INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (31, 5, 232, '4 x 4 Tiffen Black Satin 1/2 Filter', '4-x-4-tiffen-black-satin-1-2-filter', 'The 4 × 4 Tiffen Black Satin 1/2 Filter is a specialty filter that reduces overall contrast and controls highlights within a scene. Key features include:

