INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (32, 5, 232, '4 x 4 Tiffen Pearlescent 1/2 Filter', '4-x-4-tiffen-pearlescent-1-2-filter', 'The 4 × 4 Tiffen Pearlescent 1/2 Filter is a specialty filter that slightly softens and lowers contrast level while creating a pearlescent halo around highlights.  Key features include:

