INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (88, 5, 232, '4 x 5.6 Tiffen ND 0.3 Filter', '4-x-5-6-tiffen-nd-0-3-filter', 'The 4 × 5.6 ND 0.3 Filter is a high-quality glass neutral-density filter made by Tiffen. Key features include:

