INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (102, 2, 17, 'ARRI 135mm T1.9 Master Anamorphic 2x (PL)', 'arri-135mm-t1-9-master-anamorphic-2x-pl', 'The ARRI 135mm T1.9 Master Anamorphic (PL) is a premium PL-mount lens that provides a cinematic, 2x squeeze image while maximizing contrast with minimal focus breathing and fantastic color reproduction down to T1.9. Key features include:

For Super 35 sensors providing up to 29.26mm coverage
