INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (103, 5, 17, 'ARRI 15mm Lightweight Support LWS-6', 'arri-15mm-lightweight-support-lws-6', 'The ARRI 15mm Lightweight Support LWS-6 mounts to either the ARRI Lightweight Camera Handle LCH-1 or the ARRI Universal Adapter Plate UAP-3 (not included), allowing you to add two optically centered standard 15mm LWS rods to your rig, in addition to other accessories such as the Mini Viewfinder Bracket MVB-1, lens motors, or matte boxes.', 79000.0, '{"Brand":"ARRI","Item Type":"Lens Support","Lens Support Type":"Support Bracket","Mfr. Model Number":"K2.0023948"}', 'ARRI 15mm
