INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (106, 2, 17, 'ARRI 18mm T1.8 Signature Prime (LPL)', 'arri-18mm-t1-8-signature-prime-lpl', 'The ARRI 18mm T1.8 Signature Prime is a wide-angle LPL-format cine prime that can cover cameras with sensor sizes ranging from Super 35 to full-frame large-format. Key features include:

Covers sensor sizes up to full-frame large-format
Wide-angle cine prime
High-quality cine build
