INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (157, 5, 17, 'ARRI AMIRA PL LDS Lens Mount', 'arri-amira-pl-lds-lens-mount', 'The ARRI AMIRA PL LDS Lens Mount is just what the name implies, a PL lens mount with Hirose 12-pin LDS support when used on an ARRI AMIRA. Key features include:

Mount PL lenses to ARRI AMIRA cameras
Hirose 12-pin connector for LDS communication
Suitable for ENG-style lenses
