INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (163, 3, 17, 'ARRI BHA-1 Balance Harness Adapter for LCH-1', 'arri-bha-1-balance-harness-adapter-for-lch-1', 'The ARRI BHA-1 Balance Harness Adapter mounts onto the ARRI LCH-1 camera handle for the ALEXA 35 camera and provides quick camera balancing. You can slide it back and forth along the handle and secure it in place with the thumbscrew once you’ve found perfect balance. You can also mount an accessory via the adapter’s 3/8"-16 thread. Want the whole kit? We include this product alongside an entire ALEXA 35 LPL / PL package here.', 71000.0, '{"Brand":"ARRI","Camera Support Type":"Handle","Item Type":"Camera Support","Mfr. Model Number":"K2.0034554"}', 'ARRI
BHA-1
Balance
Harness
Adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (164, 3, 17, 'ARRI BP-8 19mm Studio Bridge Plate', 'arri-bp-8-19mm-studio-bridge-plate', 'The BP-8 is an ARRI standard bridge plate with 19mm studio rods spaced 104mm center-to-center, that helps to optimize the balance of a compatible camera rig. Designed for select ARRI and third party cameras, the BP-8 features two 3/8"-16 mounting screws, two location pins, a lever locking sliding plate, and a rubberized top coating to prevent twisting and ensure a secure connection to your camera base.', 179000.0, '{"Brand":"ARRI","Camera Support Type":"Baseplate","Compatibility":"Universal","Item Type":"Camera Support","Mounting Options":"Rod Standard19mm Studio / 104mm spacingCamera Mounting2x 3/8\\"-16 screw"}', 'Just the plate', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (165, 3, 17, 'ARRI BP-9 15mm Studio Bridge Plate', 'arri-bp-9-15mm-studio-bridge-plate', 'The ARRI BP-9 15mm Studio Bridge Plate works with a bottom dovetail plate (not included) to balance your camera as the weight of your rig changes. It features 15mm studio rod support for mounting a lens support or other accessories onto select ARRI and third-party cameras. However, the BP-9 is not compatible with 15mm LWS-spaced accessories.', 196000.0, '{"Brand":"ARRI","Camera Mount":"3/8\\"-16 screw","Camera Support Type":"Rod Component","Item Type":"Camera Support","Mfr. Model Number":"K2.0031435","Ports":"15mm rod port (x2)","Rod Standard":"15mm studio / 100mm spacing"}', 'ARRI
