INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (173, 3, 17, 'ARRI Compact Bridge Plate CBP-6 (15mm)', 'arri-compact-bridge-plate-cbp-6-15mm', 'The ARRI Compact Bridge Plate CBP-6 (15mm) provides a sliding bridge plate and a shoulder pad for your ALEXA 35 camera rig. It mounts onto a Balance Utility Dovetail BUD-1 and makes significant balance adjustment possible. An improved quick-release system allows you to lift the camera straight off the dovetail without having to slide off from the rear, which is particularly helpful when using longer lenses. The CBP-6 supports both 15mm LWS and 15mm studio rods.', 332000.0, '{"Brand":"ARRI","Camera Support Type":"Baseplate","Compatibility":"ARRI ALEXA 35 Camera\\nARRI BUD-1 Utility Dovetail","Item Type":"Camera Support","Mfr. Model Number":"K2.0023836","Mount":"Unknown","Ports":"2x 15mm rod port","Rod Standard":"15mm LWS\\n15mm Studio"}', 'CBP-6
