INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (174, 3, 17, 'ARRI Compact Shoulder Pad CSP-2 for ALEXA 35', 'arri-compact-shoulder-pad-csp-2-for-alexa-35', 'The ARRI Compact Shoulder Pad CSP-2 is designed to mount onto the bridge plate or baseplate of an ALEXA 35 camera, providing a comfortable rest for your shoulder. It features four short legs that raise the pad away from flat surfaces, preventing wear and tear when you set your camera rig down. Want the whole kit? We include this product alongside an entire ALEXA 35 LPL / PL package here.', 107000.0, '{"Brand":"ARRI","Camera Support Type":"Shoulder Mount","Compatibility":"ALEXA 35","Item Type":"Camera Support","Mfr. Model Number":"K2.0024161"}', 'ARRI
