INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (176, 4, 17, 'ARRI DTS Cord Control Pod w/ XLR5S Connector', 'arri-dts-cord-control-pod-w-xlr5s-connector', 'The ARRI DTS 1830C Control Pod w/ XLR5S Cable bundles the ARRI DTS Cord Control Pod with XLR5S Connect and the ARRI Mounting Bracket for DTS 1830B to effectively control volume, PGM audio, intercom functions, and more. The female XLR5S connector allows connection to a headset with a dynamic microphone, while the mounting bracket is specifically designed to attach the system to a pan bar with a diameter of up to 35mm.', 218000.0, '{"Brand":"ARRI","Cable Type":"Accessory","Item Type":"Cable"}', 'ARRI
