INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (191, 6, 17, 'ARRI Gold Mount Power Splitting Box Mk II', 'arri-gold-mount-power-splitting-box-mk-ii', 'The ARRI Gold Mount Power Splitting Box Mk II is an add-on accessory for the Alexa Mini LF that adds compatibility for Gold Mount batteries & output to 2-pin LEMO, 3-pin Fischer, 4-pin Hirose, & USB. Key features include:

Compatible with Gold Mount batteries (not included)
