INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (194, 5, 17, 'ARRI LMB 4x5 Clamp On 3-Stage Matte Box', 'arri-lmb-4x5-clamp-on-3-stage-matte-box', 'The ARRI LMB 4×5 Clamp On 3-Stage Matte Box is a modular kit offering side and top/bottom flags, filter trays, lens barrel adapters, and more for the LMB 4 × 5″ Matte Box. Key features include:

