INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (252, 6, 8, 'Anker 65W Nano II 3-Port Power Kit w/ Thunderbolt 5 Cable', 'anker-65w-nano-ii-3-port-power-kit-w-thunderbolt-5-cable', 'The Anker 65W Nano II 3-Port Power Kit w/ Thunderbolt 5 Cable bundles a 65W 3-port wall charger with a 3-foot Thunderbolt 5 cable for your charging needs. Key features include:

Easily charges power hungry devices
Two USB-C and one USB-A port
