INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (255, 6, 8, 'Anker 8-in-1 USB-C Power Strip and Charging Station', 'anker-8-in-1-usb-c-power-strip-and-charging-station', 'The Anker 8-in-1 USB-C Power Strip and Charging Station is a sleek and portable outlet expansion system designed with AC outlets, USB-C ports, and USB-A ports to supply power to a variety of devices. Key features include:

20W USB-C charging
Adjustable swivel plug
Four 3-prong AC outlets
