INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (262, 6, 9, 'Anton Bauer 26V Gold Mount Plus Plate for ARRI ALEXA 35', 'anton-bauer-26v-gold-mount-plus-plate-for-arri-alexa-35', 'The Anton Bauer 26V Gold Mount Plus Plate for ARRI ALEXA 35 mounts directly onto your ARRI ALEXA 35. Key features include:

Gold Mount plus/Gold Mount plate
Mounts directly on ARRI ALEXA 35
For AB Gold Mount Plus 26V battery
Full battery data via SMBus & Pogo Pins

For ARRI ALEXA 25 Systems. The Anton Bauer 26V Gold Mount Plus Plate for ARRI ALEXA 35 powers your ARRI ALEXA 35 through the separately rented AB Gold Mount Plus 26V battery. This Gold Mount Plus plate mounts directly on the back of your camera, saving space and weight on your rig. Full battery data is transmitted via the SMBus protocol and the plate’s pogo pins.', 136000.0, '{"Brand":"Anton Bauer","General":"Camera Power MethodBattery Plate Mount Type  Plate Front / Battery MountGold Mount Plus  Number of Battery Bays1","Item Type":"Power","Physical":"Dimensions4.7 × 3.7 × 0.9″  Weight6.3 oz","Power":"Power Input26 VDC","Power Type":"Battery Plate"}', 'Anton
