INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (263, 6, 9, 'Anton Bauer 26V Gold Mount Power Kit w/ LP4 Quad Charger', 'anton-bauer-26v-gold-mount-power-kit-w-lp4-quad-charger', 'The Anton Bauer 26V Gold Mount Plus Power Kit w/ LP4 Quad Charger is a great kit for anyone looking for more power and fast charging for their shoot. The Gold Mount Plus Batteries feature more reliable run times with on-board displays that predict your remaining power down to the minute. They also can recharge in approximately 90 minutes with the included Anton Bauer Dionic 26V LP4 Quad Gold Mount Plus Charger. Click on any of the package items below for more information.

