INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (285, 6, 9, 'Anton Bauer Dionic XT90 V-Mount Battery', 'anton-bauer-dionic-xt90-v-mount-battery', 'The Anton Bauer Dionic XT90 V-Mount Battery is a long-lasting and reliable AB V-Mount battery. Key features include:

Suitable for cinema power
12A continuous load
