INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (294, 6, 9, 'Anton Bauer Gold Mount to V-Mount Adapter', 'anton-bauer-gold-mount-to-v-mount-adapter', 'The Anton Bauer Gold Mount to V-Mount Adapter attaches directly to a camera with integrated V-mount and lets you use Anton Bauer Gold Mount batteries. Key features include:

Use Anton Bauer Gold Mount batteries on Sony V-Mount cameras
Adds three D-tap inputs
Great value
