INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (298, 6, 9, 'Anton Bauer LP4 Quad V-Mount Battery Charger', 'anton-bauer-lp4-quad-v-mount-battery-charger', 'The Anton Bauer LP4 Quad V-Mount Battery Charger is a compact simultaneous charger for up to four batteries. Key features include:

Simultaneous four-battery charging
Priority charging for quick changeover
