INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (325, 6, 9, 'Anton Bauer Titon Base Kit for USB Type-C PD Devices', 'anton-bauer-titon-base-kit-for-usb-type-c-pd-devices', 'The Anton Bauer Titon Base Kit for USB Type-C PD Devices is a package we assembled that provides Titon power to Sony, Nikon, and Canon cameras. Key features include:

68Wh 14.4V, lithium-ion battery
1/4"-20 mounting system w/ quick release
