INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (413, 1, 23, 'Atomos A-Eye 4K-20X PTZ Camera with 20x Optical Zoom', 'atomos-a-eye-4k-20x-ptz-camera-with-20x-optical-zoom', 'The Atomos A-Eye 4K-20X PTZ Camera with 20x Optical Zoom is a highly intelligent PTZ camera designed with AI tracking capabilities and a built-in 20x zoom lens. Key features include:

