INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (415, 6, 23, 'Atomos Battery Eliminator Stand Power Kit for Ninja Recorder', 'atomos-battery-eliminator-stand-power-kit-for-ninja-recorder', 'This Atomos Battery Eliminator Stand Power Kit is designed to power your Atomos Ninja V, Ninja V+, Ninja, or Ninja Ultra monitors/recorders. The battery eliminator accepts a single L-series dummy battery, and it is powered via the included locking AC adapter and DC input. Additionally, the eliminator is equipped with a kickstand, allowing you to safely prop your monitor up on a flat surface.', 82000.0, '{"Brand":"Atomos","Compatibility":"Atomos Ninja V Ninja V+ Ninja Ultra / Ninja Locking AC Adapter ATOMPWR012","DC Input Power":"6.2 to 16.8 VDC","Item Type":"Power","Mfr. Model Number":"#ATOMBES001","Mounting":"1x L-Series Dummy Battery","Power I/O":"1x Barrel Input","Power Source":"AC Input","Power Type":"Power Adapter"}', 'Atomos
