INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (419, 4, 23, 'Atomos USB-C to Serial Calibration & Control Cable', 'atomos-usb-c-to-serial-calibration-control-cable', 'The Atomos USB-C to Serial Calibration & Control Cable connects an Atomos monitor/recorder like the Atomos Ninja V to the Z CAM E2 4K Cinema Camera and other compatible Z Cam cameras to act as a control cable for the camera. This cable can also be used with the X-Rite i1 Display Pro to calibrate the Atomos monitor. This cable is not compatible with any other X-Rite devices. The cable features a USB Type-C and has a 2.5mm LANC connector on the other end. Almost every Atomos monitor has a matching 2.5mm LANC port.', 54000.0, '{"Brand":"Atomos","Cable Type":"USB, Control, and Accessory","Connector":"USB-C","Item Type":"Cable","Length":"1.0’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (420, 5, 24, 'Aurora Aperture Power XND Mark II Variable ND 105mm', 'aurora-aperture-power-xnd-mark-ii-variable-nd-105mm', 'The Aurora Aperture Power XND Mark II Variable ND 105mm is a high-quality specialty filter. Key features include:

Variable 1-7 stops of ND
High-quality, multi-coated glass
Marked for easy control over exposure settings
105mm filter thread

Variable 1-7 Stops Of ND. By simply rotating the Aurora-Aperture Power XND Mark II Variable ND 105mm filter’s ring, you can increase or decrease the ND effect.

Minimal Image Degradation. High-quality, multi-coated Schott B270 glass ensures minimal image degradation, ghosting, and reflections.

Index Points For Reference. The front ring has dots representing different density values, which help you mark your spot. A removable rotation lever lets you make fast, precise adjustments so you can recreate your desired effect.

105mm Filter Thread. This filter is designed for lenses with 105mm filter threads. It’s the standard-depth version, so do watch for vignetting on wide-angle lenses.', 111000.0, '{"Brand":"Aurora Aperture","Filter Format":"Screw-On","Filter Type":"Neutral Density","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'Filter
Filter pouch', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (421, 5, 26, 'B+W 40.5mm ND Filter (2-Stop)', 'b-w-40-5mm-nd-filter-2-stop', 'The  B+W 40.5mm ND Filter is a screw-on filter designed to add 2 stops of exposure reduction to lenses with 40.5mm front filter threads. Key features include:

Enables reduced shutter speed
0.6 optical density
MRC nano coating
Brass ring with enhanced top knurling

2-Stop ND. Designed for select telephoto lenses with a 40.5mm filter thread, the B+W 40.5mm ND Filter is a high-quality glass filter offering 2-stops of exposure reduction.

Compatibility. This filter is compatible with lenses featuring accessory threads measuring 40.5mm.

Multi-Resistant & Nano Coatings. B+W’s MRC coating protects the filter glass from light abrasion and a Nano coating makes cleaning easier with its hydrophobic properties.', 61000.0, '{"Brand":"B+W","Exposure Reduction":"2-Stop","Filter Format":"Screw-On","Filter Size":"40.5mm","Filter Type":"Neutral Density","Item Type":"Lens Support","Lens Support Type":"Filter","Mfr. Model Number":"66-1101535"}', 'B+W 40.5mm
ND
Filter (2-Stop)
LR
Filter
Pouch 4×4', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (422, 5, 26, 'B+W 95mm Circular Polarizing Filter', 'b-w-95mm-circular-polarizing-filter', 'The B+W 95mm Circular Polarizing Filter is an oversized, high-quality filter. Key features include:

Greater color and tonal saturation
Helps eliminate reflections and glare
Enhanced knurling, greaseless rotation
Thin brass rotating filter ring

Large Diameter. Not a common, widely used size, the B+W 95mm Circular Polarizing Filter is an oversized filter that’s perfect for any lens that takes 95mm filters.

Reduced Reflections. By simply rotating the filter, you can eliminate reflections from reflective surfaces. Glass, water, eyeballs, the whole lot.

Multi-Layer Coatings. This filter is coated to repel water drops and resist smudging from fingerprints and treated to prevent microscopic dust from clinging to the front surface. This helps to ensure sharp images.', 93000.0, '{"Brand":"B+W","Filter Factor":"2x (1-Stop) to 2.8x (1.5-Stop)","Filter Format":"Screw-On","Filter Type":"Polarizing","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'B+W
MRC-Nano
Master 95mm
CP
Filter
Tetrafab
LR
Filter
