INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (428, 4, 27, 'Beachtek 5-Pin XLR to 6-Pin LEMO for ALEXA Mini LF 17.7"', 'beachtek-5-pin-xlr-to-6-pin-lemo-for-alexa-mini-lf-17-7', 'The Beachtek 5-Pin XLR to 6-Pin LEMO for ALEXA Mini LF 17.7" accessory cable connects the 5-pin balanced output of the Beachtek DXA-ALEXA or DXA-CINE preamplifiers to the balanced 6-pin input on the ARRI ALEXA Mini LF, allowing professional quality audio to be fed directly into the camera. Both connectors are gold plated and are genuine LEMO and Neutrik brands.', 64000.0, '{"Brand":"Beachtek","Cable Type":"Audio","Connector":"LEMO and 5-Pin XLR","Item Type":"Cable"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (429, 4, 27, 'Beachtek XLR5F to Right-Angle 3.5mm TRS for DSMC2 17.7"', 'beachtek-xlr5f-to-right-angle-3-5mm-trs-for-dsmc2-17-7', 'This Beachtek XLR5F to Right-Angle 3.5mm TRS for DSMC2 is a 17.7-inch cable designed to run dual, balanced XLR audio from the Beachtek DXA-ALEXA Preamplifier into a RED DSMC2 camera for high-quality internal audio you won’t need to sync in post. Your RED DSMC2 camera will need to have a base expander installed to use this cable. Our DMSC2 brain rentals include the base expander.', 39000.0, '{"Brand":"Beachtek","Cable Type":"Audio and Accessory","Connector":"3.5mm TRS and 5-Pin XLR","Item Type":"Cable","Length":"1.5’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
