INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (434, 4, 28, 'Belden 150ft Cat 6A Ethernet Cable', 'belden-150ft-cat-6a-ethernet-cable', 'The Belden 150ft Cat 6A Ethernet Cable is a .265” OD, high-throughput ethernet cable with a small bend radius and uniform heat flow dissipation for demanding video applications. Key features include:

Works great for NDI and HDBaseT systems
Up to 10 Gbps transfer speed
Dual, male RJ45 connectors
100 watt PoE support

Premium Ethernet Cable. This Belden 150ft Cat 6A ethernet cable is made from high-quality, .265” OD Belden 10GXS32 cable that’s capable of transmitting up to 10 Gbps of data and 100 watts of energy in PoE applications. The cable is sleeved in heat dissipating Polyolefin with a bendable PVC outer jacket.

Male RJ45 Connectors. This is a male by male cable for connecting two devices with RJ45 female ports. If you need a male by female extension cable, check out the Belden 150ft Cat 6A Ethernet Cable Extension. Please note that long runs of cable may require a repeater. If you have questions, please contact us.

Great for NDI & HDBaseT. This cable has enough throughput for intensive video applications like NDI, NDI HX, and HDBaseT, and in some situations, removes the need for a separate power supply thanks to its compatibility with four-pair power over ethernet. It also works perfectly for simply connecting two network devices.', 104000.0, '{"Brand":"Belden","Cable Type":"Ethernet","Connector":"Ethernet","Item Type":"Cable","Length":"150.0’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (435, 4, 28, 'Belden 150ft Cat 6A Ethernet Cable Extension', 'belden-150ft-cat-6a-ethernet-cable-extension', 'The Belden 150ft Cat 6A Ethernet Cable Extension is a .265” OD, high-throughput ethernet extension cable with a small bend radius and uniform heat flow dissipation for demanding video applications. Key features include:

Male by female cable for extending ethernet runs
Up to 10 Gbps transfer speed
Male by female RJ45 connectors
100 watt PoE support

Premium Ethernet Cable. This Belden 150ft Cat 6A ethernet cable extension is made from high-quality, .265” OD Belden 10GXS32 cable that’s capable of transmitting up to 10 Gbps of data and 100 watts of energy in PoE applications. The cable is sleeved in heat dissipating Polyolefin with a bendable PVC outer jacket.

Male by Female RJ45 Connectors. This is a male by female ethernet cable for extending a male by male cable like the Belden 150ft Cat 6A Ethernet Cable. Please note that long runs of cable may require a repeater. If you have questions, please contact us.

Great for NDI & HDBaseT. This cable has enough throughput for intensive video applications like NDI, NDI HX, and HDBaseT, and in some situations, removes the need for a separate power supply thanks to its compatibility with four-pair power over ethernet.', 104000.0, '{"Brand":"Belden","Cable Type":"Ethernet and Extender","Connector":"Ethernet","Item Type":"Cable","Length":"150.0’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (436, 4, 28, 'Belden 2.6ft 179DT 12G-SDI BNC Cable', 'belden-2-6ft-179dt-12g-sdi-bnc-cable', 'The Belden 2.6ft 179DT 12G-SDI BNC Cable is an ultra-miniature, 4K-ready coax cable with Neutrik Rear TWIST BNC connectors capable of 12GHz video transmission. This version measures 2.6ft and is suited for gimbal monitoring. Key features include:

179DT ultra-miniature RG-179 coax cable
Neutrik Rear TWIST Tiny BNC connector w/ black boot
