INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (492, 3, 32, 'Blackmagic Design 15mm LWS Baseplate for URSA Cine 12K', 'blackmagic-design-15mm-lws-baseplate-for-ursa-cine-12k', 'Mount your Blackmagic Design URSA Cine 12K LF B-Mount – PL or Blackmagic Design URSA Cine 12K LF B-Mount – LPL securely on a tripod or shoulder rig with this Blackmagic Design 15mm LWS Baseplate for URSA Cine 12K. This baseplate provides you with two 15mm rod mounts and a world of rig mounting possibilities. Need access to 19mm rod mounts? Check out the Blackmagic Design 19mm Baseplate. Please note that in order to connect this baseplate to another surface, you will need access to an ARRI-standard dovetail plate.', 150000.0, '{"Brand":"Blackmagic","Camera Support Type":"Baseplate","Item Type":"Camera Support","Mounting":"Rod Standard15 mm LWS / 60 mm Spacing Battery Plate TypeNo Accessory MountingNot Specified by Manufacturer Rod Ports (2) 15 mm Rod Port Shoe MountingNo RosettesNo"}', 'Blackmagic
