INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (499, 5, 32, 'Blackmagic Design Focus Demand', 'blackmagic-design-focus-demand', 'The Blackmagic Design Focus Demand is an add-on accessory for the Blackmagic PYXIS 6K – L-Mount, PYXIS 6K – EF, PYXIS 6K – PL, Studio Camera 4K Plus, Studio Camera 4K Pro, and URSA Broadcast G2 (B4), that allows for electronic focus control of compatible servo lenses via the camera’s USB Type C ports. The rental includes a tripod handle clamp, and if you’re also renting a Blackmagic Design Zoom Demand, you’ll be able to daisy chain the devices together to leave a USB port open for external SSD recording.', 100000.0, '{"Brand":"Blackmagic","Item Type":"Lens Support","Lens Support Type":"Lens Control"}', 'Focus demand
