INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (520, 3, 32, 'Blackmagic Design URSA Broadcast ENG Kit', 'blackmagic-design-ursa-broadcast-eng-kit', 'The Blackmagic Design URSA Broadcast ENG Kit is designed to protect and expand mounting options to your URSA or URSA Mini/Mini Pro camera. Key features include:

Protects camera top vents
Rugged Run-and-Gun ENG handle
Multiple 3/8"-16 mounting points
Rotating light mount included

Run N Gun. The Blackmagic Design URSA Broadcast ENG Kit transforms your URSA or URSA Mini/Mini Pro into a Run-and-Gun style camera. This kit is essentially body armor for your camera, offering protection to the top vent from dust or wet conditions, a top handle with multiple 3/8"-16 mounting threads, a rotating light mount for attaching a light or LED, a microphone mount for capturing audio with a shotgun mic, and a side panel cradle to hold those hard-to-mount accessories like portable USB drives, wireless transmitters and receivers.', 89000.0, '{"Brand":"Blackmagic","Camera Support Type":"Shoulder Mount","General":"Item TypeTopside Handle RotationNo Built-In ControlsNone","Item Type":"Camera Support","Mounting":"Attachment MethodNot Specified by Manufacturer Accessory MountingMultiple x 3/8\\"-16 Thread Shoe MountingNone RosettesNone Rail MountingNone"}', 'Blackmagic
