INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (521, 1, 32, 'Blackmagic Design URSA Broadcast G2 OLPF Studio Kit (B4)', 'blackmagic-design-ursa-broadcast-g2-olpf-studio-kit-b4', 'We built the Blackmagic Design URSA Broadcast G2 OLPF Studio Kit (B4) for renters who need a studio-style B4 camera package, but want the flexibility to choose their own tripod and media if necessary. Click on any of the package items below for more information.

