INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (547, 5, 32, 'Blackmagic Design Zoom Demand', 'blackmagic-design-zoom-demand', 'The Blackmagic Design Zoom Demand is an add-on accessory for the Blackmagic PYXIS 6K – L-Mount, PYXIS 6K – EF, PYXIS 6K – PL, URSA Broadcast G2 Camera (B4), Blackmagic Studio Camera 4K Plus, and Pro models that allows for electronic zoom control of compatible servo lenses via the camera’s USB Type C ports. The rental includes a tripod handle clamp, and if you’re also renting a Blackmagic Design Focus Demand, you’ll be able to daisy chain the devices together to leave a USB port open for external SSD recording.', 100000.0, '{"Brand":"Blackmagic","Item Type":"Lens Support","Lens Support Type":"Lens Control"}', 'Zoom demand
