INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (554, 1, 32, 'Blackmagic Pocket Cinema Camera 6K G2 w/ Wooden PL Mount Mod', 'blackmagic-pocket-cinema-camera-6k-g2-w-wooden-pl-mount-mod', 'The Blackmagic Pocket Cinema Camera 6K G2 w/ Wooden PL Mount Mod provides a modified PL mounting system to the Pocket Cinema Camera 6K G2. Key features include:

Super35, 6K 60fps sensor
5" tilting HDR touchscreen LCD
Powered by one Sony L-Series battery
Modified with a Wooden PL mount

