INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (616, 3, 38, 'Bolin QR-BM Outdoor PTZ Mounting Base', 'bolin-qr-bm-outdoor-ptz-mounting-base', 'The Bolin QR-BM Outdoor PTZ Mounting Base is an add-on for select Bolin cameras for easy upright outdoor installation. Key features include:

Compatible with EX Gen3 series PTZ cameras
Quick-release structure
Mounts to bottom of PTZ camera
Upright installation only

The QR-BM Outdoor PTZ Mounting Base from Bolin Technology is a quick release-style plate that is rugged enough for outdoor use and offers upright installation of Bolin EX-Ultra series or EX-1000 series cameras.', 129000.0, '{"Brand":"Bolin Technology","Camera Support Type":"Baseplate","Item Type":"Camera Support"}', 'Bolin
