INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (621, 6, 39, 'Bolt PP-500DR Dual-Outlet Power Pack with Removable Battery', 'bolt-pp-500dr-dual-outlet-power-pack-with-removable-battery', 'The Bolt PP-500DR Dual-Outlet Power Pack with Removable Battery brings up to 2,700 flashes to a variety of on-camera flash brands, like Nikon, Canon, Sony, Vivitar, and more. Key features include:

