INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (627, 3, 42, 'Bright Tangerine Base Cage for Sony BURANO', 'bright-tangerine-base-cage-for-sony-burano', 'The Bright Tangerine Basic Cage for Sony BURANO bundles several plates designed to protect and add  secure mounting points to your BURANO camera. Key features include:

Easy installation with locating pins & captive screws
Multiple safety mechanisms for increased reliability on set
