INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (630, 3, 42, 'Bright Tangerine Create Shoulder Rig (VCT-14)', 'bright-tangerine-create-shoulder-rig-vct-14', 'The Bright Tangerine Create Shoulder Rig (VCT-14) is a shoulder-mount support system that offers customizable camera configurations with accessory mounting points. Key features include:

Built-in VCT-14 mount
Adjustable shoulder pad with 7.9" travel
Dual ARRI rosettes and M6 threads
