INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (639, 3, 42, 'Bright Tangerine Floating NATO Side Rail for Sony BURANO', 'bright-tangerine-floating-nato-side-rail-for-sony-burano', 'This Bright Tangerine Floating NATO Side Rail for Sony BURANO integrates into your BURANO configuration using other available Bright Tangerine accessories, like the Sliding Top Handle or NATO Cheese Plate. The rail provides you with two 1/4"-20 captive mounting screws and several 1/4"-20 and 3/8"-16 threads for ample accessory mounting, while a safety release button glides your accessories on and off in a breeze.', 82000.0, '{"Brand":"Bright Tangerine","Camera Support Type":"Rod Component","Item Type":"Camera Support"}', 'Bright
