INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (658, 3, 42, 'Bright Tangerine Sliding Top Handle', 'bright-tangerine-sliding-top-handle', 'The Bright Tangerine Sliding Top Handle is designed for use with select cameras and accessories. Key features include:

