INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (725, 6, 49, 'Canon AC-E6N AC Adapter w/ DR-E6 DC Coupler', 'canon-ac-e6n-ac-adapter-w-dr-e6-dc-coupler', 'The Canon AC-E6N AC Adapter with DR-E6 DC Coupler is a kit designed to provide continuous power to a number of Canon EOS DSLRs.

This adapter works with:

Canon EOS R and its BG-E22 Battery Grip
	Canon 5D Mark IV and its BG-E20 Battery Grip
