INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (726, 3, 49, 'Canon AD-E1 Multi-Function Shoe Adapter', 'canon-ad-e1-multi-function-shoe-adapter', 'The Canon AD-E1 Multi-Function Shoe Adapter lets you use legacy shoe-mounted accessories on Canon cameras that feature the Canon Multi-Function Shoe. This adapter is great for Speedlites, shotgun mics, on-camera lights, and other accessories. It boasts a weather-sealed design and gives you a secure connection to the Multi-Function Shoe via dual-locking pins.

