INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (803, 6, 49, 'Canon DR-E6C DC Coupler', 'canon-dr-e6c-dc-coupler', 'This Canon DR-E6C DC Coupler is compatible with select Canon digital cameras. It provides 9V/3A minimum voltage to your camera.

