INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (805, 5, 49, 'Canon Drop-In Clear Filter A for EF-EOS R Adapter', 'canon-drop-in-clear-filter-a-for-ef-eos-r-adapter', 'Designed for use with the Canon Drop-In Filter Mount Adapter EF-EOS R, this Drop-In Clear Filter A is a simple clear protective filter used to guard the interior of the camera body and rear element of the lens when the lens adapter is in use.

The Canon Drop-In Clear Filter A for EF-EOS R Adapter is a simple clear protective filter designed for use with the Canon EF-EOS R Drop-In Variable ND and Canon EF-EOS R Drop-In Circular Polarizer Mount Adapters. It’s generally used when you have the adapter installed but don’t want to use any filter effects.', 82000.0, '{"Brand":"Canon","Filter Format":"Drop-In","Filter Type":"Clear","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'Just the filter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (806, 5, 49, 'Canon Drop-In PL-C 52 (WIII) Circular Polarizing Filter', 'canon-drop-in-pl-c-52-wiii-circular-polarizing-filter', 'The Canon Drop-In PL-C 52 (WIII) Circular Polarizing Filter is the latest iteration of the Canon Drop-in Polarizing Filter.  While Canon doesn’t specify any change in optical performance, the paint color of the filter holder itself has been updated to match the latest generation 400mm f/2.8L IS III and 600mm f/4L IS III lenses. Like the previous version of the Drop-In CP, it features the same dial on top that allows for quick adjustment of polarization.', 114000.0, '{"Brand":"Canon","Filter Format":"Drop-In","Filter Type":"Polarizing","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'Just the filter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (807, 5, 49, 'Canon Drop-in Polarizing Filter (WII)', 'canon-drop-in-polarizing-filter-wii', 'This is the drop-in polarizing filter specifically for use in the Canon L-series super telephoto lenses.  Unlike the other Canon Drop-in filters,  it features a dial on top that allows for quick adjustment of polarization.', 100000.0, '{"Brand":"Canon","Filter Format":"Drop-In","Filter Type":"Polarizing","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'Just the filter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (808, 5, 49, 'Canon EF Extender 1.4x III', 'canon-ef-extender-1-4x-iii', 'The Canon EF Extender 1.4x III is a popular teleconverter.  Key features include:

Improved Optical Performance
Integrated Processor
Fluorine Coating

High Quality Optics. The Canon 1.4x Teleconverter III features three groups of seven elements that ensure improved optical performance. All optical elements use Canon’s super-spectra coating, which reduces ghosting and flare to minimize post-processing requirements and a fluorine coating on the front and rear elements makes smudge marks much easier to clean.

Full Electronic Pass-Through. The extender features an integrated processor which ensures all focusing, metering, and ID information is available. Canon claims that, when combined with the range of premium Canon L-series lenses, these extenders enable higher AF accuracy.', 111000.0, '{"Brand":"Canon","Camera Mount":"Canon EF","Dimensions":"2.8″ × 1.1″ (ø x L)","Groups/Elements":"3/7","Item Type":"Lens Support","Lens Mount":"Canon EF","Lens Support Type":"Teleconverter","Light Loss":"1 Stop","Maximum Magnification":"1.4x","Mfr. Model Number":"4409B002","Weight":"7.9 oz"}', '1.4x
TC
III
