INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (820, 2, 49, 'Canon EF-S 15-85mm f/3.5-5.6 IS USM', 'canon-ef-s-15-85mm-f-3-5-5-6-is-usm', 'The Canon EF-S 15-85mm f/3.5-5.6 IS USM is a standard zoom lens designed for crop-frame Canon DSLRs, such as the 7D Mark II, and 80D. Key features include:

