INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (825, 2, 49, 'Canon EF-S 18-55mm f/3.5-5.6 IS STM', 'canon-ef-s-18-55mm-f-3-5-5-6-is-stm', 'The Canon EF-S 18-55mm f/3.5-5.6 IS STM is a normal-range kit lens designed for Canon’s crop-frame cameras. Key features include:

