INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (828, 2, 49, 'Canon EF-S 55-250mm f/4-5.6 IS STM', 'canon-ef-s-55-250mm-f-4-5-6-is-stm', 'The Canon EF-S 55-250mm f/4-5.6 IS STM is a consumer-grade telephoto zoom lens designed for use with Canon crop-sensor cameras like the T7i and 80D.  Key features include:

3.5-stop image stabilization
