INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (835, 1, 49, 'Canon EOS C300 Mark III (Locking EF-C)', 'canon-eos-c300-mark-iii-locking-ef-c', 'The Canon EOS C300 Mark III (Locking EF-C) is a cinema-quality camera with a Super 35 Dual Gain Output sensor that is capable of recording Canon Cinema RAW Light to dual CFexpress media slots. Key features include:

Super 35mm dual gain output CMOS sensor
Internal, 10-bit Canon RAW Light to dual CFexpress slots
Canon Log 2 and 3 Gammas
Netflix approved cameras

