INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (840, 1, 49, 'Canon EOS C50 Full-Frame Cinema Camera (RF)', 'canon-eos-c50-full-frame-cinema-camera-rf', 'Featuring a newly developed 7K full-frame CMOS sensor, the Canon EOS C50 Cinema Camera is a compact powerhouse for your video and photo needs. The EOS C50 is capable of recording 3:2 Open Gate video at 4K120 and raw video up to 7K60, as well as 32MP stills in photo mode. Simply select between dedicated photo and video modes for an intuitive hybrid shooting experience. Additional advanced features of the C50 include Dual-Pixel CMOS AF II, simultaneous 2K crop recording, built-in Frame.io Camera-to-Cloud integration, and XC protocol support for remote control. This is a Netflix approved camera!

Key features include:

7K FF Back-Illuminated CMOS Sensor
	7K 3:2 Open Gate, UHD 4K120, 2K180
	Dual-Base ISO: 800 and 6400
	Netflix approved camera', 857000.0, '{"Brand":"Canon","Camera Mount":"Canon RF","Camera Type":"Mirrorless and Cinema","Compatible Media":"CFexpress Type B and SD","Item Type":"Camera","Maximum Video Resolution":"7K","Screen Type":"Touchscreen and Swivel","Sensor Size":"Full-Frame","Stabilization":"No","Weather Sealing":"Yes","Wireless Connectivity":"Wi-Fi"}', 'Canon
