INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (844, 1, 49, 'Canon EOS C500 Mark II Premium Kit (Locking EF-C)', 'canon-eos-c500-mark-ii-premium-kit-locking-ef-c', 'The Canon EOS C500 Mark II Premium Kit (EF-C) provides you with a cinema-quality camera package that’s ready to shoot with just the addition of a lens and is well suited for narrative, commercial, or documentary work. This kit includes a locking EF-C mount camera, expansion unit, V-Mount battery, battery charger, media, and media reader to get you from zero to shooting in a matter of minutes. Click on any of the package items below for more information. This is a Netflix approved camera!

