INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (870, 1, 49, 'Canon EOS R6 Mark II w/ Stop Motion Animation Firmware', 'canon-eos-r6-mark-ii-w-stop-motion-animation-firmware', 'The Canon EOS R6 Mark II w/ Stop Motion Animation Firmware is a version of the EOS R6 II with pre-installed firmware that optimizes the camera for creating stop-motion animation when used in conjunction with speciality software. Key features include:

Optimized for stop-motion animation
Aperture-lock and focus-position memory
24.2MP full-frame CMOS sensor; DIGIC X processor
4K60p 10-bit internal video; external 6K60p ProRes RAW

