INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (881, 5, 49, 'Canon ET-74B Lens Hood for EF 70-300mm / RF 100-400mm', 'canon-et-74b-lens-hood-for-ef-70-300mm-rf-100-400mm', 'The ET-74B Lens Hood is compatible with the Canon EF 70-300mm f/4-5.6 IS II and the Canon RF 100-400mm f/5.6-8 IS. It helps minimize flare by deflecting stray light from entering the lens. The hood also provides additional protection to the lens from accidental impacts, bumps, or scratching.', 54000.0, '{"Brand":"Canon","General":"Compatible LensesCanon EF 70-300mm f/4-5.6 IS IICanon RF 100-400mm f/5.6-8 ISDimensions (ø x L)3.1 × 3.9″MountingAttaches to front of lensMfr. Model Number 0578C001Weight2.05 oz.","Item Type":"Lens Support","Lens Support Type":"Hood"}', 'Canon
