INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (896, 3, 49, 'Canon HDU-2 Handle Unit for EOS C200', 'canon-hdu-2-handle-unit-for-eos-c200', 'The Canon HDU-2 Handle Unit for EOS C200 mounts to your Canon EOS C200 via a custom-made handle screw and gives you mounting positions for an LCD viewfinder setup and microphone. We have this camera available in both PL and EF mounts!', 93000.0, '{"Brand":"Canon","Camera Support Type":"Handle","Item Type":"Camera Support"}', 'Canon
