INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (897, 3, 49, 'Canon HG-100TBR Tripod Grip', 'canon-hg-100tbr-tripod-grip', 'The Canon HG-100TBR Tripod Grip is an accessory grip for handheld shooting that also doubles as a compact tabletop tripod. We now carry the improved HG-200TBR Tripod Grip at a similar price point! Key features include:

Larger, more comfortable grip when shooting hand-held
Doubles as a tabletop tripod
Includes a remote shutter release
For select Canon EOS M, EOS R, and PowerShot G cameras

Improved Stability and Convenience. The Canon HG-100TBR Tripod Grip provides a larger, more comfortable grip when shooting hand-held. Its integrated head has a tilting design for easy positioning at different angles and attaches to your camera via 1/4"-20 mount.

Tabletop Tripod. In addition to being a more comfortable accessory grip, the HG-100TBR doubles as a sleek, durable tabletop tripod for hands-free shooting.

Remote Shutter Release Included. This rental includes the Canon BR-E1 Remote Shutter Release, which fits into the HG-100TBR grip and allows you to wirelessly release your camera’s shutter via Bluetooth from within a sixteen-foot operating range. It has low power consumption and requires no line of sight to the camera.', 82000.0, '{"Brand":"Canon","Camera Mount":"1/4\\"-20 Male","Camera Support Type":"Tripod and Shutter Release","Depth":"1.7\\"","Height":"1.5\\"","Item Type":"Camera Support","Mfr. Model Number":"4157C001","Width":"7.5\\""}', 'Canon
HG-100TBR
Tripod
Grip
Canon
BR-E1
Remote
Shutter
Release', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (898, 3, 49, 'Canon HG-200TBR Tripod Grip', 'canon-hg-200tbr-tripod-grip', 'The Canon HG-200TBR Tripod Grip is an intuitive and lightweight grip designed for use with select Canon cameras, and a direct update to the HG-100TBR Tripod Grip. Key features include:

Detachable BR-E2 remote
Control power zoom and focus
16.4-foot operating range
Hybrid grip and fold-out mini tripod duo

Holy Handheld! Take the next step in expanding your on-the-go camera kit with this Canon HG-200TBR Tripod Grip! Designed for use with select Canon cameras, this accessory is equipped with a comfortable and ergonomic handheld grip, and can also be folded out to a tabletop tripod. Want to mount a mic, but don’t know where to do so? The HG-200TBR features L and S microphone brackets!

Integrated Remote Control. On the front end of this grip, you’ll find the detachable BR-E2 remote for controlling power zoom, focus, start/stop, exposure compensation, and take photos from just over 16-feet away. With two assignable buttons, you can customize your experience even further!', 89000.0, '{"Brand":"Canon","Camera Attachment":"1/4\\"-20 Male","Camera Support Type":"Controller","Dimensions":"7.5 × 1.7 × 1.5″","Item Type":"Camera Support","Mfr. Model Number":"7497C001","Weight":"0.4 lb."}', 'Canon
HG-200TBR
Tripod
Grip
Canon
BR-E2
Remote
Shutter
Release', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (899, 6, 49, 'Canon LC-E17 Charger', 'canon-lc-e17-charger', 'The LC-E17 Battery Charger doesn’t need a power cord. Simply plug it directly into a standard electrical outlet to charge your LP-E17 battery.

This is Canon’s standard-issue charger for:

Canon EOS R100
	Canon EOS R10
	Canon EOS R8
	Canon EOS RP and its EG-E1 Extension Grip
	Canon EOS M6 Mark II
	Canon T7i
	Canon 77D
	Canon PowerShot V1', 57000.0, '{"Brand":"Canon","Item Type":"Power","Power Type":"Charger"}', 'Just the charger', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (900, 6, 49, 'Canon LC-E19 Battery Charger', 'canon-lc-e19-battery-charger', 'The Canon LC-E19 charges up to two LP-E19 batteries simultaneously. Key features include:

Designed for the Canon EOS 1DX Mark II
Charges two batteries at once
Backwards compatible with Canon LP-E4 batteries

Twin Charger. The Canon LC-E19 is the twin battery charger for the LP-E19 battery. A charger is included with the rental of the Canon EOS 1DX Mark II camera, but we offer this item as a spare charger option.

Required for LP-E19 Batteries. This is the only charger compatible with the 1DX II’s LP-E19 battery. Unless you have (or rent) this charger, you won’t be charging that battery.

Backwards Compatibility. The LC-E19 is backwards-compatible with previous-generation 1D-series batteries like the LP-E4 and LP-E4N.', 139000.0, '{"Brand":"Canon","Item Type":"Power","Power Type":"Charger"}', 'Charger
Non-polarized cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (901, 6, 49, 'Canon LC-E6 Battery Charger', 'canon-lc-e6-battery-charger', 'The LC-E6 Battery Charger from Canon is designed for use with the for LP-E6 battery pack, which powers the Canon EOS 5D Mark II, 5D Mark III, 7D, and 60D Digital SLR cameras.

The LC-E6 Battery Charger doesn’t need a power cord. Simply plug it directly into a standard electrical outlet to charge your LP-E6, LP-E6N, and LP-EL batteries.

It’s Canon’s standard-issue charger for:

Canon EOS R7
	Canon EOS R5 Mark II and its LP-E6P Battery
	Canon EOS R5 C
	Canon EOS R5 / R6 and their BG-R10 Battery Grip
	Canon 5D Mark IV and its BG-E20 Battery Grip
	Canon 5D Mark III / 5DS / 5DS R and their BG-E11 Battery Grip
	Canon 5D Mark II and its BG-E6 Battery Grip
	Canon 6D Mark II and its BG-E21 Battery Grip
	Canon BG-E13 Battery Grip
	Canon 7D Mark II and its BG-E16 Battery Grip
	Canon 7D and its BG-E7 Battery Grip
	Canon 80D and its BG-E14 Battery Grip
	Canon 90D
	Canon XC15 / XC10
	Canon Speedlite EL-1 and its LP-EL Battery', 71000.0, '{"Brand":"Canon","Item Type":"Power","Power Type":"Charger"}', 'Just the charger', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
