INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (915, 3, 49, 'Canon OU-700 Remote Operation Unit for C700', 'canon-ou-700-remote-operation-unit-for-c700', 'The Canon OU-700 Remote Operation Unit for C700 is a lightweight interface solution for the Canon EOS C700 EF/C700 PL/C700 GS PL Cinema Cameras. Key features include:

