INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (918, 5, 49, 'Canon PL to RF Lens Mount Adapter for EOS C400 / C80', 'canon-pl-to-rf-lens-mount-adapter-for-eos-c400-c80', 'The Canon PL to RF Lens Mount Adapter for C400/C80 will pair an ARRI PL-mount lens to an RF-mount C400 or C80 camera and will maintain Cooke /i Technology metadata from compatible lenses. Key features include:

