INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (993, 3, 49, 'Canon RS-60E3 Remote Shutter Release', 'canon-rs-60e3-remote-shutter-release', 'The Canon RS-60E3 Remote Shutter Release is designed for entry-level and consumer-grade Canon DSLRs and compacts. Key features include:

2.0’ cable release
Canon E3 connection

