INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (995, 3, 49, 'Canon TC-80N3 Timer Remote Shutter Release', 'canon-tc-80n3-timer-remote-shutter-release', 'The Canon TC-80N3 Timer Remote Control is a remote switch with an 80cm/2.6ft. cord and a self-timer, interval timer, long-exposure timer, and exposure-count setting feature.

The timer can be set anywhere from 1 sec. to 99 hrs. A dial enables you to easily enter the numeric settings with a single thumb. The LCD panel can also be illuminated.', 68000.0, '{"Brand":"Canon","Camera Support Type":"Shutter Release","Item Type":"Camera Support"}', 'Remote
