INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1000, 2, 49, 'Canon TS-E 90mm f/2.8', 'canon-ts-e-90mm-f-2-8', 'The Canon TS-E 90mm f/2.8 is a standard-format, tilt-shift lens. Key features include:

Incredibly sharp images
Independently rotating tilt and shift axes
