INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1042, 3, 52, 'Cartoni Red Lock 3-Tube Aluminum Tripod (100mm)', 'cartoni-red-lock-3-tube-aluminum-tripod-100mm', 'This Cartoni Red Lock 3-Tube Aluminum Tripod (100mm) can withstand up to 132.3 pounds of gear and offers a 100mm bowl base. Key features include:

