INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1045, 5, 53, 'Celestron EclipSmart Solar Filter for 6-inch SCTs', 'celestron-eclipsmart-solar-filter-for-6-inch-scts', 'The Celestron EclipSmart Solar Filter for 6-inch SCTs uses Solar Safe technology that allows you to view the Sun safely through your Celestron NexStar. Key features include:

Attaches to telescope with hook-and-loop straps
Ideal for viewing eclipses, sunspots, or the Sun
Orange tint
Solar Safe film covering

Total Eclipse of the Heart. Strap this Celestron EclipSmart Solar Filter for 6-inch SCTs to the front of your Celestron NexStar for safe viewing of the sun, eclipses, and sunspots. A Solar Safe film designed for this filter protects your and your telescope, and conforms to the ISO 12312-2:2015(E) international safety standard for filters. This filter attaches to the NexStar with included hook-and-loop straps.', 39000.0, '{"Brand":"Celestron","Diameter":"7.24\\"","Filter Format":"Telescope","Filter Type":"Solar","Item Type":"Lens Support","Lens Support Type":"Filter","Mfr. Model Number":"94243"}', 'Celestron
