INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1053, 4, 55, 'Chrosziel 12-Pin to 20-Pin Hirose M-M Power and Data Cable', 'chrosziel-12-pin-to-20-pin-hirose-m-m-power-and-data-cable', 'The Chrosziel 12-Pin to 20-Pin Hirose M-M Power and Data Cable is a thin, 23.6-inch cable designed to facilitate power and data functions for Fujinon XK and ZK lenses. One end of this cable features a 20-Pin Hirose connector that plus into to the lensport of the lens, and features a 12-Pin Hirose connector on the opposite end.', 146000.0, '{"Brand":"Chrosziel","Cable Length":"23.6\\"","Cable Type":"Power","Color":"Black","Compatibility":"FUJINON XK Lenses / YK Lenses","Connector":"Hirose","Item Type":"Cable","Mfr. Model Number":"CAB-LP-FJN20"}', 'Chrosziel 12-Pin to 20-Pin
