INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1054, 6, 55, 'Chrosziel 12V D-Tap to 5-Pin Right-Angle Power Cable', 'chrosziel-12v-d-tap-to-5-pin-right-angle-power-cable', 'Power your MagNum, Aladin MKII, AL2-INTF, or CDM-MK-Z series FIZ unit using this Chrosziel 12V D-Tap to 5-Pin Right-Angle Power Cable. The cable features a right-angle 5-pin LEMO-type connector on one end and a D-Tap connector on the other end and provides 12V power from a D-Tap source, such as a professional V-mount or Gold mount battery, to your FIZ unit.

