INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1057, 4, 55, 'Chrosziel Servo Drive Control Y-Cable for Sony FX6', 'chrosziel-servo-drive-control-y-cable-for-sony-fx6', 'The Chrosziel Servo Drive Control Y-Cable for Sony FX6 is an add-on accessory for the Sony FX6 Full-Frame Cinema Camera that enables servo lens control. The Y end of the cable features two connectors- a 3.5mm camera side and a 2.5mm LANC side, for use with the Chrosziel Zoomer Universal Servo Drive Motor- with the opposite end featuring a 3.5mm female connector. This side connects to a servo controller or the FX6 handgrip.', 82000.0, '{"Brand":"Chrosziel","Cable Type":"Control and Accessory","Connector":"3.5mm","Item Type":"Cable","Length":"1.1’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1058, 4, 55, 'Chrosziel Servo Multi/3.5mm LANC Y-Cable for Sony PXW-FX9', 'chrosziel-servo-multi-3-5mm-lanc-y-cable-for-sony-pxw-fx9', 'The Chrosziel Servo Multi/3.5mm LANC Y-Cable for Sony PXW-FX9 is an add-on accessory for the Sony PXW-FX9 XDCAM 6K Full-Frame Camera that enables servo lens control. The Y end of the cable features two connectors- a Sony Multiport camera side and a 2.5mm LANC side, for use with the Chrosziel Zoomer Universal Servo Drive Motor- with the opposite end featuring a  female Sony Multiport connector. This side connects to a servo controller or the FX9 handgrip.', 86000.0, '{"Brand":"Chrosziel","Cable Type":"Control and Accessory","Connector":"3.5mm","Item Type":"Cable","Length":"1.1’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1059, 5, 55, 'Chrosziel Zoom Motor Unit for Sony FR7', 'chrosziel-zoom-motor-unit-for-sony-fr7', 'This Chrosziel Zoom Motor Unit mounts to the bottom of your Sony FR7 to give you more precise control over the attached lens. Key features include:

Only for Sony FR7 PTZ camera
Controls lens zoom
Mounts via 15mm rod clamp
RJ45 connector

Compact Zoom Control. Quickly and easily enable zoom control of the lens attached to your Sony FR7 PTZ Camera with this compact Chrosziel Zoom Motor Unit. This motor is compatible with a wide range of cine zoom lenses thanks to the adjustable Flexi gear ring, which can expand from 60mm to 120mm.

How To Mount. Using the two 15mm rods included with the FR7, simply attach the motor to the camera with the rod clamp located at the bottom of the motor.

Ports and Connectors. As for connecting the technology, this device uses an RJ45 connector that plugs right into the FR7’s option port, while the built-in power input sources fuel the motor straight from the camera.', 454000.0, '{"Brand":"Chrosziel","Item Type":"Lens Support","Lens Support Type":"Lens Control","Mounting":"1 × 15mm Rod Mount","Power":"Power SourcePlug-In Power DC Input Power19.5 VDC Power Consumption10 W","Video I/O":"1 x RJ45 Input"}', 'Chrosziel
