INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1117, 6, 61, 'Core SWX Helix Max 98Wh 2-Battery and Charger Kit (B-Mount)', 'core-swx-helix-max-98wh-2-battery-and-charger-kit-b-mount', 'The Core SWX Helix Max 98Wh 2-Battery and Charger Kit (B-Mount) consists of two Core SWX Helix Max B-Mount Batteries and a Core SWX GPM-X2B Mini Dual Travel B-Mount Battery Charger. Key features include:

