INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1123, 4, 74, 'D''Addario Right Angle Flat Patch Cable 4-Inch', 'd-addario-right-angle-flat-patch-cable-4-inch', 'The D’Addario Right Angle Flat Patch Cable 4-Inch is designed to bridge two guitar or bass pedals together, keeping pedalboard setups compact. The 4-inch cable provides just enough length to comfortably connect two pedals, while the right angle connectors maximize pedalboard space and securely attach to each pedal. This cable has low capacitance and noise-rejecting shielding, meaning the cable will transmit the sound clearly without distortion and with minimal loss of quality.', 18000.0, '{"Brand":"D’Addario","Cable Type":"Audio and Accessory","Connector":"TS","Item Type":"Cable","Length":"0.5’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1124, 4, 238, 'D-Tap to 12-pin Hirose Adapter Cable for B4 Lens', 'd-tap-to-12-pin-hirose-adapter-cable-for-b4-lens', 'The D-Tap to 12-Pin Hirose Adapter Cable is a 15.5-inch cable that lets you power B4 lenses via a D-Tap connection.

If you’re looking to use your B4 lens with our MTF B4 Lens to Sony E-Mount Camera Adapter Kit, this is the cable you’ll need to provide power to the lens so that you can use the zoom servo rocker switch. It’s also compatible with the Canon 17-120mm EF and 17-120mm PL lenses we carry.', 82000.0, '{"Brand":"Unknown","Cable Type":"Power, Adapter, and Accessory","Connector":"D-Tap and Hirose","Item Type":"Cable","Length":"1.4’","Mfr. Model Number":"MTB4DTAP"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1125, 4, 94, 'D-Tap to D-Tap Cable - 3ft', 'd-tap-to-d-tap-cable-3ft', 'The D-Tap to D-Tap Cable – 3ft is a power cable for Anton Bauer D-Tap type devices.

If you’re looking to power the ATOMOS Ninja Assassin 4K HDMI Video Recorder via D-tap power source, this is the cable you’ll need. It offers two male D-Tap connections that plug into the battery source on one end and into the D-Tap DC power adapter that’s included with the Shogun on the other.', 43000.0, '{"Brand":"General Brand","Cable Type":"Power, Adapter, and Accessory","Connector":"D-Tap","Item Type":"Cable","Length":"3.0’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
