INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1133, 6, 68, 'DJI 65W USB Charger for Mavic 3', 'dji-65w-usb-charger-for-mavic-3', 'The DJI 65W USB Charger for Mavic 3 is a compact, 65W charger designed to charge two Mavic 3 Flight Batteries, a flight battery and RC Pro controller, or any USB compatible mobile devices. Charging a Mavic 3 battery in just an hour and 36 minutes, and an RC Pro controller in an hour and 30 minutes, this charger also provides a USB Type-C and a USB Type-A port.', 82000.0, '{"Brand":"DJI","General":"CompatibilityDJI Mavic 3 USB I/O1 x USB-C Female Output1 x USB-A Female Output","Item Type":"Power","Operating Temperature":"41 to 104°F","Power":"Power SourceAC Input (Included) AC Input Power100 to 240 VAC, 50 / 60 Hz at 2 A","Power Type":"Charger"}', 'DJI 65W
