INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1142, 2, 68, 'DJI Action 6 Macro Lens', 'dji-action-6-macro-lens', 'The DJI Action 6 Macro Lens is a lens adapter that is compatible with the DJI Osmo Action 6 and produces a much closer focusing distance of down to 4.3" compared to the 13.8" of the native lens alone. It is splash resistant but not waterproof, so it is not meant for underwater use. To use it, you must unscrew the lens cover on the Action 6 and replace it with this lens adapter. Subject Tracking will not work when using this lens.', 89000.0, '{"Brand":"DJI","Dimensions":"1.8 × 1.8″ (ø x L)","Focus Type":"Manual Focus Only","Item Type":"Lens","Lens Mount":"Add-on","Lens Type":"Macro, Ultra Wide Angle, and For Mirrorless","Maximum Aperture":"2.0","Mfr. Model Number":"CP.OS.00000522.02","Minimum Focusing Distance":"4.3-29.5\\"","Stabilization":"No","Weather Sealing":"No","Weight":"0.01 lb.","Zoom Type":"Fixed Focal Length"}', 'DJI
