INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1146, 6, 68, 'DJI BG21 Grip for RS 3 Gimbal', 'dji-bg21-grip-for-rs-3-gimbal', 'The DJI BG21 Grip is an add-on accessory for the DJI RS 3 gimbal. It extends the gimbal’s handle and houses an integrated 3000 mAh Li-ion battery that provides up to 12 hours of operation, and supports the 18W PD fast-charging protocol via its USB Type-C charging port. If you use a charger that takes advantage of the aforementioned protocol (not included), you can fully charge the battery in about 2.5 hours.', 68000.0, '{"Battery":"Rated Capacity3000 mAhRated Energy21 WhNominal Voltage7.2 VVoltage Range6 to 8.4 VBattery MaterialLithium-ionBattery TypeNon-universalBattery Quantity1","Brand":"DJI","Fast Charging Type":"PD protocol","Interface":"USB Type-C charging port (Input: 5 V/2 A, 9 V/2 A, 12 V/1.5 A)","Item Type":"Power","Mfr. Model Number":"CP.RN.00000226.01","Power Type":"Battery Grip and Battery"}', 'DJI
