INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1157, 6, 68, 'DJI Extreme Battery', 'dji-extreme-battery', 'The DJI Extreme Battery is a lithium-ion polymer battery with a capacity of 1770mAh/6.81Wh and a power output of 3.85V. It’s capable of powering your Osmo Action 6, Action 5 Pro, Action 4, or Action 3 for 160 minutes and can be charged in-camera or with an optional charger.', 32000.0, '{"Battery Capacity":"1770 mAh / 6.81 Wh","Battery Life":"160 minutes","Brand":"DJI","Compatibility":"DJI Osmo Action 3","Dimensions":"1.7 × 1.4 × 0.5″","Item Type":"Power","Mfr. Model Number":"CP.OS.00000229.01","Operating Temperature":"-4 to 113°F","Output Voltage":"3.85 VDC","Power Type":"Battery"}', 'DJI
