INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1159, 6, 68, 'DJI Extreme Battery Plus', 'dji-extreme-battery-plus', 'The DJI Extreme Battery Plus a high-capacity, lithium-ion battery designed to power your Osmo Action 6, Action 5 Pro, Action 4, Action 3, or Osmo 360 for up to 4 hours, or up to 3.6 hours in temperatures down to -4°F. The battery can be charged inside of the camera with a USB-C cable in about 30 minutes!', 54000.0, '{"Battery":"Battery ChemistryLithium-Ion Battery Capacity1950 mAh / 7.55 Wh Output Voltage3.87 VDC Cells1 Charging Power4.45 VDC Recharge Time15 to 30 Minutes Maximum Battery Life240 Minutes","Brand":"DJI","Camera Compatibility":"DJI Osmo Action 5 / Osmo Action 4 (Requires Firmware Update) / Osmo Action 3 (Requires Firmware Update)","Item Type":"Power","Physical":"Charging Temperature -4 to 113°F Dimensions1.7 × 1.4 × 0.5″ Weight1.2 oz","Power Type":"Battery"}', 'DJI
