INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1174, 6, 68, 'DJI Intelligent Flight Battery for Avata 360', 'dji-intelligent-flight-battery-for-avata-360', 'This add-on DJI Intelligent Flight Battery is the designated lithium-ion power option for the Avata 360 w/ RC 2, offering a 2700mAh power capacity and 23 full minutes of flight time per charge.', 79000.0, '{"Battery Capacity":"2700 mAh / 38.67 Wh","Battery Chemistry":"Lithium-Ion","Brand":"DJI","Compatibility":"DJI Avata 360","Item Type":"Power","Maximum Flight Time":"23 Minutes","Mfr. Model Number":"CP.FP.00000306.01","Operating Temperature":"41 to 104°F","Power Type":"Battery","Weight":"5.3 oz"}', 'DJI
