Osmo', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1186, 6, 68, 'DJI Multifunctional Battery Case for Extreme Battery', 'dji-multifunctional-battery-case-for-extreme-battery', 'The DJI Multifunctional Battery Case stores and charges three separately available DJI Extreme Batteries. It can be powered via USB-C cable by an external power source for fast charging of three batteries simultaneously, and using the same port it can also serve as a power bank to power other devices. The case also features slots for storing two microSD cards.', 75000.0, '{"Battery Bays":"3","Brand":"DJI","Compatibility":"DJI Extreme Battery","Dimensions":"4.6 × 2.3 × 0.9″","Inputs/Outputs":"USB-C Female I/O (x1)","Item Type":"Power","Mfr. Model Number":"CP.OS.00000230.01","Power Source":"USB (not included)","Power Type":"Charger","Weight":"0.2 lb."}', 'DJI
