INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1191, 5, 68, 'DJI ND Filter Set for Mini 4 Pro (ND16, ND64, ND256)', 'dji-nd-filter-set-for-mini-4-pro-nd16-nd64-nd256', 'The DJI ND Filter Set for Mini 4 Pro (ND16, ND64, ND256) is designed to help you capture flawless footage with your DJI Mini 4 Pro, even on the brightest of days. Each filter provides a different strength of light reduction, the higher the number the stronger the stop. The ND16 filter offers 4-stops of light reduction, ND64 offers 6-stops, and ND265 offers 8-stops.', 61000.0, '{"Brand":"DJI","Filter Format":"Drone/Action","Filter Type":"Neutral Density","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'DJI
