Controller
Strap (2)', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1199, 3, 68, 'DJI Osmo Action Mini Handlebar Mount', 'dji-osmo-action-mini-handlebar-mount', 'Using the DJI Osmo Action Mini Handlebar Mount allows you to attach your Osmo Action 3 or Osmo Action 4 camera to the handlebars of your bike and captures those angled, in focus action shots. This ball head mount rotates 360 degrees and securely attaches to your bike with the handlebar clamp.', 46000.0, '{"Brand":"DJI","Camera Support Type":"Ball Head","General":"Dimensions 2.4 × 2.4 × 1.09″ Weight3.3 oz","Item Type":"Camera Support","Mounting":"Accessory MountBall HeadQuick Release Plate","Pan and Tilt":"Pan360°TiltYes"}', 'DJI
