INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1226, 6, 68, 'DJI Ronin BG30 Grip', 'dji-ronin-bg30-grip', 'The DJI Ronin BG30 Grip is an add-on accessory for the DJI RS 2 / RS 2 Gimbal Stabilizer Pro Combo / DJI RS 3 Pro Gimbal Stabilizer Combo / DJI RS 3 Pro Gimbal Stabilizer. The grip houses an integrated 1950 mAh LiPo battery that provides up to 12 hours of operation, and supports fast charging protocols 24W PD and QC2.0 via its USB Type-C charging port.  Using a charger that takes advantage of the aforementioned protocols (not included), the battery can be charged from 0 to 80% in roughly one hour / fully charged in 1.5 hours. While this standard battery grip gets the job done, we do have the higher-capacity, longer-running RS GB70 Battery Grip available!', 79000.0, '{"Battery":"15.4 V (12 to 17.6 V)LiPo 4S1950 mAh30 Wh","Brand":"DJI","Interface":"USB Type-C charging port (Input: 5 V/2 A, 9 V/2 A, 12 V/2 A, 15 V/1.6 A)","Item Type":"Power","Power Type":"Battery Grip"}', 'Just the grip', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1227, 6, 68, 'DJI Ronin BG33 Grip', 'dji-ronin-bg33-grip', 'The DJI RS BG33 Battery Grip is a high-capacity add-on accessory designed to extend shooting times for your RS stabilizer. It is compatible with the RS 5, RS 4 Pro, and the RS 4 gimbals. It provides continuous power up to 14 hours and takes approximately 1 hour to charge. To charge the grip, you’ll use the USB-C port and a separately available USB-C cable. You can also use the USB-C port to charge accessories while the grip is in use.', 79000.0, '{"Battery Capacity":"2150 mAh","Battery Life":"14 hours","Brand":"DJI","Item Type":"Power","Mfr. Model Number":"CP.RN.00000500.01","Power Type":"Battery Grip","Weight":"0.6 lb."}', 'DJI
RS
BG33 battery grip', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1228, 6, 68, 'DJI Ronin-S BG37 Battery Grip', 'dji-ronin-s-bg37-battery-grip', 'The DJI Ronin-S BG37 Battery Grip houses a 2400 mAh LiPo battery that can be fully charged in around 2-1/2 hours for the DJI Ronin-S gimbal.

Add this DJI Ronin-S BG37 Battery Grip to your DJI Ronin-S for up to 12 hours of uninterrupted operation.', 54000.0, '{"Brand":"DJI","Item Type":"Power","Power Supply":"BatteryModel: RB1-2400mAh-14.4VType: 18650 LiPoCapacity: 2400 mAhCapacity: 34.56 Wh","Power Type":"Battery and Battery Grip"}', 'Just the battery grip', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1229, 6, 68, 'DJI Ronin-S Battery Adapter', 'dji-ronin-s-battery-adapter', 'The DJI RSBA1 Ronin-S Battery Adapter is an add-on accessory for the DJI Ronin-S gimbal and Ronin-S BG37 Battery Grip that allows the battery grip to be charged independently of the Ronin-S gimbal head. The USB Type-C input works with 5V, 2A and 12V, 2A chargers and a USB Type-A port provides 5V, 2A of power output for charging mobile devices and accessories.', 39000.0, '{"Brand":"DJI","Item Type":"Power","Power Supply":"Power InputConnector: USB Type-CVoltage: 5V-12VAmperage: 2APower OutputConnector: USB Type-AVoltage: 5VAmperage: 2A","Power Type":"Power Adapter"}', 'Just the battery adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1230, 4, 68, 'DJI Ronin-S Multi-Camera Control Cable (Mini-USB)', 'dji-ronin-s-multi-camera-control-cable-mini-usb', 'The DJI Ronin-S Multi-Camera Control Cable (Mini-USB) is an add-on accessory for the DJI Ronin S gimbal stabilizer that adds control of camera shutter, autofocus, and video recording start/stop to compatible camera and lens combinations. This cable is 7.9 inches long.

Compatible cameras:

Canon 80D
	Canon 6D Mark II
