INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1236, 6, 68, 'DJI Two-Way Charging Hub for Avata 360', 'dji-two-way-charging-hub-for-avata-360', 'The DJI Two-Way Charging Hub for Avata 360 is a 3-slot charger designed to refuel the DJI Intelligent Flight Battery for Avata 360. With one to three batteries inserted, the charger can be set to sequential or simultaneous modes, or it can be used as a power bank that will output 30W of power.', 61000.0, '{"Battery Bays":"3","Brand":"DJI","Item Type":"Power","Mfr. Model Number":"CP.FP.00000307.01","Modes":"Sequential, Simultaneous","Power Output":"30W","Power Type":"Charger"}', 'DJI
Two-Way
