INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1238, 6, 68, 'DJI WB37 Battery Charging Hub (USB Type-C)', 'dji-wb37-battery-charging-hub-usb-type-c', 'The DJI WB37 Battery Charging Hub (USB Type-C) is an extra battery charger for DJI WB37 batteries (separately rentable here) featuring a USB Type-C port for charging (charger not included). If you rented the DJI High-Bright Remote Monitor and need a battery charging hub, you’ve come to the right place.', 79000.0, '{"Brand":"DJI","Item Type":"Power","Mfr. Model Number":"CP.RN.00000203.01","Power":"1 x USB Type-C Input","Power Type":"Charger and Hub"}', 'WB37
Charging
