INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1239, 6, 68, 'DJI WB37 LiPo Battery Pack for DJI CrystalSky / Cendence', 'dji-wb37-lipo-battery-pack-for-dji-crystalsky-cendence', 'The DJI WB37 LiPo Battery Pack is used by the DJI CrystalSky 7.85-inch Ultra Bright Monitor for Inspire/Phantom, DJI High-Bright Remote Monitor, and DJI WB37 Battery Charging Hub, offering up to 4-5 hours of runtime.

The DJI WB37 LiPo Battery Pack is a 4920mAh, 37.39 Wh, lithium-ion, rechargeable battery used by the DJI High-Bright Remote Monitor and DJI WB37 Battery Charging Hub, offering up to 4-5 hours of runtime. We include two with each CrystalSky rental, but if you need any spares, you’ve come to the right place.', 68000.0, '{"Brand":"DJI","Item Type":"Power","Power Type":"Battery"}', 'Just the battery', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1240, 2, 68, 'DJI Wide-Angle Lens for Osmo Pocket 3', 'dji-wide-angle-lens-for-osmo-pocket-3', 'This DJI Wide-Angle Lens attaches to the lens of your Osmo Pocket 3 to extend the field of view to 108°.', 54000.0, '{"Brand":"DJI","Compatibility":"DJI Osmo Pocket 3","Environmental":"Environmental ProtectionNo","Item Type":"Lens","Lens Mount":"Add-on","Lens Type":"Wide Angle","Mfr. Model Number":"CP.OS.00000307.01","Physical":"Dimensions0.92 × 0.7 × 0.3″ Weight0.13 oz","Zoom Type":"Fixed Focal Length"}', 'DJI
