INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1250, 5, 68, 'DJI Zenmuse X9 Sony E Lens Mount', 'dji-zenmuse-x9-sony-e-lens-mount', 'Expand your lens options when using your Ronin 4D 4-Axis Cinema Camera 6K or 8K Combo with the Sony E-mount Zenmuse X9 Lens Mount Unit from DJI. This dedicated unit replaces the DJI DL lens mount on your Zenmuse X9 camera.

