INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1279, 2, 73, 'DZOFilm LingLung 10-24mm T2.9 Parfocal Cine (MFT)', 'dzofilm-linglung-10-24mm-t2-9-parfocal-cine-mft', 'The DZOFilm LingLung 10-24mm T2.9 Parfocal Cine for Micro 4/3 is an ultra-wide parfocal cine zoom for Micro 4/3 cameras and camcorders. Key features include:

Maintains focus throughout the zoom range
Near-zero focus breathing; 19.7-inch minimum focus
High-quality cine build with geared focus and zoom rings
Twelve-blade aperture diaphragm

