INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1341, 3, 64, 'Dana Dolly Center Support', 'dana-dolly-center-support', 'The Dana Dolly Center Support is an aluminum support device that lends a helping hand to the Dana Dolly Portable Dolly for heavy camera loads. To prevent scraping, two foam pads on either side of the support make contact with your rail, allowing you to enjoy a smooth ride. This support can securely load up to 70 pounds of gear, and is compatible with 5/8" baby stud stands, like the Kupo Low Mighty Baby Stand 22.5-inch.', 39000.0, '{"Brand":"Dana Dolly","Camera Support Type":"Dolly","Dimensions":"13.25 × 4.00 × 1.75″","Item Type":"Camera Support","Load Capacity":"70.0 lb","Material":"Powder Coated 6061 Aluminum Felt cushion tabs","Mfr. Model Number":"DDCTRSUP1","Mounting":"TVMP with taped hole and screw for baby pin mounting","Weight":"1.5 lb"}', 'Dana
