INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1349, 4, 65, 'Deity C17 Locking 3.5mm TRS to 9-Pin LEMO Timecode Cable', 'deity-c17-locking-3-5mm-trs-to-9-pin-lemo-timecode-cable', 'The Deity C17 Locking 3.5mm TRS to 9-Pin LEMO Timecode Cable pairs TC-1 timecode generators to cinema cameras that sport a 9-pin LEMO input, like the KOMODO 6K or RED V-RAPTOR 8K. This cable connects to the devices from a right-angle, locking 3.5mm TRS male connector on one end and a right-angle, 9-pin LEMO connector at the other end.', 43000.0, '{"Brand":"Deity","Cable Type":"Audio, Video, Sync, and LEMO","Compatibility":"Deity Microphones TC-1 RED Komodo 6K RED Komodo 6K Stormtrooper Limited Edition RED V-Raptor 8K RED V-Raptor 8K XL","Inputs/Outputs":"Connector 11x Right-Angle Locking 3.5mm TRS Male Connector 21x Right-Angle 9-Pin LEMO Connector Male","Item Type":"Cable"}', 'Deity
