INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1367, 6, 75, 'Eartec 10-Port Multi-Charger', 'eartec-10-port-multi-charger', 'The Eartec 10-Port Multi-Charger has ten bays to recharge Eartec UltraLITE, HUB, and UltraPAK batteries, letting you keep your systems up and running with minimal downtime. The charge time is roughly three hours, and each bay has an LED indicator that turns from red to green when the corresponding battery is fully charged.', 68000.0, '{"Brand":"Eartec","Charge Time":"Approximately Three Hours","Input Level":"100 to 240 VAC","Item Type":"Power","Mfr. Model Number":"CHLX10E","Power Type":"Charger"}', 'Eartec
Multi-Charger
