INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1380, 4, 92, 'FUSION TLC Camera Control Cable Micro-A to Micro-B', 'fusion-tlc-camera-control-cable-micro-a-to-micro-b', 'The FUSION TLC Camera Control Cable Micro-A to Micro-B is a coiled cable deigned for use with the Raven Trigger for Nikon and Canon. Key features include:

