INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1383, 3, 93, 'FXLion NANO V-Lock Camera Cage Plate', 'fxlion-nano-v-lock-camera-cage-plate', 'The FXLion NANO V-Lock Camera Cage Plate provides D-Tap, micro V-Mount power to a small selection of camera cages. This plate can be used with your own FXLion batteries, or a third-party brand micro battery like this Anton Bauer Titon Micro 90 V-Mount Battery. As for camera cages this plate can be used with, our compatible inventory consists of the ARRI ALEXA Mini Cage, ARRI ALEXA Mini LF Cage – 15mm LWS, ARRI ALEXA Mini LF Cage – 19mm Studio, or the Wooden Unified Base Accessory Kit for BMPCC 6K Pro. Like most battery plates of this type, you’re provided with a mounting plate and 1/4"-20 screws for cage attachment.', 61000.0, '{"Brand":"FXLion","Camera Support Type":"Baseplate","General":"Plate Front / Battery MountV-Mount","Item Type":"Camera Support","Power Output":"D-Tap: VDC"}', 'Fxlion
