INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1390, 4, 86, 'Freefly 18-inch RED RCP Serial Cable for Movi Pro', 'freefly-18-inch-red-rcp-serial-cable-for-movi-pro', 'The Freefly 18-inch RED RCP Serial Cable for Movi Pro is a high-flex, lightweight cable that gives you access to the Redlink Command Protocol on RED cameras. Key features include:

High-flex, lightweight design
Movi and MIMIC control of key camera settings
Focus and aperture control of Canon EF lenses
Compatible DSMC2 expander required

High-Flex, Lightweight Design. The Freefly 18-inch RED RCP Serial Cable for Movi Pro’s construction ensures your setup won’t be negatively impacted by difficult/excess cable runs. Its length means you don’t need a RED Jetpack Expander to use it.

RED Compatibility. This cable is designed for use with RED DSMC2 brains, like the WEAPON HELIUM / EPIC-W / SCARLET-W / Raven that are fitted with a DSMC2 expander featuring a CTRL port. If you are renting a DSMC2 brain from us, a base expander is already included.

Redlink Command Protocol. This cable connects the RED brain to the Freefly Movi Pro via the camera’s CTRL port. This lets you use Freefly’s Mimic or Movi Controller (not included) to adjust features like Start/Stop, ISO, Frame Rate, Color Temp, and focus and aperture on EF lenses, all from up to 600+ feet away.', 68000.0, '{"Brand":"Freefly","Cable Type":"Control","Dimensions":"Length: 18\\"","Item Type":"Cable"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1391, 4, 86, 'Freefly 7.8-inch RED RCP Serial Cable for Movi Pro', 'freefly-7-8-inch-red-rcp-serial-cable-for-movi-pro', 'The Freefly RED RCP Serial Cable for Movi Pro is a high-flex, lightweight cable that gives you access to the Redlink Command Protocol on RED cameras with JetPack expanders installed. Key features include:

High-flex, lightweight design
Movi and MIMIC control of key camera settings
Focus and Aperture control of Canon EF lenses
Designed to work with RED JetPack Expanders

High-Flex, Lightweight Design. Ensures your setup won’t be negatively impacted by difficult / excess cable runs.

RED Compatibility. This cable is designed for use with RED DSMC2 brains like the WEAPON HELIUM / EPIC-W / SCARLET-W / Raven that have been fitted with the RED DSMC2 Jetpack Expander.

Redlink Command Protocol. Using the “CTRL” port on the Jetpack Expander, this cable connects the RED brain to the Freefly Movi Pro.  This enables users to  Freefly’s Mimic or Movi Controller (not included) to adjust features like Start/Stop, ISO, Frame Rate, Color Temp, and focus and aperture on EF lenses, all from up to 600+ feet away.', 54000.0, '{"Brand":"Freefly","Cable Type":"Power","Dimensions":"Length: 7.8\\"","Item Type":"Cable"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1392, 3, 86, 'Freefly Adjustable Accessory Mount', 'freefly-adjustable-accessory-mount', 'The Freefly Adjustable Accessory Mount is a compact mounting solution for Ember or Wave cameras. Key features include:

Low-profile accessory mount for Ember / Wave
¼-20 captive screw to attach monitor/accessory
Hinge provides up to 135° of tilt (100° minimum)
Can be direct-mounted to camera or Freefly NATO clamp

