INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1393, 3, 86, 'Freefly Cheese Plate for Ember Camera', 'freefly-cheese-plate-for-ember-camera', 'The Freefly Cheese Plate for Ember Camera provides an abundance of mounting options to your Freefly Ember or Wave camera. This unit sports a bounty of M3, 1/4"-20, and 3/8"-16 threads along the edges and main surface, as well as mounting slots that allow you to attach a variety of accessories, such as top handles, monitors, articulating arms, and more. The plate mounts onto the camera using the existing screws from your camera body.', 79000.0, '{"Brand":"Freefly","Camera Support Type":"Baseplate","Dimensions":"3.3 × 2.7 × 0.5″","Item Type":"Camera Support","Material":"Aluminum","Mount Types":"Multiple x 1/4\\"-20 Threads Multiple x 3/8\\"-16 Threads Multiple x M3 Threads"}', 'Freefly
