INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1396, 1, 86, 'Freefly Ember S5K 2.5TB pSLC Standard Micro V-Mount Kit (EF)', 'freefly-ember-s5k-2-5tb-pslc-standard-micro-v-mount-kit-ef', 'Looking for a standard bundle that adds mounting points and V-Mount power to the Freefly Ember S5K with Active EF Mount and 2.56TB pSLC? This Freefly Ember S5K 2.5TB pSLC Standard Micro V-Mount Kit (EF) is the kit for you! Offering rail-compatibility, battery & charging solutions, and more, this kit has you covered on the basics. Feel free to check out any of the highlighted links below for additional information and specifications!

