INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1409, 5, 88, 'Fringer EF-NZ II Canon EF to Nikon Z Autofocus Adapter', 'fringer-ef-nz-ii-canon-ef-to-nikon-z-autofocus-adapter', 'The Fringer EF-NZ II Canon EF to Nikon Z Autofocus Adapter enables use of a Canon EF or EF-S lens with a Nikon Z camera. Key features include:

Enables autofocus and auto exposure
Weather sealed
