INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1420, 2, 89, 'Fuji GF 120mm f/4 Macro R LM OIS WR', 'fuji-gf-120mm-f-4-macro-r-lm-ois-wr', 'The Fuji GF 120mm f/4 Macro R LM OIS WR is a short tele / macro lens for the Fuji G-mount cameras. Key features include:

Fuji G-mount
