INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1421, 2, 89, 'Fuji GF 20-35mm f/4 R WR', 'fuji-gf-20-35mm-f-4-r-wr', 'The Fuji GF 20-35mm f/4 R WR is a 16-28mm equivalent ultra-wide to wide-angle zoom for Fuji G-mount cameras. Key features include:

Versatile ultra-wide to wide-angle zoom
Manual aperture and focus rings
Fast, accurate autofocus; internal-focusing design
