INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1431, 2, 89, 'Fuji GF 55mm f/1.7 R WR', 'fuji-gf-55mm-f-1-7-r-wr', 'The Fuji GF 55mm f/1.7 R WR is a versatile, fast, and compact cine-style portrait-length prime for Fuji G-mount cameras. Key features include:

