INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1444, 5, 89, 'Fuji LH-XF27 Lens Hood', 'fuji-lh-xf27-lens-hood', 'The Fuji LH-XF27 Lens Hood is a plastic, dome-shaped Bayonet hood engineered to deflect light, reduce flare, and provide protection for the Fuji XF 23mm f/2.8 R WR – Black and Fuji XF 27mm f/2.8 R WR.', 39000.0, '{"Brand":"Fuji","Front Accessory Thread":"No","Hood Type":"Bayonet for Dedicated Lens","Item Type":"Lens Support","Lens Support Type":"Hood","Material":"Plastic","Mfr. Model Number":"#16674853"}', 'Fuji
