INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1450, 3, 89, 'Fuji MHG-GFX S Handgrip for GFX100S', 'fuji-mhg-gfx-s-handgrip-for-gfx100s', 'The Fuji MHG-GFX S Handgrip for GFX100S is an accessory that makes it easier to handle your Fuji GFX100S mirrorless camera. Key features include:

Only for the Fuji GFX100S
Adds additional clearance from the camera body’s base
Allows easy switching of batteries and memory cards
Durable aluminum-alloy build

Control Boost. The Fuji MHG-GFX S Handgrip for GFX100S gives you an optimized grip on your camera for easier handling. It adds additional clearance from the camera body’s base to better support the use of large-diameter lenses when mounted to a tripod.

Easy Access. This grip gives you easy access to the camera’s battery compartment and memory card slot, even when it’s mounted to a tripod.

Versatility. The 1/4"-20 tripod mount is positioned along the camera’s optical axis to facilitate panning shots, while the bottom of the plate has rails that let you use a quick-release plate.', 93000.0, '{"Brand":"Fuji","Camera Support Type":"Baseplate","Item Type":"Camera Support","Mfr. Model Number":"16696760"}', 'Just the handgrip', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1451, 3, 89, 'Fuji MHG-XT5 Metal Hand Grip', 'fuji-mhg-xt5-metal-hand-grip', 'The Fuji MHG-XT5 Metal Hand Grip is an accessory grip that makes it easier to handle your Fuji X-T5 and X-T50 mirrorless cameras. Key features include:

Only for the Fuji X-T5 and X-T50
Adds additional clearance from the camera body’s base
Allows easy switching of batteries and memory cards
Durable aluminum-alloy build

Control Boost. The Fuji MHG-XT5 Metal Hand Grip gives you an optimized grip on your camera for easier handling. It adds additional clearance from the camera body’s base to better support the use of large-diameter lenses when mounted to a tripod.

Easy Access. This grip gives you easy access to the camera’s battery compartment and memory card slot, even when it’s mounted to a tripod.

Versatility. The 1/4"-20 tripod mount is positioned along the camera’s optical axis to facilitate panning shots, while the base of the grip has an Arca-type compatible dovetail design that can act as a quick-release plate with compatible tripod heads.', 89000.0, '{"Brand":"Fuji","Camera Attachment":"1/4\\"-20 Male","Camera Support Type":"Baseplate","Construction":"Aluminum","Item Type":"Camera Support","Mfr. Model Number":"16785793"}', 'Just the grip', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
