INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1495, 2, 89, 'Fuji XF 16mm f/2.8 R WR', 'fuji-xf-16mm-f-2-8-r-wr', 'The Fuji XF 16mm f/2.8 R WR is a compact, fast-aperture, wide-angle lens designed for Fuji X-mount mirrorless cameras. Key features include:

Excellent for architectural, nature, and landscape photography
Great for use in available lighting conditions
