INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1497, 2, 89, 'Fuji XF 18-135mm f/3.5-5.6 R LM OIS WR', 'fuji-xf-18-135mm-f-3-5-5-6-r-lm-ois-wr', 'The Fujifilm XF 18-135mm f/3.5-5.6 R LM OIS WR is a weather-sealed, multi-purpose zoom lens for Fuji X-mount cameras. Key features include:

Excellent all-in-one vacation lens for daylight shooting
High-quality optical design
