INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1498, 2, 89, 'Fuji XF 18-55mm f/2.8-4 R LM OIS', 'fuji-xf-18-55mm-f-2-8-4-r-lm-ois', 'The Fuji XF 18-55mm f/2.8-4 R LM OIS is the first zoom lens for Fuji X-mount cameras. Key features include:

Great for portraiture, street photography, and everyday use
