INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1500, 2, 89, 'Fuji XF 18mm f/2 R', 'fuji-xf-18mm-f-2-r', 'The Fuji XF 18mm f/2 R is a solid wide-angle prime lens for Fuji X-mount cameras. Key features include:

