INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1502, 2, 89, 'Fuji XF 23mm f/1.4 R', 'fuji-xf-23mm-f-1-4-r', 'The Fuji XF 23mm f/1.4 R is a moderately wide angle lens for Fuji X-mount cameras, and the predecessor to the Fuji XF 23mm f/1.4 R LM WR. Key features include:

Excellent for street photography
