INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1504, 2, 89, 'Fuji XF 23mm f/2 R WR', 'fuji-xf-23mm-f-2-r-wr', 'The Fuji XF 23mm f/2 R WR is a moderately wide-angle lens for Fuji X-mount cameras. Key features include:

