INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1512, 2, 89, 'Fuji XF 50-140mm f/2.8 R LM OIS WR', 'fuji-xf-50-140mm-f-2-8-r-lm-ois-wr', 'The Fuji XF 50-140mm f/2.8 R LM OIS WR is a fast-aperture telephoto zoom for Fuji X-mount mirrorless cameras. Key features include:

Excellent for portraiture and sports photography
Fast, nearly silent autofocus
Five-stop optical image stabilization
