INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1551, 4, 89, 'Fujinon SA-12F-XLR Duvo Portable Power Cable (12-inch)', 'fujinon-sa-12f-xlr-duvo-portable-power-cable-12-inch', 'The Fujinon SA-12F-XLR Duvo Portable Power Cable connects the Fujinon Duvo HZK 14-100mm and HZK 24-300mm lenses to cameras that don’t have 12-pin lens connectors. This cable uses a 12-pin connection from the lens’s servo to a 4-pin XLR power source (not included) to power the lens.

