INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1554, 2, 90, 'Fujinon UA18X5.5BERD B4 Lens w/ SS-15D Control Kit', 'fujinon-ua18x5-5berd-b4-lens-w-ss-15d-control-kit', 'The Fujinon UA18X5.5BERD B4 Lens w/ SS-15D Control Kit includes:

Fujinon UA18X5.5BERD B4 Lens for 2/3 Sensors
	Fujinon SS-15D Digital Full Servo Control Kit

