INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1570, 3, 98, 'Glide Gear Straight Track 12-foot', 'glide-gear-straight-track-12-foot', 'The Glide Gear Straight Track 12-foot is a straight track made up of 4-foot hollow pipes that can be joined together to create a track totaling 12 feet in length. While this kit only includes enough rails for a 12-foot track, multiple kits can be combined for even longer tracks. All the hardware necessary for assembling this track will come included with the rental, and when disassembled, can be neatly stored in the soft carry case. This rental does not include a dolly, but the Glide Gear SYL-960 Tripod Dolly will work great if you need one.', 121000.0, '{"Brand":"Glide Gear","Camera Support Type":"Dolly","Item Type":"Camera Support"}', '2x
