INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1571, 6, 100, 'GoPro ACBAT-011 Enduro for MAX 360', 'gopro-acbat-011-enduro-for-max-360', 'Looking for an extra battery to power your GoPro MAX 360? You’re in the right spot! This GoPro ACBAT-011 Enduro for MAX 360 provides uninterrupted, full throttle power to the MAX for nearly 2 hours, even in temperatures as low as 14°F. Check out the diagram in the Resources section on your screen for specific runtimes and frame rates!', 39000.0, '{"Battery":"Battery ChemistryLithium-Ion Battery Capacity1600 mAh","Brand":"GoPro","Item Type":"Power","Mfr. Model Number":"#ACBAT-011","Power Type":"Battery"}', 'Just the battery', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
