INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1573, 2, 100, 'GoPro Anamorphic Lens Mod for HERO13 Black', 'gopro-anamorphic-lens-mod-for-hero13-black', 'The GoPro Anamorphic Lens Mod for HERO13 Black is an optional lens for the HERO13 to capture wide angle, 16:9 and 21:9 aspect ratio shots with minimal distortion. Key features include:

In-camera de-squeeze
Scratch- and water-resistant
Only for HERO13
Less distortion than wide/ultrawide lenses

