INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1575, 3, 100, 'GoPro Chest Harness', 'gopro-chest-harness', 'This GoPro Chesty (Performance Chest Mount) has a padded design that is more stable and comfortable on your chest. It’s made with breathable materials that further add to the comfort aspect.

Compatible with all GoPro cameras.

This is a chest harness for all GoPro action camera models. It accepts GoPro’s standard quick-release buckle for, you guessed it, quick release. If you’d prefer an updated version of this product, we also offer the GoPro Chesty Performance Mount.', 32000.0, '{"Brand":"GoPro","Camera Support Type":"Harness","Item Type":"Camera Support"}', 'Chest
