INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1576, 3, 100, 'GoPro Chesty Performance Mount', 'gopro-chesty-performance-mount', 'The GoPro Chesty is a performance chest mount for GoPro cameras. Key features include:

Hands-free camera stabilization
New breathable strap and bracket cushion material
Uses the standard GoPro quick-release buckle for attaching cameras
Adjustable straps to fit most human bodies

