INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1584, 6, 100, 'GoPro Enduro Dual Battery Charger Kit for HERO9/10/11/12', 'gopro-enduro-dual-battery-charger-kit-for-hero9-10-11-12', 'The GoPro Enduro Dual Battery Charger Kit for HERO9/10/11/12 Black is a one-stop power solution for the GoPro HERO9, HERO10, HERO11, and HERO12. It includes a Dual Battery Charger and two Enduro Batteries. Key features include:

