INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1603, 1, 100, 'GoPro MISSION 1', 'gopro-mission-1', 'The GoPro MISSION 1 is a compact, high-quality action camera series capable of 8K30 recording and 50MP photo capture with a 159° native field of view. Key features include:

1-inch sensor
