INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1614, 3, 100, 'GoPro Shorty', 'gopro-shorty', 'The GoPro Shorty is a mini extension pole and tripod that’s ideal for quickly setting up tabletop or handheld shots. Key features include:

