INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1626, 3, 104, 'Hasselblad 907X Control Grip', 'hasselblad-907x-control-grip', 'The Hasselblad 907X Control Grip gives you more intuitive handling and tactile control over your Hasselblad 907X & CFV 100C. It’s great for working from eye-level and waist-level positions, and it’s the perfect alternative for the camera’s touchscreen interface if you’re wearing gloves.

This grip features a shutter-release button, a control dial for fast aperture and shutter-speed adjustment, and a joystick for autofocus point selection. Additional, customizable buttons give you direct access to the menu system and image-review options. The grip attaches to the camera via a 1/4"-20 tripod mount.', 154000.0, '{"Brand":"Hasselblad","Camera Support Type":"Baseplate","Item Type":"Camera Support","Mfr. Model Number":"H-CP.HB.00000595.01"}', 'Hasselblad 907X
Control
Grip', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1627, 6, 104, 'Hasselblad Battery Charging Hub for X System', 'hasselblad-battery-charging-hub-for-x-system', 'The Hasselblad Battery Charging Hub for X System is a two-bay charger that supports the Hasselblad High-Capacity Rechargeable Battery for X System. It’ll charge one 3400 mAh battery in two hours and half hours, and will charge two 3400 mAh batteries in about three hours. It also supports first-generation X System 3200 mAh batteries, which it’ll charge in approximately three hours. There are front LEDs to indicate charge status, and the hub will chime once the batteries are fully charged. This hub can be powered by its included power supply or from power banks via its USB Type-C connector.', 79000.0, '{"Battery Bays":"2","Brand":"Hasselblad","Charging Method":"Independent, Simultaneous","Indicator":"LED","Item Type":"Power","Mfr. Model Number":"H-CP.HB.00000392.01","Power Type":"Charger and Hub","USB Port":"1x USB Type-C"}', 'Hasselblad
