INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1674, 6, 107, 'Hollyland Solidcom C1 4-slot Charging Base', 'hollyland-solidcom-c1-4-slot-charging-base', 'If you need an extra charger for your Solidcom C1 batteries, you’re in luck: the Hollyland Solidcom C1 4-slot Charging Base can charge up to four spare batteries in just 2.5 hours. Each battery powers a remote headset for up to 10 hours. This rental doesn’t include any batteries; if you need spares, you can rent them here.', 71000.0, '{"Brand":"Hollyland","Item Type":"Power","Power Type":"Charger"}', '4-slot charging base
USB-C cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1675, 6, 107, 'Hollyland Solidcom C1 8-slot Charging Base', 'hollyland-solidcom-c1-8-slot-charging-base', 'The Hollyland Solidcom C1 8-slot Charging Base can charge up to 8 batteries in just 2.5 hours. Each battery can power a remote headset for up to 10 hours.

If you’re looking for a charging solution for your Solidcom C1 batteries, you’re in the right place. The Hollyland Solidcom C1 8-slot Charging Base can charge up to 8 batteries in just 2.5 hours. Each battery can power a remote headset for up to 10 hours. This rental only includes the charger; if you need extra batteries, you’ll have to rent them separately here.', 79000.0, '{"Brand":"Hollyland","Item Type":"Power","Power Type":"Charger"}', '8-slot charging base
AC adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
