INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1677, 6, 107, 'Hollyland Solidcom M1 Beltpack Battery', 'hollyland-solidcom-m1-beltpack-battery', 'The Hollyland Solidcom M1 Beltpack Battery is a lithium-ion battery that powers the M1 Pro and M1 beltpacks. The 3.8V battery provides a 1500mAh capacity, and fits the separately available M1 Pro or M1 multi-unit chargers.', 50000.0, '{"Battery":"Battery ChemistryLithium-Ion Battery Capacity1500 mAh Output Voltage3.8 VDC Charging Power4.35 VDC","Brand":"Hollyland","Item Type":"Power","Power Type":"Battery"}', 'Just the battery', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
