INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1683, 4, 108, 'Hosa Technology Pro 5-Pin DIN MIDI Cable (10-foot)', 'hosa-technology-pro-5-pin-din-midi-cable-10-foot', 'This Hosa Technology Pro 5-Pin DIN MIDI Cable (10’) is a serviceable cable with male 5-pin DIN connectors on each end. The cable features oxygen-free copper conductors and a dense spiral copper shield to block interference and hum, and its connectors are nickel-plated. It supports all MIDI functions, including uploading and downloading data and relaying SysEx information.', 21000.0, '{"Brand":"Hosa Technology","Cable Type":"MIDI","Connector":"MIDI","Connectors":"DIN 5-pin male straight (x2)","Item Type":"Cable","Length":"10.0’","Material":"Nickel plated contacts\\nOFC conductors"}', 'Pro
MIDI to
MIDI
Cable (10’)', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1684, 5, 109, 'Hoya 49mm EVO Antistatic Circular Polarizer Filter', 'hoya-49mm-evo-antistatic-circular-polarizer-filter', 'The Hoya 49mm EVO Antistatic Circular Polarizer Filter is a high-quality slim-profile filter designed to enhance saturation and capture clearer imaging in foggy or hazy conditions. Key features include:

Minimizes reflections and glares
EVO antistatic coating repels dust
Water, stain, and scratch resistant
Front thread supports filter stacking

Circular Polarizing Clarity. Supporting full use of your camera’s autofocus and autoexposure functions, the Hoya 49mm EVO Antistatic Circular Polarizer Filter is a great addition to any lens with a 49mm filter thread.

Multi-Layer Coatings. This glass and aluminum filter is equipped with an EVO antistatic coating to deter dust buildup, and is also resistant to water, stains, and scratches. An additional 16-layer multi-coating helps maintain contrast and clarity by reducing reflections and ghosting!

Filter Stacking. Front and rear threads on this filter allow you to take your imagery to the next level!', 75000.0, '{"Brand":"Hoya","Filter Format":"Screw-On","Filter Size":"49","Filter Type":"Polarizing","Item Type":"Lens Support","Lens Support Type":"Filter","Mfr. Model Number":"#XEVA-49CPL"}', 'Hoya 49mm
EVO
Antistatic
Circular
Polarizer
Filter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
