INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1722, 3, 116, 'Induro PU100 4" Lens Plate', 'induro-pu100-4-lens-plate', 'The Induro PU-100 Extra Long Slide-In Quick Release Plate has a 1/4"-20 thread and is a spare or replacement part for GHB2 Gimbal Heads and other Arca-Swiss compatible Quick Release clamps.

The Induro PU-100 Quick Release Plate is a more versatile alternative to our Arca Swiss 4in. Lens Plate.

