INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1739, 6, 117, 'Insta360 ONE R Fast Charge Hub', 'insta360-one-r-fast-charge-hub', 'The Insta360 ONE R Fast Charge Hub simultaneously charges two Insta360 ONE R battery bases, prioritizing the one with the highest remaining power so that you can get back to your shoot as quickly as possible. It features an LED light to indicate charging progress. This rental doesn’t include battery bases.', 36000.0, '{"Brand":"Insta360","Item Type":"Power","Power Type":"Charger and Hub"}', 'Insta360
