INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1751, 6, 117, 'Insta360 Rechargeable Battery for Ace and Ace Pro', 'insta360-rechargeable-battery-for-ace-and-ace-pro', 'The Insta360 Rechargeable Battery for Ace and Ace Pro is a 1650mAh capacity battery designed to power the Ace Pro from Insta360. You can charge the battery internally using the camera or use the compatible Fast Charge Hub for a quicker fuel up.', 39000.0, '{"Battery":"Battery ChemistryLithium-Ion Battery Capacity1650 mAh Recharge Time46 to 70 Minutes","Brand":"Insta360","Environmental":"CertificationsCE, FCC, IC Operating Temperature-4 to 104°F Charging Temperature32 to 104°F","Item Type":"Power","Power Type":"Battery"}', 'Insta360
