INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1786, 3, 125, 'Kessler CineSlider Motor Mount', 'kessler-cineslider-motor-mount', 'This is the motor mount for mounting Kessler Second Shooter motors to a Kessler CineSlider.  We already include this with our Kessler Second Shooter Pro Complete Kit, so only rent this if you have your own Second Shooter or similar motor that you are trying to attach to our Kessler 3-foot / 5-foot CineSlider.', 75000.0, '{"Brand":"Kessler","Camera Support Type":"Slider","Item Type":"Camera Support"}', 'CineSlider motor mount
