INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1787, 3, 125, 'Kessler Crane 100mm to 75mm Bowl Adapter', 'kessler-crane-100mm-to-75mm-bowl-adapter', 'The Kessler Crane 100mm to 75mm Bowl Adapter is a precision-machined bowl reducer that allows you to easily adapt the half bowl of 75mm-compatible fluid heads to larger 100mm-standard bowl-compatible support gear.', 43000.0, '{"Brand":"Kessler","Camera Support Type":"Fluid Head","Item Type":"Camera Support","Mfr. Model Number":"TH1017"}', 'Just the adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
