INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1793, 3, 125, 'Kessler Crane Turntable Kit w/ 12-inch White Surface Top', 'kessler-crane-turntable-kit-w-12-inch-white-surface-top', 'The Kessler Crane Turntable Kit w/ 12-inch White Surface Top is a rotating fixture compatible with CineShooter and Second Shooter motion control systems. Key features include:

Supports CineShooter
Supports Second Shooter
12-inch surface
