INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1805, 5, 125, 'Kessler Second Shooter FIZ Motor V3', 'kessler-second-shooter-fiz-motor-v3', 'The Kessler F.I.Z. Motor V3 is an add-on motor for Kessler motion control system like the CineShooter Pan & Tilt Head, that allows for programmable control of lens focus, iris, or zoom. This motor is also compatible with all Second Shooter remote generations, like the Second Shooter PRO Controller. Controllers can be ​found in the following kits:

