INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1812, 3, 125, 'Kessler Shuttle Dolly Motor Mount Kit', 'kessler-shuttle-dolly-motor-mount-kit', 'The Kessler Shuttle Dolly Motor Mount Kit allows you to connect a Kessler Second Shooter Pro Complete Kit or CineDrive motion control unit to the Kessler Shuttle Dolly to create a powerful motorized dolly solution. In this kit we send the mounting bracket & 24-foot belt. Please note that dolly runs longer than 24 feet are not supported with this kit. If you don’t already have a rail system for your Shuttle Dolly, the Kessler Kwik Rail Kit can be rented separately.', 107000.0, '{"Brand":"Kessler","Camera Support Type":"Dolly","Item Type":"Camera Support"}', 'Shuttle
