INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1815, 4, 128, 'Kondor Blue 12 to 24" Coiled USB-C Right Angle Braided Cable', 'kondor-blue-12-to-24-coiled-usb-c-right-angle-braided-cable', 'This Kondor Blue 12 to 24" Coiled USB-C Right Angle Braided Cable curls right into your USB-C compatible devices to quickly charge or sync files and data. Key features include:

2x USB-C right angle connectors
100W power delivery
USB 3.2 Gen 2 interface
Braided coil design

C to Shining C. Use this Kondor Blue 12 to 24" Coiled USB-C Right Angle Braided Cable to quickly charge and sync your USB-C compatible devices. Since this cable is coiled, you can extend the length without having to deal with annoying cable slack. Both right-angled USB-C connectors are based off the USB 3.2 Gen 2 interface, allowing swift data transfer rates up to 10 Gb/s.', 29000.0, '{"Brand":"Kondor Blue","Cable Length":"12 to 24\\"","Cable Type":"USB","Color":"Black","Connectors":"2x USB-C Male Right Angle","Current Rating":"5 A","Interface":"USB 3.1/3.2 Gen 2 (10 Gb/s)","Item Type":"Cable","Maximum Supported Wattage":"100 W","Variable Length":"Yes, Coiled","Weight":"0.8 oz"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1816, 4, 128, 'Kondor Blue D-Tap to LEMO 6-Pin Cable for RED DSMC2/DSMC3', 'kondor-blue-d-tap-to-lemo-6-pin-cable-for-red-dsmc2-dsmc3', 'The Kondor Blue D-Tap to LEMO 6-Pin Cable for RED DSMC2/DSMC3 is a 20-inch cable designed to provide power to your RED V-RAPTOR and RED KOMODO cameras using Gold or V-Mount batteries. The D-Tap end will fit most standard Gold and V-Mount battery bricks, while the 6-pin LEMO end connects seamlessly with your camera.', 39000.0, '{"Brand":"Kondor Blue","Cable Type":"Power","Connector":"D-Tap and LEMO","Connectors":"1x D-Tap Male (Right-Angle)\\t 1x 6-Pin LEMO LEMO-Type Female","Item Type":"Cable","Length":"1.7’"}', 'Kondor
Blue 6-Pin
LEMO
Braided
D-Tap
Cable 20"', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1817, 4, 128, 'Kondor Blue D-Tap to USB-C Power Cable 16-inch', 'kondor-blue-d-tap-to-usb-c-power-cable-16-inch', 'This 16 inch Kondor Blue D-Tap to USB-C Power Cable is designed to power a compatible camera, laptop, or accessory with a USB-C input. Key features include:

D-tap connector
USB-C connector
16 inch braided cable
Built-in current regulator

Power Trip. Using the 16 inch Kondor Blue D-Tap to USB-C Power Cable, your mirrorless camera, laptop, or external accessory can be powered from any V-Mount or Gold Mount battery that has an available D-tap port. This cable provides up to 65W of power and allows you to hot swap batteries as you please. On one end of this cable you’ll find a D-tap connector, and on the other end you’ll find a USB-C connector.', 32000.0, '{"Brand":"Kondor Blue","Cable Type":"Power","Connector":"USB-C and D-Tap","Connectors":"Connector 11 x D-Tap Male Connector 21 x USB-C Male","General":"Voltage ControlRegulated LED IndicatorsNo","Item Type":"Cable","Length":"1.3’","Physical":"Cable Length16\\" Weight1.4 oz"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1818, 4, 128, 'Kondor Blue XLR Female to Mini XLR 16-inch', 'kondor-blue-xlr-female-to-mini-xlr-16-inch', 'Connect a microphone or audio mixer to your Canon C70 or Blackmagic Pocket Cinema Camera 6K or 4K with this blue Mini-XLR Male to XLR Female Audio Cable from Kondor Blue.

The Kondor Blue XLR Female to Mini XLR 16-inch adapts a standard 3-pin XLR Male audio device’s output to a mini XLR input found on cameras like the Blackmagic Pocket Cinema Camera 4K, 6K EF, 6K PL, 6K Pro EF, or Canon C70 for improved audio recording. This cable is 16" in length for on-camera audio additions.', 29000.0, '{"Brand":"Kondor Blue","Cable Type":"Audio","Connector":"Mini XLR and 3-Pin XLR","Item Type":"Cable","Length":"11.0’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1819, 4, 128, 'Kondor Blue XLR Female to Mini XLR 25-foot', 'kondor-blue-xlr-female-to-mini-xlr-25-foot', 'The Kondor Blue XLR Female to Mini XLR 25-foot cable adapts a standard 3-pin XLR Male audio device’s output to a mini XLR input found on cameras like the Blackmagic Pocket Cinema Camera 4K, 6K EF, 6K PL, 6K Pro EF, or Canon C70 for improved audio recording. This cable is 25’ in length, allowing you to add mics and mixers to your rig, on, or off, camera.', 36000.0, '{"Brand":"Kondor Blue","Cable Type":"Audio","Connector":"Mini XLR and 3-Pin XLR","Item Type":"Cable","Length":"25.0’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
