INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1822, 4, 129, 'Kopul 10ft DMX55P-010-S Studio Series 5-Pin DMX Cable', 'kopul-10ft-dmx55p-010-s-studio-series-5-pin-dmx-cable', 'The Kopul 10ft DMX55P-010-S Studio Series 5-Pin DMX Cable will connect all your DMX lighting gear to a DMX controller for accurate, trouble-free DMX data transfer. This cable is manufactured to the industry-standard 100-Ohm resistance and boasts shielding and insulation that protects against EM and RF interference. All of this is housed in a durable, flexible PVC jacket with Chuck-style strain relief where the cable meets the connector.', 21000.0, '{"Brand":"Kopul","Cable Type":"Lighting and Control","Item Type":"Cable","Length":"10.0’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1823, 4, 129, 'Kopul 25ft DMX33P-025-S Studio Series 3-Pin DMX Cable', 'kopul-25ft-dmx33p-025-s-studio-series-3-pin-dmx-cable', 'The Kopul 25ft DMX33P-025-S Studio Series 3-Pin DMX Cable is designed to accurately transfer your DMX lighting data with zero hassles. Key features include:

Accurate, hassle-free DMX lighting-data transfer
110-Ohm impedance; oxygen-free conductors
Protection against EM and RF interference
Durable, flexible PVC housing

DMX Data Transfer. The Kopul 25ft DMX33P-025-S Studio Series 3-Pin DMX Cable is designed for accurate, hassle-free DMX lighting-data transfer for live shows, theatrical productions, DJ sets, and myriad other applications.

Build Quality. This cable is manufactured to the industry-standard 100-Ohm resistance, which is ideal for signal transfer. It’s housed in a durable, flexible PVC jacket with Chuck-style strain relief where the cable meets the connector.

Interference Protection. This cable boasts spiral and foil shielding and insulation that protect against EM and RF interference, ensuring that noise won’t affect your signal.', 18000.0, '{"Brand":"Kopul","Cable Type":"Lighting and Control","Electrical":"Conductor Capacitance47 pF/ftConductor DC Resistance85 Ohms/ft (Up to 3280.84’ / 1000 m)Nominal Impedance110 Ohms","General":"Connector 13-Pin XLR FemaleConnector 23-Pin XLR MaleNumber of Conductors2Conductor MaterialOxygen-Free Copper (OFC)Shielding92% Oxygen-Free Copper (OFC) Foil, SpiralJacket TypePolyvinyl Chloride (PVC)Outer Diameter0.25\\"Bend Radius1.4\\"Maximum Pull Tension55 lbs.Operating Temperature-4 to 158°FCable Length25’Weight0.9 lb.","Item Type":"Cable","Mfr. Model Number":"DMX33P-025-S"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1824, 4, 129, 'Kopul 25ft DMX55P-025-S Studio Series 5-Pin DMX Cable', 'kopul-25ft-dmx55p-025-s-studio-series-5-pin-dmx-cable', 'The Kopul 25ft DMX55P-025-S Studio Series 5-Pin DMX Cable will connect all your DMX lighting gear to a DMX controller for accurate, trouble-free DMX data transfer. This cable is manufactured to the industry-standard 100-Ohm resistance and boasts shielding and insulation that protects against EM and RF interference. All of this is housed in a durable, flexible PVC jacket with Chuck-style strain relief where the cable meets the connector.', 21000.0, '{"Brand":"Kopul","Cable Type":"Lighting and Control","Item Type":"Cable"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1825, 4, 129, 'Kopul 50ft DMX55P-050-S Studio Series 5-Pin DMX Cable', 'kopul-50ft-dmx55p-050-s-studio-series-5-pin-dmx-cable', 'The Kopul 25ft DMX55P-050-S Studio Series 5-Pin DMX Cable will connect all your DMX lighting gear to a DMX controller for accurate, trouble-free DMX data transfer. This cable is manufactured to the industry-standard 100-Ohm resistance and boasts shielding and insulation that protects against EM and RF interference. All of this is housed in a durable, flexible PVC jacket with Chuck-style strain relief where the cable meets the connector.', 32000.0, '{"Brand":"Kopul","Cable Type":"LEMO and Control","Item Type":"Cable"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1826, 4, 129, 'Kopul 6" DMX35PA-S 3-Pin Male to 5-Pin Female DMX Adapter', 'kopul-6-dmx35pa-s-3-pin-male-to-5-pin-female-dmx-adapter', 'The Kopul 6" DMX35PA-S 3-Pin Male to 5-Pin Female DMX Adapter is a cable that allows you to connect a 5-pin DMX device to the 3-pin output of a DMX controller. Key features include:

Sturdy XLR connectors that withstand demanding use
Copper cabling for signal reliability
Protection against EM and RF interference
Strain relief where connectors meet the cable

Sturdy, Durable Connectors. The DMX35PA-S features sturdy connectors that can withstand demanding use in any situation.

OFC. Oxygen-free copper cabling provides excellent conductivity and reliable signal transfer of digital data.

No Interference. Spiral and foil shielding with 92% coverage blocks EM and RF interference, and a PVC shield and PE insulation seal the deal with further protection, providing a noise-free signal.

Strain Relief. Chuck-style strain relief where the connectors meet the cable greatly reduces the likelihood of a break in your signal.', 11000.0, '{"Brand":"Kopul","Cable Type":"DMX","Connector":"5-Pin DMX and 3-Pin DMX","Item Type":"Cable","Mfr. Model Number":"DMX35PA-S"}', 'Kopul 6" 3-Pin
Male to 5-Pin
Female
DMX
Adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1827, 4, 129, 'Kopul 6" DMX53PA-S 5-Pin Male to 3-Pin Female DMX Adapter', 'kopul-6-dmx53pa-s-5-pin-male-to-3-pin-female-dmx-adapter', 'The Kopul 6" DMX53PA-S 5-Pin Male to 3-Pin Female DMX Adapter lets you connect a 3-pin DMX device to a DMX controller with a 5-pin output. Key features include:

Accurate, hassle-free DMX lighting-data transfer
Oxygen-free copper conductor
Protection against EM and RF interference
Durable, flexible PVC housing

DMX Adapter. The Kopul 6" DMX53PA-S 5-Pin Male to 3-Pin Female DMX Adapter does just what its name says, allowing you to connect your 3-pin DMX device to a DMX controller with a 5-pin output.

Build Quality. This adapter features oxygen-free copper cable, which is ideal for signal reliability and conductivity. It’s housed in a durable, flexible PVC jacket with Chuck-style strain relief where the cable meets the connector.

Interference Protection. This cable boasts spiral and foil shielding and insulation that protect against EM and RF interference, ensuring that noise won’t affect your signal.', 11000.0, '{"Brand":"Kopul","Cable Type":"DMX","Connector":"5-Pin DMX and 3-Pin DMX","General":"Connector 15-Pin XLR MaleConnector 23-Pin XLR FemaleConductor MaterialOxygen-Free Copper (OFC)Shielding92% Foil, SpiralJacket TypePolyvinyl Chloride (PVC)Cable Length6\\"","Item Type":"Cable","Mfr. Model Number":"DMX53PA-S"}', 'Just the adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1828, 4, 130, 'Kramer 10-foot High-Speed HDMI Male-Micro Cable', 'kramer-10-foot-high-speed-hdmi-male-micro-cable', 'The Kramer 10-foot High-Speed HDMI Male-Micro Cable is a thin, ten-foot cable that’s great for connecting micro-HDMI to full-size HDMI devices up to 4K/60Hz. Key features include:

