INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1850, 5, 132, 'LEE SW150 Mark II Lens Adapter for Canon EF 11-24mm f/4L USM', 'lee-sw150-mark-ii-lens-adapter-for-canon-ef-11-24mm-f-4l-usm', 'The LEE SW150 Mark II Lens Adapter for Canon EF 11-24mm f/4L USM lets you attach the SW150 Mark II Filter Holder to the Canon 11-24mm f/4L. Key features include:

Secure attachment to lens
For the Canon 11-24mm f/4L (available separately)
