INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1854, 5, 132, 'LEE SW150 Mark II w/ 72mm Filter Thread Adapter Kit', 'lee-sw150-mark-ii-w-72mm-filter-thread-adapter-kit', 'The LEE SW150 Mark II w/ 72mm Filter Thread Adapter Kit is designed to allow the SW150 Mark II Filter Holder to connect to any lens with a 72mm filter thread. Key features include:

For lenses with a 72mm filter thread
Easy installation
Secure attachment to lens
