INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1882, 2, 133, 'Leica 28mm f/2 Summicron-M ASPH for Leica M (2023)', 'leica-28mm-f-2-summicron-m-asph-for-leica-m-2023', 'The Leica 28mm f/2 Summicron-M ASPH for Leica M (2023) is a versatile, moderately wide,  fast-aperture prime designed for Leica M-mount cameras that features a redesigned housing and an updated optical design. Key features include:

Great for journalism, documentary, and street photography
