INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1886, 2, 133, 'Leica 35mm f/1.4 Summilux-M ASPH for Leica M (2022)', 'leica-35mm-f-1-4-summilux-m-asph-for-leica-m-2022', 'The Leica 35mm f/1.4 Summilux-M ASPH for Leica M (2022) is a versatile, fast-aperture, wide-angle prime designed for Leica M-mount cameras. Key features include:

Great for landscape, street, and documentary photography
Shallow depth of field and great low-light performance
