INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1891, 2, 133, 'Leica 35mm f/2 ASPH Summicron-M II for Leica M', 'leica-35mm-f-2-asph-summicron-m-ii-for-leica-m', 'The Leica 35mm f/2 ASPH Summicron-M II for Leica M is a fast-aperture, moderately wide angle M-mount lens and update to the Leica 35mm f/2 ASPH Summicron. Key features include:

Great for landscape and street photography
High-contrast images
