INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1892, 2, 133, 'Leica 50mm f/0.95 Noctilux-M for Leica M', 'leica-50mm-f-0-95-noctilux-m-for-leica-m', 'The Leica 50mm f/0.95 Noctilux-M for Leica M is a specially designed optic with exceptional depth-of-field control. Key features include:

Outstanding image quality, even at close distances
Great for portraits and detailed studies
Excellent low-light performance
