INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1904, 2, 133, 'Leica 90mm f/1.5 Summilux-M ASPH for Leica M', 'leica-90mm-f-1-5-summilux-m-asph-for-leica-m', 'The Leica 90mm f/1.5 Summilux-M ASPH for Leica M is a fast-aperture, portrait-length, manual focus prime designed for Leica M-mount cameras. Key features include:

Fast portrait-length prime that’s great in low light
Meticulously crafted optics for exceptional sharpness
