INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1910, 6, 133, 'Leica BP-SCL6 Battery', 'leica-bp-scl6-battery', 'Dedicated to select Leica Q and SL-Series cameras, the Leica BP-SCL6 Battery is an 8.4V, 2200mAh rechargeable lithium-ion battery offering 18% more power than the previous generation. Its unique design is inserted directly into the base of the camera, and it can be charged via the BC-SCL4 Charger. Also, the battery can be charged in-camera via USB-C or, with the Q3, can be charged wirelessly when the HG-DC1 Handgrip is installed.', 104000.0, '{"Battery Capacity":"2200 mAh","Brand":"Leica","Chemistry":"Lithium-ion","Item Type":"Power","Output Voltage":"8.4 VDC","Power Type":"Battery"}', 'Leica
