INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1916, 4, 133, 'Leica FOTOS Cable', 'leica-fotos-cable', 'The Leica FOTOS Cable is a 3.3 foot braided nylon cable designed to transfer photos from select Leica cameras to the Leica FOTOS app. Key features include:

USB Type-C to Lightning cable
Nylon braided cable
3.3 feet long
Connects select Leica cameras to iPhone

