INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1920, 6, 133, 'Leica HG-DC1 Wireless Charging Handgrip', 'leica-hg-dc1-wireless-charging-handgrip', 'The Leica HG-DC1 Wireless Charging Handgrip is a unique grip attachment designed for the Leica Q3. Key features include:

Improves handling and ergonomics
For Q3 digital camera
Enables wireless charging for Q3
Compatible with optional finger loops

Better Grip, Better Shots. The Leica HG-DC1 Wireless Charging Handgrip attaches to your Q3 via a 1/4 20" mount, and allows the camera to fit more comfortably in your hands. This all metal unit enables a wireless charge to a BP-SCL6 battery when used with a Qi-enabled charging mat, like the Leica Drop XL Wireless Charger. On the side of this handgrip you’ll find another mounting point that you can accessorize with optional finger loops, too.', 96000.0, '{"Accessory Mount":"1 × 1/4\\"-20 Female","Brand":"Leica","Camera Attachment":"1/4\\"-20 Male","Construction":"Metal","Item Type":"Power","Power Type":"Battery Grip"}', 'HG-DC1
Handgrip', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1921, 6, 133, 'Leica HG-SCL6 Multifunctional Handgrip', 'leica-hg-scl6-multifunctional-handgrip', 'The Leica HG-SCL6 Multifunctional Handgrip is an accessory battery grip designed specifically for the Leica SL2. Key features include:

Provides a more comfortable portrait-orientation grip
Adds a shutter release and control dials
Durable dust- and moisture-sealed build
One battery included

Additional Power. The Leica HG-SCL6 Multifunctional Handgrip holds one Leica BP-SCL4 battery, which combines with the battery in the SL2 camera to effectively double your shooting time.

Improved Ergonomics. The addition of a battery grip provides a more comfortable grip when shooting in the vertical/portrait orientation. It also adds a shutter-release button and control dials.

Solid Build. The HG-SCL6 grip features the same dust and moisture sealed design as the SL2.

Rental Includes a Battery. This rental includes one BP-SCL4 battery in addition to the battery that comes with the SL2. If you need additional batteries, they’re available as separate rental items. The purchase of this grip will not include a battery.', 218000.0, '{"Brand":"Leica","Item Type":"Power","Power Type":"Battery Grip"}', 'Leica
HG-SCL6
Handgrip
BP-SCL4 battery', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
