INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1935, 3, 133, 'Leica Q2 Thumb Support', 'leica-q2-thumb-support', 'The Leica Q2 Thumb Support is a large right-hand grip that improves ergonomics and comfort while shooting. It lets you comfortably rest your thumb against the camera body, giving you a steadier, more secure grip, particularly when you’re shooting one-handed. This thumb support attaches to the Leica Q2 and Leica Q2 Monochrom via their hot shoes.', 86000.0, '{"Brand":"Leica","Camera Support Type":"Baseplate","Item Type":"Camera Support"}', 'Leica
