INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (1999, 2, 135, 'Lensbaby Trio 28mm f/3.5 for Sony E', 'lensbaby-trio-28mm-f-3-5-for-sony-e', 'While we no longer rent this product, here’s a link to our current selections.

