INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2019, 6, 140, 'Litepanels Dual Gold Mount Battery Bracket for Gemini', 'litepanels-dual-gold-mount-battery-bracket-for-gemini', 'The Litepanels Dual Gold Mount Battery Bracket for Gemini accepts two 14.4V broadcast camera batteries that let the Gemini 2×1 run at 100% power. Key features include:

