INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2023, 4, 153, 'MID49 EVF/LCD Extension Cable for Sony Cinema Cameras 3-Foot', 'mid49-evf-lcd-extension-cable-for-sony-cinema-cameras-3-foot', 'The MID49 EVF/LCD Extension Cable for Sony Cinema Cameras is a 3-foot cable equipped with a 40-Pin Female connector on one end, and a 40-Pin Male connector on the other. Designed for use with select Sony cameras, this cable works as an extension for the Burano, FX9, and FX6 cameras and their associated monitors.', 111000.0, '{"Brand":"MID49","Cable Type":"Extender","Connector":"Sony 40-Pin","Item Type":"Cable","Length":"3’","Mfr. Model Number":"M49-CBL-SON-EVF"}', 'MID49
