INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2025, 5, 164, 'MTF B4 Lens to Canon EF Adapter', 'mtf-b4-lens-to-canon-ef-adapter', 'The MTF B4 Lens to Canon EF Adapter lets you use ENG-style B4 2/3-inch lenses on cameras with a Canon EF mount. Key features include:

