INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2027, 3, 142, 'Manfrotto 114MV Cine/Video Dolly', 'manfrotto-114mv-cine-video-dolly', 'The Manfrotto 114MV Cine/Video Dolly is an add-on wheeled dolly compatible with select Manfrotto and Sachtler video tripods up to 132 pounds. Key features include:

