INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2028, 3, 142, 'Manfrotto 161MK2B Professional Video Tripod', 'manfrotto-161mk2b-professional-video-tripod', 'The Manfrotto 161MK2B Professional Video Tripod is a large-format tripod supporting up to 44 pounds of gear with a maximum height of just over 105-inches. Key features include:

Aluminum build
Bubble level w/ geared center column
Weighs 17.5 pounds
