INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2051, 5, 142, 'Manfrotto Heavy Telephoto Lens Support w/ 357PLV Plate', 'manfrotto-heavy-telephoto-lens-support-w-357plv-plate', 'The Manfrotto Heavy Telephoto Lens Support w/ 357PLV Plate allows you to safely tilt heavy telephoto lens setups when attached to a tripod or other support systems. Key features include:

1/4"-20 mount; 3/8"-16 mount
3 height settings for lens and camera
Removable, anti-twist index pin
