INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2149, 4, 158, 'Mogami 3.5mm TRS Gold Male to Male Stereo 15-foot', 'mogami-3-5mm-trs-gold-male-to-male-stereo-15-foot', 'The Mogami 3.5mm TRS Gold Male to Male Stereo 15-foot cable is designed to connect most any devices that have 3.5mm stereo-mini / AUX audio inputs or outputs, like smartphones, tablets, A/V receivers, and portable audio devices. It’s designed to pass the audio signal without altering its quality, and it uses straight connectors with gold-plated contacts; individually shielded connectors; and a low-noise, abrasion-resistant PVC jacket for maximum clarity.', 64000.0, '{"Brand":"Mogami","Cable Type":"Audio","Connector":"TRS and 3.5mm","Item Type":"Cable","Mfr. Model Number":"GOLD353515"}', 'Mogami 3.5mm
