INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2150, 4, 158, 'Mogami Gold Studio XLR 25-foot Male to Female Cable 4-Pack', 'mogami-gold-studio-xlr-25-foot-male-to-female-cable-4-pack', 'The Mogami Gold Studio XLR 25-foot Male to Female Cable 4-Pack includes four of the Mogami Gold Studio XLR Female to XLR Male 25-foot Cables. These cables are professional-grade XLR cables designed to minimize noise while maintaining audio quality, even in studios suffering from wiring or grounding problems. The Mogami Gold XLR is a 4-conductor cable engineered for maximum rejection of RFI and EMI with XLPE (Cross-Linked Polyethylene) conductor insulation and gold-plated contacts to prevent corrosion. These small-diameter cables work great in professional or home studios even when working with unbalanced equipment.', 282000.0, '{"Brand":"Mogami","Cable Type":"Audio","Connector":"3-Pin XLR","Diameter":"Outer0.236\\"","General":"Conductor MaterialOxygen-Free Copper (OFC) Number of Conductors4 Wire Gauge24 AWG Contact PlatingGold Jacket TypePolyvinyl Chloride (PVC) Insulation TypePolyethylene Conductor Capacitance29.6 pF/ft at 1 kHz","Item Type":"Cable","Length":"25.0’"}', '(4)
