INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2170, 5, 159, 'Moment 82mm CineFlare Blue Streak Filter', 'moment-82mm-cineflare-blue-streak-filter', 'The Moment 82mm CineFlare Blue Streak Filter adds anamorphic-like blue flares to stills and video footage, eliminating the need for a specialty lens. Key features include:

