INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2207, 5, 167, 'Nikon 1.4x III Teleconverter', 'nikon-1-4x-iii-teleconverter', 'The Nikon 1.4x III Teleconverter is used to increase the focal length of compatible Nikon lenses.  Key features include:

Focal length increase
High-quality optics
