INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2242, 2, 167, 'Nikon 50mm f/1.4G AF-S', 'nikon-50mm-f-1-4g-af-s', 'The Nikon 50mm f/1.4G AF-S is a wide-aperture, normal-range lens for both FX and DX camera bodies. Key features include:

