INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2254, 5, 167, 'Nikon C-PL1L Drop-In Polarizing Filter', 'nikon-c-pl1l-drop-in-polarizing-filter', 'This is the drop-in circular polarizing filter for use with most Nikon G-Series Super Telephoto lenses. Its small rotating dial on the outside of the filter holder is used to adjust polarization.

Attention Nikon 200mm f2 Users:  This filter does not work with the Nikon 200mm f2G AF-S VR. If you’re using that lens, you should use this drop-in filter.', 104000.0, '{"Brand":"Nikon","Filter Format":"Drop-In","Filter Type":"Polarizing","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'Just the filter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2255, 5, 167, 'Nikon C-PL3L Drop-In Polarizing Filter', 'nikon-c-pl3l-drop-in-polarizing-filter', 'This is the drop-in circular polarizing filter for use with the Nikon 200mm f2G AF-S VR and Nikon 800mm f/5.6E FL ED AF-S VR only.  Its small rotating dial on the outside of the filter holder is used to adjust polarization.

This filter does not fit or work with any other Nikon lens. If you need a drop-in filter for any other Nikon Super Telephoto lens, look here.', 96000.0, '{"Brand":"Nikon","Filter Format":"Drop-In","Filter Type":"Polarizing","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'Just the filter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2256, 5, 167, 'Nikon C-PL405 40.5mm Drop-In Polarizing Filter', 'nikon-c-pl405-40-5mm-drop-in-polarizing-filter', 'The Nikon C-PL405 is the drop-in circular polarizing filter for specific Nikon super telephoto lenses. Key features include:

For Nikon 400 f/2.8E, 500 f/4E, and 600 f/4E
Reduces reflections and glare from non-metallic surfaces
Easy to install and use
Filter factor of 2 to 4x reduces exposures by 1 to 2 stops

Specific Compatibility. The Nikon C-PL405 Drop-In Polarizing Filter is only compatible with the Nikon 400mm f/2.8E, 500mm f/4E, and 600mm f/4E superteles.

Why Use It? Circular polarizers help to reduce reflections and glare from just about any non-metallic surface (think water, glass, electronic screens). They’ll clear up haze when shooting subjects at a great distance, all with a minimal drop in autofocus performance.

How to Use It. Just remove the drop-in UV filter near the lens mount, then replace it with this one. There’s a dial on the top of the filter holder that’s used to adjust polarization.

Filter Factor. Please keep in mind that this filter has a filter factor of 2 to 4×. This means reduced exposures by 1 to 2 stops.', 79000.0, '{"Brand":"Nikon","Filter Format":"Drop-In","Filter Type":"Polarizing","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'Just the filter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2257, 5, 167, 'Nikon C-PL460 Drop-In Circular Polarizer Filter', 'nikon-c-pl460-drop-in-circular-polarizer-filter', 'The Nikon C-PL460 Drop-In Circular Polarizer Filter is a 46mm rotating filter designed for select NIKKOR Z super-telephoto lenses. This filter limits reflections on surfaces such as water or glass, and saturates colors to deliver better contrast.', 146000.0, '{"Brand":"Nikon","Filter Format":"Drop-In","Filter Type":"Polarizing","Item Type":"Lens Support","Lens Support Type":"Filter"}', 'Nikon
C-PL460
