INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2364, 5, 167, 'Nikon Z TC-1.4x Teleconverter', 'nikon-z-tc-1-4x-teleconverter', 'The Nikon Z TC-1.4x Teleconverter is used to increase the focal length of compatible Nikon Z-series lenses. Key features include:

Nikon Z mount
