INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2397, 3, 175, 'OBSBOT Extendable Tripod', 'obsbot-extendable-tripod', 'The OBSBOT Extendable Tripod is designed for small cameras with a 1/4"-20 mounting thread, like the Tiny 4K AI-Powered PTZ 4K Webcam or Alpha a6400. Key features include:

