INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2430, 3, 179, 'OM SYSTEM RM-WR1 Wireless Remote Control', 'om-system-rm-wr1-wireless-remote-control', 'The OM SYSTEM RM-WR1 Wireless Remote Control lets you trigger the OM-1 camera’s shutter without disturbing the camera, making it great for close-ups, time exposures, self-portraits, and group photos.', 61000.0, '{"Brand":"OM SYSTEM","Camera Support Type":"Controller","Item Type":"Camera Support","Mfr. Model Number":"V3350800W000"}', 'OM
