INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2442, 3, 174, 'Oben Macro Focusing Rail (Long)', 'oben-macro-focusing-rail-long', 'The Oben Macro Focusing Rail (Long) is an aluminum-build Arca-style rail designed to provide precise camera-to-subject focusing. Key features include:

22 lb load capacity
Folding drive crank
Rotating Arca-Type plate
