INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2459, 2, 177, 'Olympus 45mm f/1.8 ED', 'olympus-45mm-f-1-8-ed', 'The Olympus 45mm f/1.8 ED is a short telephoto lens designed for Micro 4/3 cameras. Key features include:

Great for portraits and low-light shooting
Excellent contrast and sharpness
