INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2488, 2, 183, 'Panasonic 16-35mm f/4 S PRO', 'panasonic-16-35mm-f-4-s-pro', 'The Panasonic 16-35mm f/4 S PRO is a versatile wide-angle zoom for L-mount mirrorless cameras. Key features include:

Versatile wide-angle zoom
Fast, accurate, quiet autofocus; full-time manual override
Advanced optical design
Compatible with all L-mount cameras

