INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2490, 2, 183, 'Panasonic 24-105mm f/4 S Macro OIS', 'panasonic-24-105mm-f-4-s-macro-ois', 'The Panasonic 24-105mm f/4 S Macro OIS is a versatile wide-angle to short-telephoto zoom for L-mount mirrorless cameras. Key features include:

