INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2491, 2, 183, 'Panasonic 24-70mm f/2.8 S PRO', 'panasonic-24-70mm-f-2-8-s-pro', 'The Panasonic 24-70mm f/2.8 S PRO is a bright wide-angle to short-telephoto zoom designed for the L-mount system. Key features include:

