INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2492, 2, 183, 'Panasonic 25mm f/1.7', 'panasonic-25mm-f-1-7', 'The Panasonic 25mm f/1.7 is a compact normal-range lens for Micro 4/3 cameras. Key features include:

