INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2493, 2, 183, 'Panasonic 30mm f/2.8 OIS Macro', 'panasonic-30mm-f-2-8-ois-macro', 'The Panasonic 30mm f/2.8 OIS Macro is a true macro lens made for Micro 4/3 cameras and camcorders. Key features include:

