INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2494, 2, 183, 'Panasonic 35-100mm f/2.8 X Power OIS II', 'panasonic-35-100mm-f-2-8-x-power-ois-ii', 'The Panasonic 35-100mm f/2.8 X Power OIS II is a fast-aperture telephoto zoom lens. We now have the updated 35-100mm f/2.8 available. Key features include:

