INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2495, 2, 183, 'Panasonic 35-100mm f/4-5.6 OIS', 'panasonic-35-100mm-f-4-5-6-ois', 'The Panasonic 35-100mm f/4-5.6 OIS is an ultra-compact telephoto zoom lens for Micro 4/3 cameras and camcorders. Key features include:

