INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2505, 6, 183, 'Panasonic AC Adapter for S5', 'panasonic-ac-adapter-for-s5', 'The Panasonic AC Adapter for S5 provides continuous AC power to the Panasonic GH5 II and Lumix DC-S5 cameras. Key features include:

