INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2512, 6, 183, 'Panasonic AG-VBR118G High Capacity Battery', 'panasonic-ag-vbr118g-high-capacity-battery', 'The Panasonic AG-VBR118G is an 11,800 mAh high-capacity battery for the Panasonic AJ-PX270

Our cameras are shipped with a single battery. If you need additional batteries, you’re in the right place!

The Panasonic AG-VBR118G works with:

