INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2522, 6, 183, 'Panasonic DMW-BG1 Battery Grip', 'panasonic-dmw-bg1-battery-grip', 'The Panasonic DMW-BG1 provides extended battery power to select LUMIX mirrorless cameras like the S5 IIX, S5 II, and G9 II. Key features include:

Only for the LUMIX S5 IIX, S5 II, and G9 II
Provides extended battery power
Doubles as a vertical grip
