INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2541, 5, 183, 'Panasonic DMW-STC14 Lumix S 1.4x Teleconverter', 'panasonic-dmw-stc14-lumix-s-1-4x-teleconverter', 'The Panasonic DMW-STC14 Lumix S 1.4x Teleconverter is a durable, high-quality teleconverter. Key features include:

98-280mm effective focal length; one stop of light loss with the Panasonic 70-200mm f/4 S PRO OIS
Retains the attached lens’s original quality
Fully supports exposure metering, autofocus, and image stabilization
Weather-resistant build

Compatibility. The Panasonic DMW-STC14 Lumix S 1.4x Teleconverter is designed to work with the L-mount Panasonic 70-200mm f/4 S PRO OIS.

High Quality, Longer Reach. The DMW-STC14 1.4x gives you a 98-280mm effective focal length with only one stop of light loss. Advanced optics help retain the attached lens’s original quality while fully supporting exposure-metering, autofocus, and image-stabilization capabilities.

All-Weather Gear. This teleconverter’s weather-sealed construction reduces the chances of dust, water, or even the cold affecting performance.', 86000.0, '{"Brand":"Panasonic","Camera Mount":"L","Item Type":"Lens Support","Lens Mount":"L","Lens Support Type":"Teleconverter","Mfr. Model Number":"DMW-STC14"}', 'Just the teleconverter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2542, 5, 183, 'Panasonic DMW-STC20 Lumix S 2x Teleconverter', 'panasonic-dmw-stc20-lumix-s-2x-teleconverter', 'The Panasonic DMW-STC20 Lumix S 2x Teleconverter is a durable, high-quality teleconverter. Key features include:

140-400mm effective focal length; two stops of light loss with the Panasonic 70-200mm f/4 S PRO OIS
Retains the attached lens’s original quality
Fully supports exposure metering, autofocus, and image stabilization
Weather-resistant build

Compatibility. The Panasonic DMW-STC20 Lumix S 2x Teleconverter is designed to work with the Panasonic 70-200mm f/2.8 S PRO OIS and Panasonic 70-200mm f/4 S PRO OIS.

High Quality, Longer Reach. The DMW-STC20 2x gives you a 140-400mm effective focal length with only two stops of light loss. Advanced optics help retain the attached lens’s original quality while fully supporting exposure-metering, autofocus, and image-stabilization capabilities.

All-Weather Gear. This teleconverter’s weather-sealed construction reduces the chances of dust, water, or even the cold affecting performance.', 143000.0, '{"Brand":"Panasonic","Camera Mount":"L","Item Type":"Lens Support","Lens Mount":"L","Lens Support Type":"Teleconverter","Mfr. Model Number":"DMW-STC20"}', 'Just the teleconverter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
