INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2567, 2, 183, 'Panasonic Leica 15mm f/1.7 ASPH', 'panasonic-leica-15mm-f-1-7-asph', 'The Panasonic / Leica 15mm f/1.7 ASPH is a fast-aperture, moderately wide-angle lens for Micro 4/3 cameras and camcorders. Key features include:

