INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2581, 1, 183, 'Panasonic Lumix DC-G100D Mobile Vlog Kit', 'panasonic-lumix-dc-g100d-mobile-vlog-kit', 'This Panasonic Lumix DC-G100D Mobile Vlog Kit is a basic, beginner-friendly bundle that supplies you with everything needed to perfect your content creation. Based around the compact Panasonic Lumix DC-G100D, a notable vlogging camera, this kit provides you with power, a memory card and reader, a mic system, and much more. Feel free to click any of the highlighted links below for additional information and specifications!

