INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2640, 6, 188, 'Pentax K-BC92U Charger', 'pentax-k-bc92u-charger', 'The Pentax K-BC92U Charger is designed to charge the Pentax D-LI92 battery, which powers the Ricoh WG-80 Digital Camera. This kit includes a battery-charging cradle and an AC cord to connect it to a wall outlet. The charger is dual-voltage, so you can use it around the world with the right plug adapter.', 50000.0, '{"Brand":"Pentax","Item Type":"Power","Mfr. Model Number":"39805","Power Type":"Charger"}', 'Pentax
