INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2666, 3, 192, 'Proaim Big Multi-Angle Levelling Wedge Plate', 'proaim-big-multi-angle-levelling-wedge-plate', 'This Proaim Big Multi-Angle Levelling Wedge Plate is designed to provide better support and tilt angles for larger cameras on a rig, up to 44 pounds. Key features include:

For greater/extreme tilt angles
44 pound payload
0-90° tilt adjustment with ratchet lock
