INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2670, 6, 194, 'Profoto Charger for B-Series', 'profoto-charger-for-b-series', 'The Profoto Charger for B-Series is the dedicated charging system for the Profoto Li-Ion Battery for B-Series, which powers Profoto’s B10, B20, and B30 OCF flash heads. The B-Series battery can be charged to 100% in 90 minutes and to 80% power in 60 minutes with this charger. While the battery that that is in-use can be charged to prolong its life, please note that it must remain connected to AC power while it’s charging. It has a charge-power indicator, and includes a touch-fastener strap so you can attach it to a light stand.', 89000.0, '{"Brand":"Profoto","Item Type":"Power","Power Type":"Charger"}', 'Profoto
PCA3456 3A
Battery
