INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2681, 6, 199, 'RED DIGITAL CINEMA Compact Dual V-Mount Battery Charger', 'red-digital-cinema-compact-dual-v-mount-battery-charger', 'The RED DIGITAL CINEMA Compact Dual V-Mount Battery Charger is a compact, simultaneous, dual-battery charger for REDvolt Micro V-Mount Batteries. Key features include:

