INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2682, 3, 199, 'RED DIGITAL CINEMA Compact Top Handle', 'red-digital-cinema-compact-top-handle', 'The RED DIGITAL CINEMA Compact Top Handle is a grip attachment for the KOMODO-X, V-RAPTOR, or V-RAPTOR XL cameras. It features an ergonomic wood inlay, an integrated start/stop trigger, and a bunch of 1/4"-20 and 3/8"-16 thread points. Included is a 15mm mount for an optional monitor.', 154000.0, '{"Brand":"RED","Camera Support Type":"Handle","Dimensions":"2.6 × 4.5″ (ø x L)","Item Type":"Camera Support","Mfr. Model Number":"790-0725","Weight":"0.41 lb."}', 'Top handle trigger
