INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2685, 6, 199, 'RED DIGITAL CINEMA DSMC2 LEMO Adapter B', 'red-digital-cinema-dsmc2-lemo-adapter-b', 'The RED DIGITAL CINEMA DSMC2 LEMO Adapter B allows you to use a RED DSMC2 Touch 7-inch LCD or RED DSMC2 Touch 4.7-inch LCD with a RED EPIC or RED SCARLET brain. It mounts securely to the brain with captive screws, creating a 16-pin LEMO port that’s compatible with RED Touch, RED PRO, and RED EVFs, and it features two extra 1/4"-20 threaded holes for accessories.', 71000.0, '{"Brand":"RED","Item Type":"Power","Power Type":"Power Adapter"}', 'RED
DSMC2
LEMO
