B', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2686, 4, 199, 'RED DIGITAL CINEMA DSMC3 RMI Cable 39-inch', 'red-digital-cinema-dsmc3-rmi-cable-39-inch', 'The RED DIGITAL CINEMA DSMC3 RMI Cable 39-inch lets you connect your RED V-RAPTOR 8K VV DSMC3 or ST 8K VV DSMC3 Cinema Camera to a DSMC3 Touch 7-inch monitor. Its 39-inch length gives you more mounting options than the 10-inch cable that’s included with the DSMC3 Touch LCD, making it ideal for gimbal and shoulder-mount work.', 71000.0, '{"Brand":"RED","Cable Type":"Video","Item Type":"Cable","Length":"3.3’","Mfr. Model Number":"790-0703"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2687, 4, 199, 'RED DIGITAL CINEMA EXT-to-Timecode Cable 3ft', 'red-digital-cinema-ext-to-timecode-cable-3ft', 'The RED DIGITAL CINEMA EXT-to-Timecode Cable is a 3-foot accessory cable designed to specifically allow timecode input on a RED KOMODO 6K or RED V-RAPTOR via the 9-pin EXT LEMO port. The other end of the cable is common BNC and compatible with most timecode devices.', 68000.0, '{"Brand":"RED","Cable Type":"Sync","Connectors":"BNC, 9-pin EXT (RED, LEMO-style)","Item Type":"Cable","Length":"3.0’"}', 'EXT to timecode cable
BNC coupler', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
