INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2689, 3, 199, 'RED DIGITAL CINEMA KOMODO Expander Module', 'red-digital-cinema-komodo-expander-module', 'The RED DIGITAL CINEMA KOMODO Expander Module adds I/O like timecode, genlock, and control ports to a RED KOMODO 6K. Key features include:

Connects directly to RED KOMODO cameras
Timecode via BNC
Genlock via BNC
4-pin control port

Direct Attachement. The RED DIGITAL CINEMA KOMODO Expander Module uses for captive screws to attach directly to the bottom of a RED KOMODO 6K camera without adding excessive bulk to your rig. The expander also adds various 1/4"-20 and 3/8"-16 threaded holes to the camera’s base.

I/O Options. This expander adds BNC ports for timecode, genlock, and GPI as well as a 4-pin CTRL port and plugs into a KOMODO’s EXT port.', 157000.0, '{"Brand":"RED","Camera Support Type":"I/O Adapter","Inputs/Outputs":"Timecode: BNCControl: 4-pin 00B LEMO socketGPI: BNCGenlock: BNC","Item Type":"Camera Support","Physical":"MaterialAluminum Alloy"}', 'Just the expander', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2690, 3, 199, 'RED DIGITAL CINEMA KOMODO Outrigger Handle', 'red-digital-cinema-komodo-outrigger-handle', 'The RED DIGITAL CINEMA KOMODO Outrigger Handle is an add-on accessory grip for the RED KOMODO 6K camera with full 360-degree rotation and a conveniently placed button for starting and stopping the camera. You’ll also find to 1/4"-20 threaded holes for accessory mounting.', 143000.0, '{"Brand":"RED","Camera Support Type":"Handle","Item Type":"Camera Support","Physical":"Grip Rotation360 degreesCamera ControlsStart/StopAccessory Mounting(2) 1/4\\"-20 threaded hole"}', 'KOMODO outrigger handle
	3/16" driver', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2691, 3, 199, 'RED DIGITAL CINEMA KOMODO Riser Plate', 'red-digital-cinema-komodo-riser-plate', 'The RED DIGITAL CINEMA KOMODO Riser Plate is a durable aluminum riser designed to increase optical height to allow use of 15mm rod accessories. This plate requires the V-RAPTOR QR Platform. Key features include:

Only for RED KOMODO and KOMODO-X
