INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2704, 3, 199, 'RED DIGITAL CINEMA V-RAPTOR Wing Grip', 'red-digital-cinema-v-raptor-wing-grip', 'The RED DIGITAL CINEMA V-RAPTOR Wing Grip is an add-on accessory grip for the RED V-RAPTOR 8K VV DSMC3 Cinema Camera that adds a low profile grip and extra 1/4"-20 and ARRI-standard 3/8"-16 mounting points to either, or both sides of a RED V-Raptor camera.', 75000.0, '{"Brand":"RED","Camera Support Type":"Handle","Item Type":"Camera Support","Physical":"Dimensions4.21 × 1.45 × 1.07″Weight2.88 oz"}', 'Wing grip
