INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2707, 5, 199, 'RED DIGITAL CINEMA V-RAPTOR Z to PL Adapter', 'red-digital-cinema-v-raptor-z-to-pl-adapter', 'The RED DIGITAL CINEMA V-RAPTOR Z to PL Adapter is compatible with Z-mount V-RAPTOR cameras and PL-mount lenses.

