INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2739, 3, 199, 'RED V-RAPTOR Top Handle', 'red-v-raptor-top-handle', 'The RED V-RAPTOR Top Handle is a compact, ergonomic handle that makes it easy to carry your RED V-RAPTOR 8K VV DSMC3 or ST 8K VV DSMC3 Cinema Camera. The top and sides of the handle provide multiple 1/4"-20 and 3/8"-16 threaded accessory mounting points with anti-twist divots, and there’s even a mounting point with anti-twist divots on the front of the handle. A built-in run/stop trigger automatically connects when you secure the top handle to your camera, and there are wood inlays for comfort and temperature stability. You can attach the optional rear support arm for even greater security, but the top handle will also work without the rear support.', 193000.0, '{"Brand":"RED","Camera Support Type":"Handle","Controls":"Built-In Remote Trigger","Dimensions":"6.3 × 2.6 × 2.4″","Grip Type":"Topside Handle with Cheeseplate-Style Handle","Item Type":"Camera Support","Material":"Aluminum, Wood","Mfr. Model Number":"790-0689","Mount":"Attachment Method\\nAttaches via 2x Built-In 1/4\\"-20 Screw\\n\\nAccessory Mounting\\nHandgrip Shaft\\nMultiple x 1/4\\"-20 Thread\\nMultiple x Anti-Twist 3/8\\"-16 Thread\\n\\nShoe Mounting\\nNone\\n\\nRosettes\\nNone\\n\\nRail Mounting\\nNone"}', 'RED
