INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2743, 1, 199, 'RED V-RAPTOR XE RF Premium Kit (V-Mount)', 'red-v-raptor-xe-rf-premium-kit-v-mount', 'This is a Netflix approved camera! The RED V-RAPTOR XE RF Premium Kit (V-Mount) includes:

RED V-RAPTOR XE 8K VV for Canon RF
	RED V-RAPTOR tactical top plate with micro V-Lock adapter
	RED side ribs for V-RAPTOR
