INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2755, 6, 204, 'RODE Charging Case for Wireless GO II', 'rode-charging-case-for-wireless-go-ii', 'The RODE Charging Case for Wireless GO II is a compact and portable charging solution for the Wireless Go 2 transmitters and receiver. Key features include:

