INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2760, 4, 204, 'RODE VXLR 3.5mm TRS to XLR Adapter', 'rode-vxlr-3-5mm-trs-to-xlr-adapter', 'The RODE VXLR 3.5mm TRS to XLR Adapter lets you connect a mic with a TRS connector to a professional camera, recorder, or mixer’s XLR input. There is a 3.5mm female TRS connector at one end and an XLR male connector at the other.

This adapter is the predecessor to the RODE VXLR+ 3.5mm TRS to XLR Adapter with Phantom Power, which converts 12 to 48V phantom power down to 3 to 5V plug-in power.', 14000.0, '{"Brand":"Rode","Cable Type":"Adapter","Connector":"3-Pin XLR and 3.5mm TRS","Item Type":"Cable","Mfr. Model Number":"VXLR"}', 'Just the adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2761, 4, 204, 'RODE VXLR Pro Transformer-Balanced 3.5mm TRS to XLR Adapter', 'rode-vxlr-pro-transformer-balanced-3-5mm-trs-to-xlr-adapter', 'Using the RODE VXLR Pro Transformer-Balanced 3.5mm TRS to XLR Adapter allows you to connect a microphone to a recording device. This adapter ensures great signal quality over longer cables thanks to it’s transformer-balanced output, and even converts phantom power down to plug-in power so that mics and headsets can be powered via the XLR connector.', 39000.0, '{"Brand":"Rode","Cable Type":"Adapter","Connector":"3-Pin XLR and 3.5mm TRS","General":"In-Line Accessory TypePhantom Power ConverterTransformer TypePowerInput / Output LevelInput: Mic LevelOutput: Mic LevelNumber of Channels1ControlsNoneIndicatorsNonePhantom Power ConversionInput Voltage: 12 to 48 VOutput Voltage: 4 V","Item Type":"Cable","Mfr. Model Number":"VXLR PRO","Physical":"Dimensions (L x W x H)2.8 × 0.8 × 0.8″Weight0.2 lb."}', 'Just the adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2762, 4, 204, 'RODE VXLR+ 3.5mm TRS to XLR Adapter with Phantom Power', 'rode-vxlr-3-5mm-trs-to-xlr-adapter-with-phantom-power', 'The RODE VXLR+ 3.5mm TRS to XLR Adapter with Phantom Power lets you connect a mic with a TRS connector to a professional camera, recorder, or mixer’s XLR input. Unlike the standard VXLR adapter, the VXLR Plus converts 12 to 48V phantom power down to 3 to 5V plug-in power so that lab, headset, and shotgun mics can receive power from the XLR connector. This adapter is terminated by a threaded 3.5mm female TRS connector at one end and an XLR male connector at the other.', 29000.0, '{"Brand":"Rode","Cable Type":"Adapter","Connectivity":"I/O1x 1/8\\" / 3.5 mm TRS Female Output1x XLR 3-Pin Male Input","Connector":"3-Pin XLR and 3.5mm TRS","General":"In-Line Accessory TypePhantom Power ConverterInput / Output LevelInput: Mic LevelOutput: Mic LevelNumber of Channels1ControlsNone","Item Type":"Cable","Mfr. Model Number":"VXLR+","Physical":"Dimensions (L x W x H)2.3 × 0.7 × 0.7″Weight0.1 lb."}', 'Just the adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
