INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2765, 5, 200, 'Redrock Captain Stubling Black DSLR Rig', 'redrock-captain-stubling-black-dslr-rig', 'The Redrock Captain Stubling Black DSLR Rig is a lightweight handheld setup that’s designed for hybrid DSLRs. It includes the latest iteration of Redrock’s follow focus. Key features include:

