INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2792, 2, 202, 'Ricoh GT-2 Tele Conversion Lens', 'ricoh-gt-2-tele-conversion-lens', 'The Ricoh GT-2 Tele Conversion Lens combines with the included GA-2 lens adapter to mount to the Ricoh GRIIIx digital camera. The camera automatically detects the GT-2 and extends focal length to roughly a 75mm equivalent when using the camera’s crop mode, or to about 107mm in its secondary crop mode.', 71000.0, '{"Brand":"Ricoh","Item Type":"Lens","Lens Mount":"Add-on","Lens Type":"Specialty","Mfr. Model Number":"37827"}', 'Ricoh
