INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2793, 2, 202, 'Ricoh GW-4 Wide Conversion Lens', 'ricoh-gw-4-wide-conversion-lens', 'Widen your Ricoh GR III perspective with this Ricoh GW-4 Wide Conversion Lens! This 0.75x magnification lens adds a wide, 21mm equivalent focal length to the camera, while the included petal-shaped hood minimizes pesky glares and flares. Please note that this lens requires the separately available GA-1 Lens Adapter in order to secure to the camera.', 79000.0, '{"Brand":"Ricoh","Item Type":"Lens","Lens Mount":"Add-on","Lens Type":"Wide Angle","Mfr. Model Number":"#30248"}', 'Ricoh
