INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2854, 2, 205, 'Rokinon AF 35mm f/1.4 FE for Sony E', 'rokinon-af-35mm-f-1-4-fe-for-sony-e', 'The Rokinon AF 35mm f/1.4 FE for Sony E is a versatile, fast-aperture, wide-angle prime for full-frame Sony E-mount cameras. Key features include:

