INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2933, 3, 207, 'Sachtler Adapter for 75mm aktiv Head to Slider', 'sachtler-adapter-for-75mm-aktiv-head-to-slider', 'The Sachtler Adapter for 75mm aktiv Head to Slider is an add-on accessory for Sachtler aktiv fluid heads like the one found in the Sachtler aktiv14T MS Flowtech 100 Tripod System. This adapter is necessary to mount Sachtler SpeedSwap heads to sliders, since those heads don’t use a traditional mounting screws. This adapter will only work with those fluid heads, but can mount to any slider or support gear with a 3/8"-16 screw or threading.', 64000.0, '{"Brand":"Sachtler","Camera Support Type":"Fluid Head","Item Type":"Camera Support"}', 'Just the adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2934, 3, 207, 'Sachtler Aktiv Connector V2 for 75mm Bowl Tripod', 'sachtler-aktiv-connector-v2-for-75mm-bowl-tripod', 'This Sachtler Aktiv Connector for 75mm Bowl Tripod is a small adapter designed to attach a Sachtler aktiv6, aktiv8, or aktiv8T head to a 75mm bowl. Its SpeedSwap base and clamp-style attachment allows you to quickly switch between 75mm bowls, helping you maintain the flow of your production.', 71000.0, '{"Brand":"Sachtler","Camera Support Type":"Fluid Head","Compatibility":"TripodSachtler 75mm Bowl Headaktiv6aktiv8aktiv8T","Item Type":"Camera Support","Mfr. Model Number":"S2080-0012","Weight":"4.1 oz"}', 'Sachtler aktiv 75mm
Bowl
Connector
V2', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2935, 3, 207, 'Sachtler FSB 10 T FT MS Flowtech 100 Tripod System', 'sachtler-fsb-10-t-ft-ms-flowtech-100-tripod-system', 'The Sachtler FSB 10 T FT MS Flowtech 100 Tripod System is a complete fluid-head tripod kit that is capable of supporting cameras up to 26.5 lb. Key features include:

Fluid movement for cameras up to 26.5 lb
Height adjustable between 28" & 68"
10-step counterbalance & 5-step drag control
Extends with brake levers mounted at top of legs

Moderate to Heavy Weight Capacity. The FSB 10T fluid head offers a weight capacity of up to 26.5 lb. The tripod alone can support up to 66 lb on its 100mm bowl.

Quick Release. The FSB 10 T head features Sachtler’s Touch & Go plate system, enabling quick removal. Additionally, the integrated sliding baseplate offers 2.4" of sliding range for quick balancing.

