INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2937, 3, 207, 'Sachtler FSB 14T Mk II HotPod CF 14 System', 'sachtler-fsb-14t-mk-ii-hotpod-cf-14-system', 'The Sachtler FSB 14T Mk II HotPod CF 14 System is a heavy-duty, quick assembly tripod system with a pneumatic center column that extends the tripod’s maximum height up to 6.5 feet. Key features include:

