INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2941, 3, 207, 'Sachtler Heavy Duty Harness', 'sachtler-heavy-duty-harness', 'The Sachtler Heavy Duty Harness is an ergonomic vest-style harness designed to carry audio bags like the Sachtler Lightweight Audio Bag, transmitters and receivers, boom poles and support equipment, and extra cables and accessories in a comfortable, weight-relieving design perfect for field recording. Rated for up to 88 lbs of gear, this harness features a dedicated boom pole pocket, D rings for cables and accessories, a single expandable pouch for a transmitter, receiver, or other accessories, and includes adjustable straps and snap locks for a secure fit.', 86000.0, '{"Brand":"Sachtler","Camera Support Type":"Harness","Item Type":"Camera Support"}', 'Heavy duty harness', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
