INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2945, 3, 207, 'Sachtler aktiv Slider to 75mm Tripod Adapter', 'sachtler-aktiv-slider-to-75mm-tripod-adapter', 'The Sachtler aktiv Slider to 75mm Tripod Adapter allows you to mount sliders to tripods with a 75mm bowl. This adapter includes a plate for easy mounting and a bubble level to ensure your slider is mounted properly. This adapter has a maximum payload of 22 lbs, and can support sliders up to 23.6 inches in length. Please note, if you’ll be using a Sachtler aktiv SpeedSwap head like the one found in the Sachtler aktiv14T MS Flowtech 100 Tripod System, you’ll also need the Sachtler Adapter for 75mm aktiv Head to Slider, since these heads don’t use a traditional camera screw mounting system.', 139000.0, '{"Brand":"Sachtler","Camera Support Type":"Slider","Item Type":"Camera Support"}', 'Tripod to slider adapter
