INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2950, 4, 208, 'Sanho 2.6ft HyperThin HDMI Male-Mini', 'sanho-2-6ft-hyperthin-hdmi-male-mini', 'The Sanho 2.6ft HyperThin HDMI Male-Mini is an ultra-thin cable with full-size HDMI male (type-A) to Mini-HDMI (type C) connector. Key features include:

