INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2968, 4, 210, 'Semote SECP-2 Gigabit RX Splitter Cable w/ 2-Pin LEMO Power', 'semote-secp-2-gigabit-rx-splitter-cable-w-2-pin-lemo-power', 'This Semote SECP-2 Gigabit RX Splitter Cable w/ 2-Pin LEMO Power features three connectors designed for use with the Semote Wireless Controller for VRI Phantom Cameras – Gigabit and Cameo VEObob Accessory Kit for Phantom VEO4K to enable LAN connectivity between the Semote Control Unit and VRI Phantom cameras.  When connected to the Semote Phantom Receiver (Gigabit) 915MHz, this cable allows for effective communication and control functionalities between the Control Unit and camera. This cable connects to the Semote Phantom Receiver (Gigabit) 915MHz via a 10-pin LEMO connector. The 8-pin Fisher connector marked by yellow attaches to the Ethernet port on the Phantom VEO4K. The 2-pin LEMO connector marked by white connects to one of the 12V ports on the VEObob. This configuration gives the Semote Control Unit full wireless camera menu control of the Phantom VEO4K.', 86000.0, '{"Brand":"Semote","Cable Type":"Breakout","Item Type":"Cable"}', 'Semote
SECP-2
Gigabit
RX
Splitter
Cable w/ 2-Pin
LEMO
Power', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2969, 4, 210, 'Semote SECP-4 Phantom RS Cable', 'semote-secp-4-phantom-rs-cable', 'This Semote SECP-4 Phantom RS Cable is a 15-inch cable designed for use with the Semote Wireless Controller for VRI Phantom Cameras – Serial to enable wireless connectivity between the Control Unit and VRI Phantom cameras when using the Cameo VEObob Accessory Kit for Phantom VEO4K. When connected to the Semote RED Receiver (RS) 915MHz, this cable allows for effective communication and control functionalities between the Control Unit and camera. The cable connects to the Semote RED Receiver (RS) 915MHz via a 10-pin LEMO connector, while the 5-pin Fisher connector attaches to the Remote port on the VEObob giving the Semote Control Unit full wireless camera menu control of the Phantom VEO4K.', 86000.0, '{"Brand":"Semote","Cable Type":"Control","Item Type":"Cable"}', 'Semote
Phantom
RS
Cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2970, 3, 210, 'Semote Wireless Controller for VRI Phantom Cameras (Gigabit)', 'semote-wireless-controller-for-vri-phantom-cameras-gigabit', 'The Semote Wireless Control Unit for VRI Phantom Cameras (Gigabit) connects a Control Unit and VRI Phantom camera giving full wireless camera menu control to the operator. Key features include:

Remotely control essential camera functions
Natively compatible with VEO4K
Powered via the camera’s ViewFinder power port
Wireless camera control for Phantom cameras up to 300ft

10x Phantom Control. The Semote Wireless Controller for VRI Phantom Cameras (Gigabit) supports up to 10 profiles for things like FPS, EI, WB, and Shutter speed right from the controller. Plus, it supports up to 10 camera IP addresses for easy switching between setups.  The controller gives you remote access to your Phantom camera’s menu. It’s perfect for DITs, DPs, and Camera Operators who need remote access to adjust camera settings. The Controller lets you view all your camera info on your own screen and tweak most settings. There’s even an intervalometer to help you manage your camera’s shutter remotely.

Wireless. The receiver operates at 915MHz with a radio control range of 100-300 feet (depending on line of sight). This setup is great for aerial shots, crane operations, car scenes, and long-distance shooting.

Camera Connection. The Remote connects to the camera via a 10-pin LEMO connector that plugs into the camera’s Ethernet port using an 8-pin Fisher connector. Power is supplied through a Hirose connector via the camera’s ViewFinder power port. When used with the Semote Control Unit, this setup provides seamless wireless control of the Phantom VEO4K camera menu.', 943000.0, '{"Brand":"Semote","Camera Support Type":"Controller","Item Type":"Camera Support"}', 'Semote
