INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2978, 4, 211, 'Sennheiser GZL RG 58 Coaxial RF Antenna Cable (16.4-ft)', 'sennheiser-gzl-rg-58-coaxial-rf-antenna-cable-16-4-ft', 'The Sennheiser GZL RG 58 Coaxial RF Antenna Cable is a 16.4 foot male-male coax cable designed for use with antennas and RF distribution systems. It has a maximum signal loss of 34.8dB per 100m at 400 MHz (56.4dB at 800 MHz), allowing you to connect several cables (like with a ground block or similar) before any significant loss. This cable is recommended for wireless audio-related applications.', 43000.0, '{"Brand":"Sennheiser","Cable Type":"Video","Connector":"Coax","General":"Dimensions (ø x L)0.24″ × 16.4′","Item Type":"Cable","Length":"16.4’","Performance":"Max Operating Frequency1000 MHzMax Attenuation34.8dB per 100m (328’) at 400 MHz, 56.4dB per 100m at 800 MHzImpedance50 Ohms"}', 'Sennheiser
