INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2979, 6, 213, 'Shure SB900B Rechargeable Lithium-Ion Battery', 'shure-sb900b-rechargeable-lithium-ion-battery', 'The Shure SB900B is a single, rechargeable battery for select Shure products. Key features include:

750 mAh capacity, lithium-ion
Up to 8.5 hours of battery life
Overheating protection
180 minute approximate charge time

This battery will charge select Shure products, including the ULXD2 wireless transmitter, the P10R+ bodypack receiver, and the UR5, QLX-D, or P9RA systems. It does not come with a spare charger. If you need a charger, be sure to grab the Shure SBC10-100-US.', 79000.0, '{"Brand":"Shure","Item Type":"Power","Power Type":"Battery"}', 'Shure
SB900B rechargeable lithium-ion battery', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (2980, 6, 213, 'Shure SB904 Rechargeable Battery for GLX-D+ Transmitters', 'shure-sb904-rechargeable-battery-for-glx-d-transmitters', 'The Shure SB904 Rechargeable Battery for GLX-D+ Transmitters powers a GLX-D1+ or GLX-D2+ transmitter for up to 12 hours on a full charge. This battery fuels up in a few different ways, including the SBC10-904 Charger, directly from the front panel of a GLXD4+ and GLXD4R+ receiver, or while attached to the transmitter via the USB-C connector. The SB904 offers a nominal capacity of 2420mAh, and weighs only 1.9 ounces.', 43000.0, '{"Battery":"Battery ChemistryLithium-Ion Battery Capacity2420 mAh / 8.71 Wh Output Voltage3.6 VDC Recharge Time .25 to 3 Hours Maximum Battery Life12 Hours","Brand":"Shure","Compatibility":"Shure GLX-D+ GLXD1+ / GLX-D+ GLXD2+","Item Type":"Power","Operating Temperature":"32 to 122°F","Physical":"Dimensions2.9 × 0.83 × 0.8″  Weight1.9 oz","Power Type":"Battery"}', 'Shure
