INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3050, 2, 214, 'Sigma 17-40mm f/1.8 DC Art for L-Mount', 'sigma-17-40mm-f-1-8-dc-art-for-l-mount', 'The Sigma 17-40mm f/1.8 DC Art for L-Mount is a compact zoom lens that delivers prime-like optical performance and functionality through APS-C sensor L-Mount cameras. Key features include:

