INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3074, 2, 214, 'Sigma 20mm f/2 DG C for Sony E', 'sigma-20mm-f-2-dg-c-for-sony-e', 'The Sigma 20mm f/2 DG C is an ultra wide angle prime for full-frame E-mount cameras and an update to the Sigma 20mm f/2 DG DN Contemporary. Key features include:

Very portable at 2.8 × 2.9″
Stepping AF motor
Part of Sigma’s I Series
