INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3083, 2, 214, 'Sigma 24-35mm f/2 DG HSM Art for Nikon F', 'sigma-24-35mm-f-2-dg-hsm-art-for-nikon-f', 'The Sigma 24-35mm f/2 DG HSM A1 for Nikon is a professional-caliber, fast-aperture, wide-angle lens designed for Nikon F-mount cameras. Key features include:

