INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3212, 2, 214, 'Sigma Cine 105mm T1.5 FF Prime with /i Technology (PL)', 'sigma-cine-105mm-t1-5-ff-prime-with-i-technology-pl', 'The Sigma Cine 105mm T1.5 FF Prime with /i Technology is a fast, pro-grade cine lens for PL-mount cameras and camcorders. It’s an enhanced version of the Sigma Cine 105mm T1.5 FF Prime. Key features include:

