INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3257, 2, 214, 'Sigma Cine 50mm T1.5 FF Prime w/ i Technology (PL)', 'sigma-cine-50mm-t1-5-ff-prime-w-i-technology-pl', 'The enhanced Sigma Cine 50mm T2.0 FF Prime w/ i Technology combines the same high-quality optics and mechanics of its FF prime line with a cine-oriented design, and it now utilizes Cooke /i Technology that provides lens metadata. Key features include:

Covers full-frame sensor sizes
