INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3342, 4, 217, 'SmallHD Camera Control Cable for RED 4-Pin RCP Outputs', 'smallhd-camera-control-cable-for-red-4-pin-rcp-outputs', 'The SmallHD Camera Control Cable for RED 4-Pin RCP Outputs allows you to control a RED DSMC2 camera or the RED KOMODO to be controlled via a breakout box using a SmallHD monitor like the FOCUS Pro with the RCP2 Camera Control Software from SmallHD. The 5-pin connector plugs directly into a SmallHD monitor or adapter and the push-pull locking 4-pin LEMO-type connector plugs into the 4-pin control port on the breakout box. The cable measures 18" long.', 86000.0, '{"Brand":"SmallHD","Cable Type":"RED","Item Type":"Cable"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3343, 6, 217, 'SmallHD D-Tap Power Adapter for 500 / 700 Series Monitors', 'smallhd-d-tap-power-adapter-for-500-700-series-monitors', 'The SmallHD D-Tap Power Adapter for 500/700 Series Monitors lets you use an external power source with your 500- and 700-series onboard monitor. The adapter is shaped like an LP-E6 battery and mounts to one of the monitor’s battery slots.

This rental includes a three-foot D-Tap-to-barrel power cable, which connects the adapter to many batteries’ D-Tap outputs. This powers your monitor for longer than LP-E6 batteries.', 89000.0, '{"Brand":"SmallHD","Cable Length":"36\\"","Item Type":"Power","Power Type":"Power Adapter"}', 'D-Tap power adapter
