INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3346, 3, 218, 'SmallRig 1860 25mm Rod Clamp for Gimbal Stabilizers', 'smallrig-1860-25mm-rod-clamp-for-gimbal-stabilizers', 'The SmallRig 1860 25mm Rod Clamp for Gimbal Stabilizers lets you mount additional accessories on the DJI Ronin 2 3-Axis Handheld Stabilizer, in addition to any other items with 25mm or 1.0-inch rods. Specifically, you can use it to mount your V-Mount battery on top of your Ronin to power all of your accessories to minimize camera weight on the gimbal.

It has an array of 1/4-inch and 3/8-inch screw holes that let you install items like EVF mounts, ballheads, and cold shoe mounts.', 39000.0, '{"Brand":"SmallRig","Camera Support Type":"Rod Component","Item Type":"Camera Support"}', 'Just the mount', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
