Plate', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3352, 3, 218, 'SmallRig Extension Rig for Sony FX3 / FX3A XLR Handle', 'smallrig-extension-rig-for-sony-fx3-fx3a-xlr-handle', 'The SmallRig Extension Rig for Sony FX3 / FX3A XLR Handle extends the handle’s grip by 1.2-inches, and allows the addition of accessories via multiple 1/4"-20 and 3/8"-16 ARRI-style accessory threads, a shoe mount, and a NATO rail. Designed for use with the FX3 and FX3A, this unit installs onto the back of the handle using two included 1/4"-20 screws, and the NATO rail is removable.', 39000.0, '{"Brand":"SmallRig","Camera Support Type":"Baseplate","Dimensions":"4.7 × 1.3 × 1.1″","Interface":"(2) 1/4\\"-20 screws","Item Type":"Camera Support","Material":"Aluminum","Mounting":"Multiple 1/4\\"-20 threads\\nMultiple 3/8\\"-16 threads\\nOne NATO rail"}', 'SmallRig
