INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3360, 6, 218, 'SmallRig NP-F970 Dual-Battery and Charger Kit', 'smallrig-np-f970-dual-battery-and-charger-kit', 'The SmallRig NP-F970 Dual-Battery and Charger Kit will power any device that uses Sony NP-F-type batteries. Equipped with a fully decoded chip, the NP-F970 battery can be used with a multitude of Sony cameras without causing pop-up windows or any incompatibility issues, and it’s the exact size of the original Sony model. Dual fast charging allows you to charge both batteries simultaneously, or you can charge them individually in order to keep working with one as the other recharges. The charger features a digital LCD screen readout for monitoring charging status in real time.', 75000.0, '{"Battery Capacity":"7800 mAh","Brand":"SmallRig","Chemistry":"Lithium-ion","Connectors":"Micro-USB (x1)\\nUSB Type-C (x1)","Item Type":"Power","Output Voltage":"7.2 V","Power Type":"Battery, Charger, and Kit"}', 'SmallRig
