INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3368, 4, 219, 'Sony 3-Pin XLR to 5-pin XLR Cable', 'sony-3-pin-xlr-to-5-pin-xlr-cable', 'The Sony 3-Pin XLR to 5-pin XLR Adapter Cable connects a Sony ECM-series microphone with a 3-pin XLR output to the 5-pin XLR input on the front of a video camera, feeding a mono microphone signal to both channels of the camera.', 46000.0, '{"Brand":"Sony","Cable Type":"Audio","Connector":"3-Pin XLR and 5-Pin XLR","Item Type":"Cable","Length":"1.6’"}', 'Sony 3-Pin to 5-pin
XLR
