INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3412, 6, 219, 'Sony BP-U100 Battery', 'sony-bp-u100-battery', 'The Sony BP-U100 Battery is a higher-capacity alternative to the Sony BP-U90 Battery. It offers 97Wh vs. the 85Wh of the BP-U90. It communicates status data to the camera, and the camera’s viewfinder will display the remaining battery capacity. A 4-LED gauge displays remaining capacity at 20, 40, 60, and 80%. This battery recharges in roughly 210 minutes using the BC-U1A Charger.

This battery works with:

