INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3413, 6, 219, 'Sony BP-U35 Lithium-Ion Battery Pack', 'sony-bp-u35-lithium-ion-battery-pack', 'The Sony BP-U35 is a high-performance 35Wh lithium-ion battery compatible with select Sony professional video cameras, such as the FS7.

The Sony BP-U35 Lithium-Ion Battery Pack is designed to communicate status data to the camera, and remaining capacity is displayed on the camera’s viewfinder. This battery is rechargeable in approximately 90 minutes using the optional BC-U1A/U2A charger. A 4-LED gauge displays remaining capacity as 20, 40, 60, and 80%.', 89000.0, '{"Battery Capacity":"35 Wh","Battery System":"BP-U","Brand":"Sony","Charging Temperature":"32-104 °F","Chemistry":"Lithium-ion","Dimensions":"2.7 × 1.8 × 1.6″","Item Type":"Power","Output Voltage":"14.4 VDC","Power Type":"Battery"}', 'Sony
