INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3416, 6, 70, 'Sony BP-U70 Dolgin Power Kit', 'sony-bp-u70-dolgin-power-kit', 'The Sony BP-U70 Dolgin Power Kit offers multiple BP-U70 Sony batteries to accommodate your filming needs. Key features include:

Six BP-U70 Sony batteries
Dolgin TC400 four position charger
Custom carry case
150 minute runtime per battery

Film. Sony Style. We get it. Sometimes a single battery and charger simply will not do. We created this Sony BP-U70 Dolgin Power Kit as a one-stop shop for your Sony BP-series battery needs. The Sony BP-U70 Dolgin Power Kit works with the Sony PXW-FS7M2 4K XDCAM, Sony PXW-FS7, Sony PXW-FS5 XDCAM w/ FS RAW Upgrade, Sony PXW-FS5, Sony PXW-X180, and the Sony PXW-X200 XDCAM.', 550000.0, '{"Brand":"Dolgin","General":"Battery\\n\\n Mount / Series TypeSony BP-U Series ChemistryLithium-Ion Battery Capacity72 Wh Output Voltage14.4 VDC Accessory PortNone Charging Temperature32 to 104°F  Discharging Temperature -4 to 113°F  \\n  Charger \\n\\n AC Input Power100 to 240 VAC, 50 / 60 Hz Recharge Time4 Hours ChemistryLithium-Ion","Item Type":"Power","Physical":"Battery\\n Dimensions(W x H x D)\\t2.74 × 3.33 × 1.63″ Weight15.87 oz  \\n Charger\\n  Dimensions8.4 × 2.5 × 6.6″  Weight4 lb","Power Type":"Battery, Charger, and Kit"}', 'Dolgin
