INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3417, 6, 219, 'Sony BP-U90 Battery', 'sony-bp-u90-battery', 'The Sony BP-U90 is a Sony camcorder battery that’s been supplanted by the Sony BP-U100 Battery, which offers a higher capacity at a similar price, and the Hawk-Woods BP-98UX BP-U Series Battery, which is more powerful and more compact.

