INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3427, 1, 219, 'Sony Cyber-Shot RX100 VII SGR1 Shooting Grip Kit', 'sony-cyber-shot-rx100-vii-sgr1-shooting-grip-kit', 'Built with vlogging in mind, the Sony Cyber-Shot RX100 VII SGR1 Shooting Grip Kit pairs an advanced, compact point-and-shoot camera with a compact tripod / grip combo with grip controls for shutter release, video record, and zoom. The added spare battery, charger, 128GB SDXC memory card, and SD card reader make this a truly one click option for producing video on the fly. Click on any of the package items below for more information.

