INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3430, 6, 219, 'Sony DC-C1 DC Coupler', 'sony-dc-c1-dc-coupler', 'The Sony DC-C1 DC Coupler is a “dummy battery” that replaces either an NP-FW50 or an NP-FZ100 battery inside your camera and connects to an AC outlet for continuous wall power – a great feature for long indoor shoots. This rental is just for the coupler. A USB PD AC wall adapter and USB-C cable are not included. The coupler is attached to a 5.2’ cable, allowing you some movement even while tethered to an outlet.', 82000.0, '{"Battery System":"NP-FW and NP-FZ","Brand":"Sony","General":"Mfr. Model NumberDC-C1Dimensions (W x H x D)2.8 × 2 × 1.3″ (dummy battery)5.2’ long (coupler cable)Weight6.5 oz.","Inputs/Outputs":"USB-C (cable not included)","Item Type":"Power","Power Type":"Power Adapter"}', 'Sony
