INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3442, 2, 219, 'Sony E 18-110mm f/4 G PZ OSS', 'sony-e-18-110mm-f-4-g-pz-oss', 'The Sony E 18-110mm f/4 G PZ OSS is a Super 35, crop-sensor E-mount zoom lens designed for the PXW-FS5/FS5-RAW/PXW-FS7 camcorders. It’s not compatible with full-frame sensors. Key features include:

