INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3526, 6, 219, 'Sony Flight Battery for Airpeak S1 Drone', 'sony-flight-battery-for-airpeak-s1-drone', 'The Sony Flight Battery for Airpeak S1 Drone is an add-on accessory for the Sony Airpeak S1 Professional Drone & Gremsy Gimbal T3 Kit. If you need an extra battery with your rental, you’ve come to the right place. This 2518mAh battery provides up to 22 minutes of flight time without a payload, so expect reduced times when flying with a gimbal and camera attached. Please note, if the batteries have more than a 20% charge difference, the drone motors will not engage. This rental does not include a charger, but we do have the charger available as a separate rental product.', 89000.0, '{"Battery":"Capacity2518mAh Lithium-IonMaximum Battery Life22 minutes (without payload)","Brand":"Sony","Item Type":"Power","Physical":"Dimensions6 × 3 × 2.3″Weight1.43 lb","Power Type":"Battery"}', 'Just the battery', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3527, 3, 219, 'Sony GP-VPT2BT Wireless Shooting Grip', 'sony-gp-vpt2bt-wireless-shooting-grip', 'The Sony GP-VPT2BT Wireless Shooting Grip is an accessory grip for handheld shooting that also doubles as a compact tabletop tripod. It’s compatible with select Sony cameras that feature Bluetooth connectivity. Key features include:

Larger, more comfortable grip when shooting hand-held
Doubles as a tabletop tripod
Durable, weather-sealed build
Works with select Bluetooth-compatible Sony cameras

Improved Stability and Convenience. The Sony GP-VPT2BT Wireless Shooting Grip provides a larger, more comfortable grip when shooting hand-held. Its built-in shutter-release button, customizable C1 button, and zoom rocker switch all offer you wireless camera control via Bluetooth. Its integrated head can tilt upward 80° (40° in tripod mode), downward 90°, and rotate 360° for easy positioning.

Tabletop Tripod. In addition to being a more comfortable accessory grip, the GP-VPT2BT doubles as a durable tabletop tripod for hands-free shooting.

Durable, Weather-Sealed Build. The GP-VPT2BT grip features the same dust- and moisture-sealed design as the Sony’s weather-resistant camera bodies.

Compatibility. This grip is compatible with the Sony a9, a9 II, a7 III, a7R III, a7R IV, a6400, a6600, a6100, RX0 II, and RX100 VII.', 75000.0, '{"Brand":"Sony","Camera Support Type":"Tripod and Controller","Connectivity":"Bluetooth v4.2 (2.4 GHz)","Dimensions":"With Legs Folded: 2 × 6.8 × 1.7″\\nWith Legs Unfolded: 5.8 × 5.3 × 6.4″","Item Type":"Camera Support","Mfr. Model Number":"GP-VPT2BT","Operating Temperature":"14-122°F / -10-50°C","Panning Angle":"360°","Power Source":"1x CR2032 Lithium-Ion Battery","Tilt Angle":"As Grip: +80°, -90°\\nAs Tripod: +40°, -90°"}', 'Sony
GP-VPT2BT
Grip', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3528, 3, 219, 'Sony GP-VR100 Remote Control Grip for BURANO', 'sony-gp-vr100-remote-control-grip-for-burano', 'The Sony GP-VR100 Remote Control Grip for BURANO puts frequently used controls like focus, zoom, iris, and run/stop within thumb’s reach, making it an ideal companion to any BURANO, PXW-Z300 or FX6 setup. Key features include:

For Sony BURANO, PXW-Z300 and FX6 cameras
Length and angle adjustability
Customizable functions and focus, zoom, iris, and run/stop controls
Connects via LANC

Remote Control. The Sony GP-VR100 Remote Control Grip for BURANO is an articulating handle with a LANC connector, an iris dial, and support for run/stop, focus, zoom, and customizable functions. The length and angle can be adjusted for comfortable positioning.

Sony Cine. This remote control grip is only natively compatible with the BURANO 8K. Both the Sony PXW-Z300 and FX6 will require a rosette attachment point.', 457000.0, '{"Brand":"Sony","Camera Support Type":"Controller","Item Type":"Camera Support"}', 'Sony
GP-VR100
Remote
Control
Grip for
BURANO', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3529, 3, 219, 'Sony GP-X1EM Grip Extension', 'sony-gp-x1em-grip-extension', 'Improve the comfort and stability of your a9, a7 II, or a7 III series camera with the GP-X1EM Grip Extension from Sony.

The Sony GP-X1EM Grip Extension mounts to your camera’s tripod socket and gives you a larger, taller, and more ergonomic grip on your camera while improving comfort and stability. It boasts a durable aluminum construction.

This grip extension works with:

Sony Alpha a9
	Sony Alpha a7 III
	Sony Alpha a7S II
	Sony Alpha a7R II
	Sony Alpha a7R III', 93000.0, '{"Brand":"Sony","Camera Support Type":"Baseplate","Dimensions":"2.25″ × 3.75″ × .84″","Item Type":"Camera Support","Material":"Aluminum"}', 'Sony
