INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3535, 6, 219, 'Sony LBP-HM1 Enhanced Battery for Airpeak S1', 'sony-lbp-hm1-enhanced-battery-for-airpeak-s1', 'The Sony LBP-HM1 Enhanced Battery for Airpeak S1 is a spare battery for the Airpeak drone that provides up to thirty minutes of flight time without a payload. If you’re anticipating longer flights, this is the battery to get, but you’ll need two to power the drone.', 111000.0, '{"Battery Capacity":"3938mAh","Brand":"Sony","Item Type":"Power","Maximum Flight Time":"30 minutes (without payload)","Physical":"Dimensions\\n6×3×2.3″\\n\\nWeight\\n1.96 lb","Power Type":"Battery"}', 'Just the battery', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3536, 5, 219, 'Sony NEX to Canon EF Lens Adapter', 'sony-nex-to-canon-ef-lens-adapter', 'The Sony NEX to Canon EF Lens Adapter lets you mount a Canon EF lens onto a Sony NEX E-mount camera. Key features include:

Mounts Canon EF lenses on Sony NEX E-mount cameras
Manual focus and aperture only
Great value

Basic Adapter. The Sony NEX to Canon EF Lens Adapter is a simple, non-electronic adapter that lets you mount a Canon EF lens onto a Sony NEX E-mount camera. Since the adapter transmits no electronic signal, you won’t have control of aperture, autofocus, or image stabilization. In order to adjust aperture, you’ll have to do so on a Canon camera before removing the lens. The aperture you select on the adapter won’t be displayed on the camera, and it won’t show up in the EXIF data.

Please Note: This adapter won’t work with Canon lenses that have electronically controlled manual focus, such as the Canon 85mm f1.2L and Canon 50mm f1.0L.', 168000.0, '{"Brand":"Sony","Camera Mount":"Sony E","Item Type":"Lens Support","Lens Mount":"Canon EF","Lens Support Type":"Mount Adapter"}', 'Just the adapter', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3537, 6, 219, 'Sony NP-BJ1 Battery for RX0 / RX0 II Camera', 'sony-np-bj1-battery-for-rx0-rx0-ii-camera', 'The NP-BJ1 3.7V 700mAh Li-Ion Battery from Sony is compatible with the Sony DSC-RX0M2, DSC-RX100M7, and DSC-RX100M7G ultracompact cameras.

The Sony NP-BJ1 Battery is a rechargeable 3.7V, 700mAh lithium-ion battery for the Sony RX0 and RX0 II. It can capture approximately 240 stills or between 35 and 60 minutes of video footage on a single charge.

We include one battery with each camera rental, but if you need any spares, you’ve come to the right place!', 39000.0, '{"Brand":"Sony","Item Type":"Power","Power Type":"Battery"}', 'Just the battery', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
