INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3548, 6, 219, 'Sony NPA-MQZ1K Multi Battery Adapter Kit', 'sony-npa-mqz1k-multi-battery-adapter-kit', 'The Sony NPA-MQZ1K Multi Battery Adapter Kit gives you additional power for compatible Sony cameras. Key features include:

For NP-FZ100 and NP-FW50 compatible cameras
