INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3559, 1, 219, 'Sony PXW-X180 Full HD XDCAM', 'sony-pxw-x180-full-hd-xdcam', 'The Sony PXW-X180 XDCAM Handheld Camcorder is a predecessor to the more advanced PXW-Z200 4K XDCAM and PXW-Z300. Key features include:

3-chips 1/3" 2MP CMOS sensor
26-650mm F/1.6-11 25x optical zoom
Capture 4:2:2 10-bit HD up to 50 Mbps with 2x SxS slots
Dual variable ND control and wireless network functions

Professional Codecs. The PXW-X180 XDCAM uses Sony’s XAVC codec to deliver 10-bit 4:2:2 footage at data rates exceeding 100 Mbps.

25x Optical Zoom. Reach even farther with a 26-650mm f/1.6-f/11 (Super 35mm equivalent) zoom lens.

Ultra-Fast Capture. The X180 can capture at speeds up to 60 fps in 1080p and 120 fps in 720p for 5x over-cranked footage.', 936000.0, '{"Battery":"Compatibility BP-U60 (included)   \\t  Life \\t163 mins. (BP-U60)","Brand":"Sony","Camera Type":"Camcorder","Compatible Media":"SXS","Dimensions":"7.54 × 7.93 × 16.22 (inches)","Filter Diameter":"82 mm","Inputs/Outputs":"Audio Inputs         2x XLRs for audio input: 3-pin female; line, mic, mic +48 V selectable     Audio Output         1x Stereo mini-jack for earphone output1x Monitor speaker: monaural, 250 mW     Video Outputs        1x 3G-SDI, BNC  1x HDMI output type A     Additional Inputs/Outputs         1x Composite BNC1x USB 2.0 (device), mini-B type1x DC jack for DC input","Iris":"f/1.6 – f/11, auto/manual selectable","Item Type":"Camera","Lens Focal Length Equivalent":"26 – 650mm","Maximum Video Resolution":"1080p","Memory Type":"2x slots for SxS cards, 1x SD card slot (proxy files only)","Screen Type":"Tilt","Sensor":"3x 1/3\\" type Exmor CMOS sensor","Sensor Size":"1/3","Stabilization":"Yes","Video Formats":"XAVC-Intra/Long, MPEG HD422/420","Viewfinder Type":"Electronic","Weather Sealing":"No","Wireless Connectivity":"Wi-Fi"}', 'PXW-X180 camcorder
