INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3573, 3, 219, 'Sony RM-VPR1 Multi-Terminal Remote Shutter Release', 'sony-rm-vpr1-multi-terminal-remote-shutter-release', 'The Sony RM-VPR1 is a wired remote shutter release that’s compatible with a wide variety of Sony Alpha cameras.  Key features include:

Remote shutter release
Wired connection
