INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3632, 6, 224, 'Switronix PB70C PowerBase Charger', 'switronix-pb70c-powerbase-charger', 'The Switronix PB70C PowerBase Charger is a spare charger for the various Switronix PowerBase-70 models.  Each PowerBase-70 already includes one charger, so this listing is for spares.

The Switronix PB70C PowerBase Charger is a spare charger for the various Switronix PowerBase-70 models.  Each PowerBase-70 already includes one charger, so this listing is for spares.', 39000.0, '{"Brand":"Switronix","Item Type":"Power","Power Type":"Charger"}', 'Just the charger', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3633, 6, 224, 'Switronix PowerBase 70 Battery Pack', 'switronix-powerbase-70-battery-pack', 'Switronix PB70 Battery Pack is a 70Wh 14.8V rechargeable battery pack. We also carry the newer, comparable Anton Bauer Titon Base. Key features include:

70Wh, 14.8V lithium-ion battery
One D-Tap connector
Attaches via 1/4"-20 quick-release plate
Excellent value

External Battery Pack. This version of PowerBase 70 allows you to power just about anything that features a D-Tap/P-Tap power input. With one D-Tap connector, you’re able to power up one 12 V accessory.  If you need multiple D-tap inputs, consider also renting the D-Tap to Multitap Cable.

Handheld Use. The Powerbase 70 attaches to the bottom of the camera via 1/4"-20 quick-release plate, allowing you to work without a large setup.', 86000.0, '{"Brand":"Switronix","Item Type":"Power","Power Type":"Battery and Charger"}', 'Powerbase-70
Quick release plate
Charger', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3634, 6, 224, 'Switronix Powerbase-70 for Canon HDSLR', 'switronix-powerbase-70-for-canon-hdslr', 'The Switronix Powerbase-70 for Canon HDSLR is a 70Wh 14.8 V lithium-ion battery pack designed for use with Canon HDSLRs that take Canon LP-E6 and LP-E6N batteries. Key features include:

Extends battery life
Includes two D-Tap connectors
Allows hand-held use
Excellent value

Extended Battery Life. The Switronix Powerbase-70 provides nearly six times the battery life of a single LP-E6 battery.

D-Tap Connectors. This battery pack features two D-Tap connectors, allowing you to power up to two additional 12 V accessories.

Hand-Held Use. The Powerbase-70 attaches to the bottom of the camera via 1/4"-20 quick-release plate, letting you work without a large setup. However, it also has the flexibility of a 12-inch DC cable if you’re mounting it to a large support rig.

This battery pack works with:

Canon 5D Mark IV / 5D Mark III / 5D Mark II
	Canon 5DS / 5DS R
	Canon 6D / 7D
	Canon 7D Mark II
	Canon 80D / 70D', 86000.0, '{"Brand":"Switronix","Item Type":"Power","Power Type":"Battery and Portable Power"}', 'Powerbase-70
LP-E6 regulator block
Quick-release plate
Charger', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3635, 6, 224, 'Switronix Powerbase-70 for Panasonic GH5 and GH4', 'switronix-powerbase-70-for-panasonic-gh5-and-gh4', 'The Switronix Powerbase-70 is a 77Wh 14.8 V lithium-ion battery pack designed to provide additional battery life for the Panasonic GH5 and GH4. Key features include:

Extends battery life
Two D-Tap connectors
Allows handheld use
Excellent value

Extended Battery Life. The Powerbase-70 provides nearly six times the battery life of the DMW-BLF19 battery that comes with the GH5, Panasonic GH5 w/V-Log, and GH4 camera bodies.

D-Tap Connectors. It features two D-Tap connectors, allowing you to power up to two additional 12 V accessories.

Handheld Use. The Powerbase-70 attaches to the bottom of the camera via 1/4"-20 quick-release plate so you can work without a large setup. It also has the flexibility of a 12-inch DC cable if you’re mounting it to a large support rig.', 96000.0, '{"Brand":"Switronix","Item Type":"Power","Power Type":"Battery, Charger, and Kit"}', 'Powerbase-70
GH4 regulator block
Quick-release plate
Charger', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
