INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3653, 2, 236, 'TTArtisan 50mm f/1.4 ASPH for Leica M', 'ttartisan-50mm-f-1-4-asph-for-leica-m', 'The TTArtisan 50mm f/1.4 ASPH for Leica M is a very fast, compact normal-length prime for Leica M-mount rangefinder cameras. Key features include:

Great for portraiture, reportage, and landscapes
Great low-light performance
Advanced optical design; twelve-blade diaphragm
