INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3678, 2, 227, 'Tamron 20mm f/2.8 Di III OSD M 1:2 for Sony E', 'tamron-20mm-f-2-8-di-iii-osd-m-1-2-for-sony-e', 'The Tamron 20mm f/2.8 Di III OSD M 1:2 for Sony E is a versatile wide-angle prime designed for full-frame Sony E-mount cameras. Key features include:

