INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3693, 2, 227, 'Tamron 35mm f/1.8 SP Di VC USD for Nikon F', 'tamron-35mm-f-1-8-sp-di-vc-usd-for-nikon-f', 'Tamron—a company known for their budget-friendly zooms—introduces their first semi-wide angle prime lens, the Tamron 35mm f/1.8 SP Di VC USD. Key features include:

