INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3714, 4, 229, 'Tentacle Sync Tentacle to 3-Pin XLR 16-inch Cable', 'tentacle-sync-tentacle-to-3-pin-xlr-16-inch-cable', 'The Tentacle Sync to 3-Pin XLR 16-inch Cable is an add-on accessory for the Tentacle Sync E and Tentacle Sync E MK II timecode generators that allows users to run an audio timecode signal into cameras that feature a 3-pin XLR audio input. The cable is 16-inches long.', 32000.0, '{"Brand":"Tentacle Sync","Cable Type":"Audio and Sync","Connector":"3-Pin XLR and 3.5mm TRS","Item Type":"Cable","Length":"1.3’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
