INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3717, 4, 229, 'Tentacle Sync Tentacle to DIN 1.0/2.3 Cable', 'tentacle-sync-tentacle-to-din-1-0-2-3-cable', 'The Tentacle Sync Tentacle to DIN 1.0/2.3 Cable is an adapter cable for feeding timecode from any Tentacle Sync E or ORIGINAL generators. It feeds devices with a DIN 1.0/2.3 input, including the Canon EOS R5 C or Atomos UltraSync ONE TCG. You can also jam-sync any Tentacle device from an external timecode source with a DIN 1.0/2.3 connector.', 43000.0, '{"Brand":"Tentacle Sync","Cable Type":"Audio and Sync","Connector":"3.5mm","Item Type":"Cable","Length":"1.0’"}', 'Tentacle to
