INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3810, 3, 233, 'Tilta 15mm LWS Rod Lens Support', 'tilta-15mm-lws-rod-lens-support', 'The Tilta 15mm LWS Rod Lens Support really should be part of any videographer’s basic tool kit. This is so true that we include it with most of our larger cinema lenses. Never hurts to have a spare though!

Snaps On to LWS 15mm Support Rods
