INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3833, 3, 233, 'Tilta Camera Cage Basic Kit for Sony BURANO', 'tilta-camera-cage-basic-kit-for-sony-burano', 'The Tilta Camera Cage Basic Kit for Sony BURANO bundles all the components needed to outfit your BURANO camera with durable armor and multiple mounting points. Key features include:

Aluminum and steel construction
Maintains access to camera controls
Modular camera cage
