INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3850, 6, 233, 'Tilta L-Series Battery Plate', 'tilta-l-series-battery-plate', 'The Tilta L-Series Battery Plate mounts seamlessly to your full or half camera cage from Tilta to deliver NP-F or L-Series battery power to your camera, devices, and accessories. Key features include:

(2) DC barrel accessory power outputs
Aluminum & stainless steel construction
