INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3872, 4, 233, 'Tilta Nucleus-M D-Tap to 7-Pin Motor Power Cable 29-inch', 'tilta-nucleus-m-d-tap-to-7-pin-motor-power-cable-29-inch', 'This 29" Nucleus-M D-Tap to 7-Pin Motor Power Cable from Tilta is designed to power your Nucleus-M lens control motor using a D-Tap power source.

We rent the Tilta Nucleus-M D-Tap to 7-Pin Motor Power Cable 29-inch to power your Tilta Nucleus M lens control motor as part of the Tilta Nucleus-M Wireless Lens Control System. Please note that if you are renting additional motors from us, a 7-pin motor-to-motor cable will be included with the Tilta Nucleus-M Motor Add-On Kit, and additional D-Tap cables are not required.', 71000.0, '{"Brand":"Tilta","Cable Type":"Power and Control","Connector":"D-Tap and LEMO","Item Type":"Cable","Length":"2.4’"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
