INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3885, 6, 233, 'Tilta Power Supply Base Plate for Select DJI Gimbals', 'tilta-power-supply-base-plate-for-select-dji-gimbals', 'This Tilta Power Supply Base Plate for Select DJI Gimbals allows you to power your DJI RS 2, RS 3, or RS 3 Pro gimbal with a Gold Mount battery, V-Mount battery, or external power source that provides a D-Tap port. This base plate connects to the base of the gimbal and provides you with 1/4"-20 and 3/8"-16 threaded holes to mount safely on tripods, sliders, and other support accessories. One of the 1/4"-20 threaded holes is surrounded by anti-twist divots to prevent twisting while mounted, while the included side bracket provides extra support.', 79000.0, '{"Brand":"Tilta","Dimensions":"2.8 × 1.9 × 1.7″","Item Type":"Power","Material":"Aluminum Alloy","Mounting":"1x 1/4\\"-20 Female with Anti-Twist Divots 2x 1/4\\"-20 Female 2x 3/8\\"-16 Female","Power":"Power SourceBattery DC Input Power14.4 VDC","Power Type":"Battery, Battery Plate, and Battery Base"}', 'Tilta
