INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3893, 3, 233, 'Tilta Rear Accessory Mounting Plate for Canon C400', 'tilta-rear-accessory-mounting-plate-for-canon-c400', 'The Tilta Rear Accessory Mounting Plate for Canon C400 is expands the mounting capabilities of your Canon C400 camera without the need for a full cage setup. This versatile plate is crafted from lightweight aluminum and steel and attaches to the rear of the cameras using four captive screws. For accessory mounting, you have access to multiple 1/4"-20 and 3/8"-16 mounting threads.', 36000.0, '{"Brand":"Tilta","Camera Support Type":"Baseplate","Color":"Black","Item Type":"Camera Support","Material":"Aluminum, Steel","Mounting":"Multiple 1/4\\"-20 Threads Multiple 3/8\\"-16 Threads"}', 'Tilta
