INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3901, 3, 233, 'Tilta Vertical Mounting Plate for Sony FX6', 'tilta-vertical-mounting-plate-for-sony-fx6', 'The Tilta Vertical Mounting Plate for Sony FX6 is an aluminum and stainless steel mounting plate designed to mount accessories to the side of your FX6. The plate provides multiple 1/4"-20 and 3/8"-16 threads and a shoe mount to safely connect accessories, like lights and monitors, to the camera.', 29000.0, '{"Brand":"Tilta","Camera Support Type":"Baseplate","Compatibility":"Sony FX6 Camera Tilta Quick Release Baseplate for Sony FX6 ES-T20-QRBP","Dimensions":"1.8 × 1.6 × 1.2″","Item Type":"Camera Support","Material":"Aluminum, Stainless Steel","Mounting":"Multiple 1/4\\"-20 Threads Multiple 3/8\\"-1 Threads 1x Shoe Mounts"}', 'Tilta
