INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3969, 2, 234, 'Tokina Vista 6-Lens Kit (Sony E)', 'tokina-vista-6-lens-kit-sony-e', 'The Tokina Vista 6-Lens Kit (Sony E) features a complete focal range set of fast, Sony E-mount cinema prime lenses that are compatible with cameras using up to full-frame sized sensors. All the lenses in Tokina’s Cinema Vista series have the same front lens diameters, focus, and iris ring positions, allowing for super-fast lens changes just by swinging your matte box and dropping your follow focus without moving their positions. Feel free to click any of the below highlighted links for additional information and specifications!

