INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3976, 6, 235, 'Tripp Lite Isobar 6-Outlet Ultra Surge Protector', 'tripp-lite-isobar-6-outlet-ultra-surge-protector', 'The Tripp Lite Isobar 6-Outlet Ultra Surge Protector is a durable, metal-housing designed to protect up to six connected electronics. Key features include:

3330 joule energy rating
Six outlet surge protection
97,000 amp maximum spike current protection
Integrated 6ft power cable

Electronic Protection Made SImple. Fear surrounding power spikes and surges during demanding productions can be set to the side using this Tripp Lite Isobar 6-Outlet Ultra Surge Protector! Sporting six total three prong GFCI outlets for a variety of devices, this surge protector boasts a stunning 3330 joule energy rating and 97,000 amp maximum spike current protection, ensuring no damaging electrical bursts happen through unpredictable times. Its integrated 6-foot power cable gives you ample room for positioning your equipment.', 75000.0, '{"Brand":"Tripp Lite","Dimensions":"7 × 2.5 × 3.5″","General":"Surge Energy Rating3330 joules BatteryNone Typical Backup RuntimeNone Audible AlarmNone Agency CertificationsUL1449, UL1283, UL1363, cUL, Exceeds IEEE 587 Category A&B Specifications CompatibilityUniversal","Input/Output Voltage":"InputAC: 120VAC, 50/60Hz Output6x AC OutletsAC: 120VAC, 12A, 1440W","Item Type":"Power","Mfr. Model Number":"#ISOBAR6 ULTRA","Power Type":"Surge Protector"}', 'Tripp
Lite
Isobar 6-Outlet
Ultra
Surge
Protector', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3977, 4, 44, 'USB 3.1 Type-C to USB Female OTG Adapter Cable', 'usb-3-1-type-c-to-usb-female-otg-adapter-cable', 'The USB 3.1 Type-C to USB Female OTG Adapter Cable connects USB Type A devices and peripherals to a USB-C equipped system.

We recommend this adapter cable for use with our switchers and memory card readers when working with newer computers.

It adheres to the USB 3.0 standard, so it can transfer data at up to 5 Gb/s. It also supports up to 3 A of power output so you can recharge your device via a computer or wall adapter. Its EM and RF shielding prevents interference from nearby devices.', 7000.0, '{"Brand":"CableToLink","Cable Type":"USB, Power, and Control","Connector":"USB-A and USB-C","Item Type":"Cable"}', 'Just the adapter cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (3978, 6, 237, 'Ulanzi BG-2 6800mAh Power Bank Handgrip', 'ulanzi-bg-2-6800mah-power-bank-handgrip', 'Get 6800mAh of extended CLUTCH power — in your hand and when you need it. The Ulanzi BG-2 Power Bank Handgrip is a 5-inch grip that lets you extend your device’s battery life while providing a 1/4"-20 screw on top for attachments. Key features include:

Rechargeable 6800mAh battery
USB Type-C port
