INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4000, 3, 242, 'Vello CS-BH2 Ball Head with Shoe Mount', 'vello-cs-bh2-ball-head-with-shoe-mount', 'The Vello CS-BH2 Ball Head with Shoe Mount mounts directly to a camera hot shoe or accessory cold shoe receiver. Key features include:

4.4-pound load capacity
Under 3 inches tall
90-degree articulation
Single-knob adjustment

This is a small ball head designed for pairing monitors, small lights, or small mics to any camera with a hot shoe. It will also mount to any accessory or cage that is equipped with a cold shoe receiver. It has a simple design with a single locking knob for 90-degree articulation. It connects to monitors and small lights with a fixed 1/4"-20 screw. The cold shoe on the bottom of this ball head offers a 1/4"-20 threaded port for connecting to light stands. It is also removable, revealing a 3/8"-16 thread mount point with step-down 1/4"-20 bushing for expanded stand compatibility.', 29000.0, '{"Brand":"Vello","Camera Support Type":"Ball Head","General":"Mounting1/4\\"-20 fixed screw top3/8\\"-16 bottom mount with 1/4\\"-20 bushingRemovable bottom cold shoePayload4.4 lb.Range90º articulationMfr. Model NumberCS-BH2Dimensions2.6 × 2 × 1.2″Weight3.8 oz.","Item Type":"Camera Support"}', 'Vello
CS-BH2 ball head
Cold shoe mount
	1/4"-20 bushing', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4001, 4, 242, 'Vello TTL-Off-Camera Flash Cord for Canon', 'vello-ttl-off-camera-flash-cord-for-canon', 'The Vello TTL-Off-Camera Flash Cord for Canon is a three-foot-long E-TTL extension cord for shooting your flash from a camera bracket on Canon-mount cameras.', 21000.0, '{"Brand":"Vello","Cable Type":"Lighting","Item Type":"Cable"}', 'Just the flash cord', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
