INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4007, 2, 243, 'Venus Optics 24mm T8 Pro2be 35° Probe (Canon EF)', 'venus-optics-24mm-t8-pro2be-35deg-probe-canon-ef', 'The Venus Optics 24mm T8 Pro2be 35° Probe (Canon EF) is an angled probe lens with a Canon EF mount. Key features include:

35° view lens
Covers full frame format
360° rotation at lens mount
Waterproof down to 14.4"

