INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4042, 2, 243, 'Venus Optics Laowa 12mm f/2.8 Zero-D for Canon', 'venus-optics-laowa-12mm-f-2-8-zero-d-for-canon', 'The Venus Optics Laowa 12mm f/2.8 Zero-D for Canon is an ultra-wide angle prime lens for Canon EF-mount and APS-C cameras. Key features include:

Canon EF mount
Great for architecture, landscape, and low-light photography
High-quality optical design
Accurate, fully manual focusing

Canon EF mount. This ultra-wide angle lens was designed for use on full-frame Canon EF-mount cameras. You can also use it on APS-C cameras, where it gives you a 19.2mm-equivalent focal length.

