INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4101, 2, 243, 'Venus Optics Laowa 25mm f/2.8 2.5-5X Ultra-Macro (E)', 'venus-optics-laowa-25mm-f-2-8-2-5-5x-ultra-macro-e', 'The Venus Optics Laowa 25mm f/2.8 2.5-5X Ultra Macro is a third-party specialty lens designed for Sony E-mount cameras. Key features include:

