INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4118, 2, 243, 'Venus Optics Laowa 8-15mm f/2.8 Fisheye for Canon RF', 'venus-optics-laowa-8-15mm-f-2-8-fisheye-for-canon-rf', 'The Venus Optics Laowa 8-15mm f/2.8 Fisheye for Canon RF is a unique full-frame lens designed with a stunningly close minimum focusing distance and a broad angle of view, creating immersive and artistic photo and video. Key features include:

