INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4167, 2, 243, 'Venus Optics Laowa Ranger 75-180mm T2.9 FF Cine Zoom (E)', 'venus-optics-laowa-ranger-75-180mm-t2-9-ff-cine-zoom-e', 'The Venus Optics Laowa Ranger 75-180mm T2.9 FF Cine Zoom (E) is a versatile short-to-mid telephoto cine zoom for Sony E-mount cameras. Key features include:

