INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4185, 2, 245, 'Viltrox AF 85mm f/1.4 Pro FE for Sony E', 'viltrox-af-85mm-f-1-4-pro-fe-for-sony-e', 'The Viltrox AF 85mm f/1.4 Pro FE for Sony E is a compact prime lens offering excellent compression level, sharpness, and autofocus performance designed to support portrait photography.  Key features include:

