INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4209, 2, 248, 'Voigtlander 40mm f/2 Ultron SL IIS Aspherical for Nikon F', 'voigtlander-40mm-f-2-ultron-sl-iis-aspherical-for-nikon-f', 'The Voigtlander 40mm f/2 Ultron SL IIS Aspherical is a versatile, slightly wide prime for Nikon F-mount cameras. Key features include:

