INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4222, 5, 248, 'Voigtlander VM-E Close Focus Adapter for Leica M to Sony E', 'voigtlander-vm-e-close-focus-adapter-for-leica-m-to-sony-e', 'The Voigtlander VM-E Close Focus Adapter is a specialty lens adapter that allows Leica M lenses to be mounted to Sony E-mount cameras and camcorders.  Key features include:

