INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4259, 4, 254, 'Wooden 36” RED Male LEMO to Female Pogo LCD/EVF Cable', 'wooden-36-red-male-lemo-to-female-pogo-lcd-evf-cable', 'The Wooden 36” RED Male LEMO to Female Pogo LCD/EVF Cable is a flexible cable that’s designed to go from a DSMC2 monitor/electronic viewfinder to a DSMC brain. Key features include:

