INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4262, 5, 254, 'Wooden 4 x 5.65 Zip Box (110-115mm)', 'wooden-4-x-5-65-zip-box-110-115mm', 'The Wooden Zip Box is a simple, lightweight solution for using 4 × 5.65 filters with larger cinema lenses. Key features include:

For lenses with a 110-115mm front diameter
