INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4268, 6, 254, 'Wooden ALEXA Mini Gold Mount D-Box Battery Plate', 'wooden-alexa-mini-gold-mount-d-box-battery-plate', 'The Wooden ALEXA Mini Gold Mount D-Box is a rail mounted Gold Mount battery plate and power distribution system customized for the ARRI ALEXA Mini, and only the ALEXA Mini. Key features include:

