INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4279, 3, 254, 'Wooden Camera 15mm LWS Baseplate for RED KOMODO', 'wooden-camera-15mm-lws-baseplate-for-red-komodo', 'The Wooden Camera Top Mount Kit for RED KOMODO is a camera-specific handle kit that adds an adjustable top handle and a 1/4"-20 monitor mount to the RED KOMODO 6K Key features include:

