INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4288, 5, 254, 'Wooden Camera ARRI LPL-Mount Lens to Canon RF-Mount Adapter', 'wooden-camera-arri-lpl-mount-lens-to-canon-rf-mount-adapter', 'The Wooden Camera ARRI LPL-Mount Lens to Canon RF-Mount Adapter allows an RF mounted camera to connect to an ARRI lens. Key features include:

For Canon RF-Mount cameras
