INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4293, 4, 254, 'Wooden Camera D-Tap to Canon C200 / C200B / C300II 24-inch', 'wooden-camera-d-tap-to-canon-c200-c200b-c300ii-24-inch', 'The Wooden Camera D-Tap to Canon C200 / C200B / C300II 24-inch Cable is an add-on accessory for the Canon EOS C300 Mark II Dual Pixel – EF, C300 Mark II – PL, Canon EOS C200 EF Cinema Camera, and C200 PL that allows the camera to be powered by batteries and battery plates featuring d-tap ports. This rental is for the d-tap cable only.', 61000.0, '{"Brand":"Wooden Camera","Cable Type":"Power","Connector":"D-Tap","Item Type":"Cable"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4294, 6, 254, 'Wooden Camera D-Tap to Nikon EN-EL15 Power Adapter 20-inch', 'wooden-camera-d-tap-to-nikon-en-el15-power-adapter-20-inch', 'This is the Wooden Camera D-Tap to Nikon EN-EL15 Power Adapter 20-Inch to power select Nikon DSLRs and mirrorless cameras from a Wooden Camera Gold Mount Pro Battery Plate or Wooden Camera V-Mount Pro Battery Plate.

We rent the Wooden Camera D-Tap to Nikon EN-EL15 Power Adapter 20-Inch to power select Nikon DSLRs and mirrorless cameras from a Wooden Camera Gold Mount Pro Battery Plate or Wooden Camera V-Mount Pro Battery Plate (not included). A 15mm LWS rail system with rear facing rods is recommended to best utilize those battery plates. Please note that your camera or device’s battery compartment needs to be able to accommodate the attached cable.

This d-tap cable works with:

