INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4317, 5, 254, 'Wooden Camera PL Lens to Micro 4/3 Pro Adapter', 'wooden-camera-pl-lens-to-micro-4-3-pro-adapter', 'The Wooden Camera PL Lens to Micro 4/3 Pro Adapter allows you to mount cine-style PL-mount lenses to a Micro 4/3 camera. Key features include:

Mounts PL cine lenses to Micro 4/3 cameras
