INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4318, 5, 254, 'Wooden Camera PL Lens to Sony E Adapter', 'wooden-camera-pl-lens-to-sony-e-adapter', 'The Wooden Camera PL Lens to Sony E Adapter is a PL lens adapter for Sony E-mount cameras and camcorders. Key features include:

Mount PL lenses on Sony E cameras
Manual aperture and focus
Excellent value

