INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4326, 3, 254, 'Wooden Camera Trigger Handle for RED DSMC2', 'wooden-camera-trigger-handle-for-red-dsmc2', 'The Wooden Camera Trigger Handle for RED DSMC2 is a multi-mount handle designed to start and stop recording on DSMC2 brains, like the RED RAVEN, without having to move your hand from the handle to touch the camera body. The trigger handle attaches quickly and without any tools thanks to two 1/4-20" thumbscrews, and it offers multiple 1/4"-20 threads, 3/8"-16 threads, and ARRI anti-twist 3/8"-16 threads.', 121000.0, '{"Brand":"Wooden Camera","Camera Support Type":"Handle","Item Type":"Camera Support"}', 'Wooden
