INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4333, 3, 254, 'Wooden Camera Unified Bridgeplate (19mm)', 'wooden-camera-unified-bridgeplate-19mm', 'The Wooden Camera Unified Bridgeplate (19mm) is an ARRI standard bridge plate with 19mm studio rods spaced 104mm center-to-center.

The Wooden Camera Unified Bridgeplate (19mm) can be converted from RED standard height to ARRI standard height, making it compatible with any type of camera rig. The rubberized top coating prevents twisting and slotted design accommodates non-standard screw spacing.

When combined with Unified Baseplates, it offers correct rod height on cameras like the Sony FS7M2, FS5M2, FX9, and Venice, Canon’s C100 Mark II, C300 Mark II, C300 Mark III, and C500 Mark II, Blackmagic URSA Mini Pro, Panasonic VariCam LT, and risers for RED DSMC2 HELIUM and GEMINI.', 104000.0, '{"Brand":"Wooden Camera","Camera Support Type":"Baseplate","Item Type":"Camera Support"}', '19mm
