INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4370, 4, 254, 'Wooden LCD/EVF Cable for RED DSMC/DSMC2 Cameras (36")', 'wooden-lcd-evf-cable-for-red-dsmc-dsmc2-cameras-36', 'The Wooden LCD/EVF 36-inch for DSMC/DSMC2 Brains is a 3-foot extension cable for compatible DSMC and DSMC2 brains and accessories. Key features include:

Compatible with RED 16-pin LCD/EVF connections
One right-angle connector to minimize wire clutter
Durable, braided cable
Great for gimbal work

Convenient LCD Offset. This 3-foot extension cable for RED DSMC and DSMC2 cameras and accessories using the 16-pin 1B LCD/EVF connection gives you the freedom to mount your monitor away from the camera for gimbal work or remote viewing.

First Gen DSMC. This cable directly replaces the included cable in our RED Touch 7-inch LCD package.

DSMC2 Compatibility. While this is not compatible with any of RED’s second generation cable-less accessories, it is a great option for the DSMC2 Ultra-Brite 7-inch Touch LCD or the DSMC2 OLED EVF. Please note, this cable requires a 16-pin connection from the camera. If you are renting a DSMC2 brain from us, a compatible LEMO A adapter is already included.', 89000.0, '{"Brand":"Wooden Camera","Cable Type":"RED","Item Type":"Cable"}', 'Just the cable', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4371, 3, 254, 'Wooden Open Cage Accessory Kit for Sony FX3 / FX3A / FX30', 'wooden-open-cage-accessory-kit-for-sony-fx3-fx3a-fx30', 'The Wooden Open Cage Accessory Kit for Sony FX3 / FX3A / FX30 is a scalable camera cage and baseplate system that is built around, and fully compatible with, Sony’s XLR-H1 Handle Unit. Key features include:

For Sony FX3 / FX30 and XLR handle unit
