INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4372, 3, 254, 'Wooden Quick Kit for Canon EOS C100/C300/C500', 'wooden-quick-kit-for-canon-eos-c100-c300-c500', 'The Wooden Camera Quick Kit for Canon C100/300/500 cameras is a complete mounting solution with rods. Key features include:

