INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4417, 5, 256, 'Z CAM Lens Mount for E2 Flagship Series (Leica M)', 'z-cam-lens-mount-for-e2-flagship-series-leica-m', 'The Z CAM Lens Mount for E2 Flagship Series (Leica M) is just what the name implies, a Leica M lens mount, that’s designed for use with select Z Cam cameras. Key features include:

Durable locking mount for Leica M lenses
Compatible with Z Cam E2 Flagship cameras
Easy to install
No shims required

Compatibility. The Z CAM Lens Mount for E2 Flagship Series (Leica M) is designed for the Z Cam E2-S6, E2-F6, E2-F8, and E2-M4 cameras and allows users to natively connect Leica M mount lenses to their camera.

Durable Build. Easy Install. This lightweight lens mount is machined to provide a secure, locking connection between your lens and camera and is easily installed with four screws and an allen wrench.', 75000.0, '{"Brand":"Z Cam","Item Type":"Lens Support","Lens Support Type":"Mount Adapter"}', 'Leica
M lens mount
Lens mount cap
Hardware kit', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4418, 5, 256, 'Z CAM Lens Mount for E2 Flagship Series (PL)', 'z-cam-lens-mount-for-e2-flagship-series-pl', 'The Z CAM Lens Mount for E2 Flagship Series (PL) is just what the name implies, a PL lens mount, that’s designed for use with select Z Cam cameras. Key features include:

Durable locking mount for PL lenses
Compatible with Z Cam E2 Flagship cameras
Easy to install
