INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4428, 4, 257, 'Zacuto 4-Pin LEMO Power/Video Cable for Kameleon EVF 30-inch', 'zacuto-4-pin-lemo-power-video-cable-for-kameleon-evf-30-inch', 'The 30" Zacuto 4-Pin LEMO Power/Video Cable for Kameleon EVF is designed to power the Zacuto Kameleon EVF. Key features include:

BNC & 4-Pin LEMO to BNC & D-Tap
Powers switch on D-Tap connector
Single molded sheathing w/ divided ends
For Kameleon EVF Pro

