INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4430, 3, 257, 'Zacuto Add-On Handgrip for Recoil', 'zacuto-add-on-handgrip-for-recoil', 'The Zacuto Add-On Handgrip for Recoil is just as it sounds, a second handgrip for any of our Zacuto Recoil kits. Key features include:

