INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4431, 3, 257, 'Zacuto DSLR Handle', 'zacuto-dslr-handle', 'The Zacuto DSLR Handle is an add-on accessory for rail support systems. Key features include:

