INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4575, 2, 258, 'Zeiss Milvus ZE 18mm f/2.8 for Canon', 'zeiss-milvus-ze-18mm-f-2-8-for-canon', 'The Zeiss Milvus ZE 18mm f/2.8 for Canon is a high-quality manual-focus lens designed for Canon DSLRs, and an update to the popular Zeiss ZE 18mm f/3.5. Key features include:

