INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4577, 2, 258, 'Zeiss Milvus ZE 25mm f/1.4 for Canon', 'zeiss-milvus-ze-25mm-f-1-4-for-canon', 'The Zeiss Milvus ZE 25mm f/1.4 for Canon is a high-quality manual-focus wide-angle prime designed for Canon EF-mount DSLRs. Key features include:

