INSERT INTO products (id, category_id, brand_id, name, slug, description, base_price, specifications, accessories_included, created_at, updated_at) VALUES (4580, 2, 258, 'Zeiss Milvus ZE 50mm f/1.4 for Canon', 'zeiss-milvus-ze-50mm-f-1-4-for-canon', 'The Zeiss Milvus ZE 50mm f/1.4 is a professional-caliber, fast-aperture prime lens designed for Canon EF-mount cameras and update to the popular Zeiss ZE 50mm f/1.4 for Canon. Key features include:

Excellent low-light performance; shallow depth of field
